//! Model process pool — manages one subprocess per loaded ModelId.
//!
//! When a model is unloaded, its worker process is killed and the OS/CUDA
//! driver reclaims all GPU memory immediately — no restart required.

use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;

use dashmap::DashMap;
use tokio::process::Child;
use tokio::sync::{mpsc, Mutex};
use uuid::Uuid;

use crate::error::SwarmError;
use crate::inference::router::StreamingTokenEvent;
use crate::inference::worker_ipc::*;
use crate::model::auto_manage::vram::KvCharge;
use crate::types::{ModelId, PrefixBlockEntry, SamplingParams};

/// Cross-platform IPC stream halves between daemon and model worker.
/// Unix: AF_UNIX socket with 0o600 filesystem perms (current user only).
/// Windows: named pipe with default DACL (current logon session only).
///
/// Both halves hold the one stream through an `Arc`: `&Stream` reads and
/// writes, so neither half needs a lock. Dropping one half closes nothing —
/// the stream closes once both are gone. Nothing here relies on a half-close:
/// a retired worker is told `DaemonMsg::Shutdown` and killed, and a Windows
/// pipe's halves never closed on drop anyway.
///
/// Prior art: interprocess 2.4.7 deprecated its own `split()` for this shape,
/// and tokio's `UnixStream::into_split` halves are built the same way.
pub(crate) struct IpcReader(Arc<interprocess::local_socket::tokio::Stream>);
pub(crate) struct IpcWriter(Arc<interprocess::local_socket::tokio::Stream>);

impl IpcWriter {
    /// A second handle on the same stream, for ONE writer that writes only
    /// while the caller's `&mut` borrow of this one is held — so frames never
    /// interleave: `model_worker::PromptProgressOut::open` (#430), whose window
    /// holds that borrow and drops the handle when it closes.
    pub(crate) fn second_handle(&mut self) -> IpcWriter {
        IpcWriter(Arc::clone(&self.0))
    }
}

/// The one place a connected IPC stream becomes its two halves — the
/// daemon's end in `spawn_worker` and the worker's in `run_worker`.
pub(crate) fn split_ipc(
    stream: interprocess::local_socket::tokio::Stream,
) -> (IpcReader, IpcWriter) {
    let stream = Arc::new(stream);
    (IpcReader(Arc::clone(&stream)), IpcWriter(stream))
}

impl tokio::io::AsyncRead for IpcReader {
    fn poll_read(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &mut tokio::io::ReadBuf<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        std::pin::Pin::new(&mut &*self.0).poll_read(cx, buf)
    }
}

impl tokio::io::AsyncWrite for IpcWriter {
    fn poll_write(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<std::io::Result<usize>> {
        std::pin::Pin::new(&mut &*self.0).poll_write(cx, buf)
    }

    fn poll_write_vectored(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        bufs: &[std::io::IoSlice<'_>],
    ) -> std::task::Poll<std::io::Result<usize>> {
        std::pin::Pin::new(&mut &*self.0).poll_write_vectored(cx, bufs)
    }

    fn is_write_vectored(&self) -> bool {
        tokio::io::AsyncWrite::is_write_vectored(&&*self.0)
    }

    fn poll_flush(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        std::pin::Pin::new(&mut &*self.0).poll_flush(cx)
    }

    fn poll_shutdown(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        std::pin::Pin::new(&mut &*self.0).poll_shutdown(cx)
    }
}

/// Item 8 Phase 1: each prefix-cache insert in a worker emits one of these
/// over the pool's `prefix_manifest_tx`. The daemon-side forwarder drains
/// the channel, broadcasts a `SwarmMessage::PrefixCacheAnnounce`, and folds
/// the blocks into the local cross-node index (so a single-node loopback
/// test sees the wire path end-to-end).
#[derive(Clone, Debug)]
pub struct PrefixManifestEvent {
    pub model_id: ModelId,
    pub blocks: Vec<PrefixBlockEntry>,
}

/// Progress on a request that has not produced its first token yet. Workers
/// emit one per prefill chunk; the daemon-side forwarder stamps it onto the
/// request's `RequestTrace`, which is what every surface reads from.
#[derive(Clone, Debug)]
pub struct ProgressEvent {
    pub request_id: Uuid,
    pub phase: crate::inference::worker_ipc::ProgressPhase,
    pub done: u32,
    pub total: u32,
    /// Where the pass began reading — the positions before it came from the
    /// cache (`WorkerMsg::Progress::from`, #430).
    pub from: u32,
}

/// Item 8 Phase 2b: worker-initiated cross-node prefix-KV probe. The
/// daemon's probe handler (`daemon::background`) drains these off the
/// channel, fetches from a peer inside the request's scope
/// (`pool::scope::request_scope`), and sends the (possibly empty) result
/// back via `ModelProcessPool::send_prefix_fetch_result`.
#[derive(Clone, Debug)]
pub struct PrefixProbeEvent {
    pub model_id: ModelId,
    pub request_id: Uuid,
    pub blocks: Vec<PrefixBlockEntry>,
    /// The probing request's caller asked to keep it on this computer
    /// (#251 (2b)) — the scope the daemon asks is that request's.
    pub keep: crate::types::KeepAsked,
}

const WORKER_CONNECT_TIMEOUT_SECS: u64 = 30;

/// How long a split's spawn waits for its worker's card reading
/// (`DaemonMsg::ReadCardFree`, #365). The worker opens its card context to
/// answer, which a working driver does in under a second here (WSL2 included);
/// past this the split keeps the placement it was first given, and the load
/// reads the card itself as it always has.
const CARD_FREE_READ_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(20);

/// How long a growth waits for its live worker's reading of what its pool
/// holds freed (`DaemonMsg::ReadCardFree` → `WorkerMsg::CardFree`, #481 (5)).
/// The worker answers between messages, and a growth is asked between a
/// request's forwards; past this the growth is weighed without the pool's
/// room, as it was before.
const GROWTH_CARD_READ_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(3);

/// Where a live worker's answer to a growth's `DaemonMsg::ReadCardFree` goes:
/// set by [`WorkerHandle::pool_reusable_mb`] before it asks, taken by the
/// reader actor when `WorkerMsg::CardFree` arrives (its `reusable_bytes`).
type CardFreeAsked = Arc<std::sync::Mutex<Option<tokio::sync::oneshot::Sender<Option<u64>>>>>;

/// Ask a worker that has just connected for the card's free memory as its load
/// will read it, and wait for the answer (#365). Run before the reader actor
/// owns `reader`, so the answer comes straight back here. `Ok(None)`: the
/// worker has no card, or did not answer in [`CARD_FREE_READ_TIMEOUT`]; an
/// `Err` is a connection that broke, which no spawn can use.
async fn read_card_free_before_the_load<R, W>(
    reader: &mut R,
    writer: &mut W,
    model_id: &ModelId,
) -> std::io::Result<Option<u64>>
where
    R: tokio::io::AsyncReadExt + Unpin,
    W: tokio::io::AsyncWriteExt + Unpin,
{
    send_daemon(writer, &DaemonMsg::ReadCardFree, &[]).await?;
    let answer = tokio::time::timeout(CARD_FREE_READ_TIMEOUT, async {
        loop {
            match recv_worker(reader).await {
                Ok((WorkerMsg::CardFree { free_bytes, .. }, _)) => return Ok(free_bytes),
                // Nothing is sent unasked before a load, but a side-band
                // report is no reason to give up on the answer.
                Ok((other, _)) => tracing::debug!(
                    model = %model_id,
                    message = ?other,
                    "A model worker sent something else while the card was being read"
                ),
                // A newer worker's message, read whole: the stream is aligned.
                Err(e) if unknown_worker_msg(&e).is_some() => {}
                Err(e) => return Err(e),
            }
        }
    })
    .await;
    match answer {
        Ok(read) => read,
        Err(_elapsed) => {
            tracing::warn!(
                model = %model_id,
                waited_secs = CARD_FREE_READ_TIMEOUT.as_secs(),
                "The model's worker did not say how much graphics memory is free — placing the \
                 split as first planned"
            );
            Ok(None)
        }
    }
}

/// A worker [`ModelProcessPool::spawn_worker`] started, and — for a
/// card/processor split — the card's free memory as its load will read it
/// ([`read_card_free_before_the_load`]); `None` where it was not asked or
/// could not say.
struct SpawnedWorker {
    handle: WorkerHandle,
    card_free_bytes: Option<u64>,
}

/// What a spawn's split is sized again by
/// (`ModelProcessPool::refit_split_to_the_load`, #365).
#[derive(Debug, Clone, Copy)]
struct SplitRefit {
    /// The model's card estimate whole, as admission priced it.
    estimated_mb: u64,
    /// The card budget the first plan was weighed against.
    budget_mb: u64,
    /// The card's free memory as the worker's load will read it.
    load_reads_free_bytes: u64,
    /// The cache the spawn charges for.
    kv: KvCharge,
}

/// What a spawn's WHOLE card placement is weighed again by
/// (`ModelProcessPool::fit_whole_placement_to_the_load`, #322).
#[derive(Debug, Clone, Copy)]
struct WholeRefit {
    /// The card's free memory as the worker's load will read it.
    load_reads_free_bytes: u64,
    /// The cache the spawn charges for — the one the load must leave room for.
    kv: KvCharge,
    /// Whose request the spawn is for: the machine's share of a split made
    /// here meets that requester's cap.
    requester: Requester,
}

/// How long a best-effort broadcast to one worker may wait, per step.
///
/// Matches the bound the worker-reply waits already use. A fire-and-forget
/// message is a few dozen bytes into a socket buffer, so this is never reached
/// by a worker that is reading at all — it exists to put a ceiling on one that
/// has stopped. See [`ModelProcessPool::notify_every_worker`].
const WORKER_NOTIFY_TIMEOUT_MS: u64 = 2000;

/// Exponential backoff for repeat worker-spawn failures: 1s, 2s, 4s, 8s,
/// 16s, 32s, capped at 60s. The arriving request gets `ModelNotAvailable`
/// during the cooldown window, so a permanently-broken model can't drown
/// the inference path in 30-second connect timeouts.
fn spawn_failure_cooldown(consecutive_failures: u32) -> std::time::Duration {
    let secs = match consecutive_failures {
        0 | 1 => 1,
        2 => 2,
        3 => 4,
        4 => 8,
        5 => 16,
        6 => 32,
        _ => 60,
    };
    std::time::Duration::from_secs(secs)
}
/// Default KV-cache TTL in seconds (10 minutes). Overridden by config at startup.
pub const DEFAULT_KV_CACHE_TTL_SECS: u64 = 600;

/// How long after its last forward a reply's conversation keeps its worker in
/// use ([`WorkerHandle::in_use`]).
///
/// An INACTIVITY bound, not a deadline on the reply: a live reply touches the
/// worker once per token, seconds apart (3-10 s per token measured on the
/// slowest chains here), and its coordinator gives up on a decode step long
/// before two minutes. What needs a bound at all is the conversation served
/// for a REMOTE coordinator — this node is never told that reply finished, so
/// without one a model that answered a peer once would count as busy for the
/// whole cache TTL, and a small machine would refuse its own owner's request
/// for memory for ten minutes. A reply silent past this and then resumed on a
/// retired worker is refused by the worker (`forward_lacks_its_conversation`),
/// visibly — never decoded from nothing.
///
/// The worker reads the same figure for its own caches: one this silent gives
/// way when a live conversation needs the room
/// (`KvCacheStore::release_finished_conversations`).
pub(crate) const CONVERSATION_GAP_SECS: u64 = 120;

/// Does `forward` begin a prompt pass at its first position — the forward a
/// re-plan of the request sends first (#481 (5))? Not a cache truncation, not
/// a later piece of a pass (`prompt_span`), not a pass resumed past what a
/// segment kept (#10: its `index_pos` is past 0).
fn starts_a_pass(forward: &crate::types::LayerForward) -> bool {
    forward.index_pos == 0
        && forward.truncate_kv_to.is_none()
        && forward.prompt_span.is_none_or(|span| span.start == 0)
}

/// The `DaemonMsg::AdmitPrompt` a peer's question becomes
/// ([`ModelProcessPool::weigh_peer_prompt`]): weighed only, under a FRESH
/// correlation id — the worker routes its answer by it — and naming the
/// request it weighs for, whose own earlier caches the pass replaces (#448).
fn peer_question(
    model_id: &ModelId,
    layer_ranges: Vec<(u32, u32)>,
    prompt_tokens: u32,
    for_request: Uuid,
) -> IpcAdmitPrompt {
    IpcAdmitPrompt {
        request_id: Uuid::new_v4(),
        model_id: model_id.clone(),
        layer_ranges,
        prompt_tokens,
        only_weigh: true,
        weighs_for: Some(for_request),
    }
}

/// What a worker said to one `DaemonMsg::AdmitPrompt`
/// ([`ModelProcessPool::send_admission`]).
enum Admission {
    /// No live worker runs the model: nothing loaded to weigh.
    NoWorker,
    /// No answer within `UP_FRONT_ADMISSION_WAIT`: the worker is busy.
    Busy,
    Admitted {
        handle: Arc<WorkerHandle>,
    },
    Refused {
        message: String,
        layers_that_fit: u32,
    },
}

/// This node's answer to a peer's question about a prompt
/// ([`ModelProcessPool::weigh_peer_prompt`], FUTURE_WORK #252 (b)).
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum PeerPromptWeight {
    /// It would fit — or nothing here can say it would not.
    Fits,
    /// It would not: the worker's words, how many of the asked layers fit,
    /// and whether they are the layers that LOAD from the first asked one or
    /// the layers whose caches fit (`swarmllm_types::LayersCounted`).
    DoesNotFit {
        message: String,
        layers_that_fit: u32,
        counted: swarmllm_types::LayersCounted,
    },
}

/// How many refusals `ModelProcessPool::layers_refused` holds before it drops
/// the stale ones. The router takes each entry within a second of the refusal,
/// so anything older than [`LAYERS_REFUSED_FOR`] is one no router will take.
const LAYERS_REFUSED_KEPT: usize = 64;
const LAYERS_REFUSED_FOR: std::time::Duration = std::time::Duration::from_secs(600);
/// How long a pipeline waits for its up-front admission before going ahead
/// without it (`ModelProcessPool::admit_prompt`). Not a bound on the work —
/// the answer is a budget sum and one device reading, milliseconds — but on how
/// long this request's peers may be held while our worker finishes ANOTHER
/// request's forward, which the old per-segment admission never waited for.
pub(crate) const UP_FRONT_ADMISSION_WAIT: std::time::Duration = std::time::Duration::from_secs(1);

/// How long a live card reading stands for a plan
/// ([`ModelProcessPool::card_budget_for_planning`]): one plan asks the card
/// budget a dozen times within milliseconds, and one `nvidia-smi` answers them
/// all (0.1-0.5 s on WSL2).
const PLANNING_CARD_READING_FOR: std::time::Duration = std::time::Duration::from_secs(2);

/// Per-request buffered channel capacity for multiplexed worker responses.
/// Long decode streams emit one WorkerMsg::Token per generated token; 256 gives
/// plenty of headroom for a caller that's slow to consume without stalling the
/// reader actor.
const RESPONSE_CHANNEL_CAPACITY: usize = 256;

/// Response channel entry: a bounded mpsc sender carrying `(WorkerMsg, payload_bytes)`.
type ResponseTx = mpsc::Sender<(WorkerMsg, Vec<u8>)>;

/// Shared map from `request_id` to the caller's response channel, tagged with
/// a unique per-attempt token. The reader actor looks up each inbound message's
/// `request_id` here to route the reply.
///
/// The token exists because a `request_id` is NOT unique across concurrent
/// attempts: a router retry re-sends the *same* id while the
/// original is still in flight. Keyed by id alone, the retry's insert silently
/// dropped the original's sender and the original's cleanup then removed the
/// retry's — killing both. See `WorkerHandle::register_response`.
type ResponseMap = Arc<DashMap<Uuid, (u64, ResponseTx)>>;
/// Where the card budget is read from now (`ModelProcessPool::vram_budget_now`).
type VramBudgetSource = Box<dyn Fn() -> Option<u64> + Send + Sync>;

/// Source of per-attempt tokens for `ResponseMap`. Process-wide; only equality
/// matters, never ordering.
/// One GPU-resident model considered for reclaim, as the planner sees it.
#[derive(Debug, Clone)]
struct VramReclaimCandidate {
    model: ModelId,
    /// What admission has charged for it — the figure the budget is spent in.
    charge_mb: u64,
    /// Idle as the request asking for the room sees it
    /// ([`WorkerHandle::idle_secs_for`], #483 (a)).
    idle_secs: u64,
    /// A request is in flight against it right now.
    busy: bool,
    /// It has guessed for another model's request
    /// (`WorkerHandle::drafts_for_another_model`): never a split's (#355).
    drafts: bool,
    /// Every model it has guessed for is the model being placed
    /// (`WorkerHandle::guesses_only_for`) — the one drafter a WHOLE placement
    /// may take ([`split_reclaim_eligible`], #442).
    guesses_only_for_the_placed: bool,
}

/// Choose which resident models to unload so `needed_mb` fits in `budget`.
///
/// Pure so the policy can be tested without spawning a worker: the wiring is
/// verified by running the node, this decides what the wiring does.
///
/// Returns an EMPTY plan when the request cannot be satisfied even by
/// reclaiming everything eligible: unloading models and still not fitting
/// WHOLE buys this admission nothing. What it buys a model the card then holds
/// part of is [`plan_vram_reclaim_for_split`]'s question, asked next.
fn plan_vram_reclaim(
    budget_mb: u64,
    committed_mb: u64,
    needed_mb: u64,
    candidates: Vec<VramReclaimCandidate>,
) -> Vec<(ModelId, u64)> {
    if committed_mb.saturating_add(needed_mb) <= budget_mb {
        return Vec::new();
    }
    let mut eligible: Vec<VramReclaimCandidate> = candidates
        .into_iter()
        .filter(vram_reclaim_eligible)
        .collect();
    // Most idle first: `spawned_at` cannot tell a worker answering steadily for
    // an hour from one loaded an hour ago and never used since.
    eligible.sort_by_key(|a| std::cmp::Reverse(a.idle_secs));

    let mut plan = Vec::new();
    let mut freed = 0u64;
    for c in eligible {
        if committed_mb.saturating_sub(freed).saturating_add(needed_mb) <= budget_mb {
            break;
        }
        freed = freed.saturating_add(c.charge_mb);
        plan.push((c.model, c.charge_mb));
    }
    if committed_mb.saturating_sub(freed).saturating_add(needed_mb) > budget_mb {
        return Vec::new();
    }
    plan
}

/// Choose which idle models to unload so more of a model the card holds only
/// PART of runs there (#355): `on_card_with(mb)` is how many of its layers the
/// card/processor split puts on the card with `mb` more card memory than
/// stands free.
///
/// [`plan_vram_reclaim`] frees nothing unless the model then fits WHOLE —
/// written when a model that did not fit went to the processor whatever was
/// freed. A split's card share grows with every layer's worth freed, and a
/// layer on the card runs several times faster than on the processor, so an
/// idle model kept beside a split costs every token of the split. Ollama
/// unloads idle runners before it settles for a partial offload
/// (`server/sched.go`: a load that would not fit whole beside the others
/// `needEvict`s, `findRunnerToUnload` taking an idle runner first).
///
/// Same candidates, predicate and order (most idle first), and only as many
/// as it takes to reach what reclaiming every eligible model would give: a
/// model whose memory adds no layer stays loaded. Empty when none adds one.
/// A drafter is taken only for a whole placement of the one model it guesses
/// for ([`split_reclaim_eligible`]).
fn plan_vram_reclaim_for_split(
    candidates: Vec<VramReclaimCandidate>,
    placing: SplitFor,
    on_card_with: impl Fn(u64) -> usize,
) -> Vec<(ModelId, u64)> {
    let mut eligible: Vec<VramReclaimCandidate> = candidates
        .into_iter()
        .filter(|c| split_reclaim_eligible(c, placing))
        .collect();
    eligible.sort_by_key(|a| std::cmp::Reverse(a.idle_secs));
    let all = eligible
        .iter()
        .fold(0u64, |sum, c| sum.saturating_add(c.charge_mb));
    let most = on_card_with(all);
    if most <= on_card_with(0) {
        return Vec::new();
    }
    let mut plan = Vec::new();
    let mut freed = 0u64;
    for c in eligible {
        freed = freed.saturating_add(c.charge_mb);
        plan.push((c.model, c.charge_mb));
        if on_card_with(freed) >= most {
            break;
        }
    }
    plan
}

/// May the pool take the card back from this model for another one?
///
/// **The single answer**, read by the reclaim itself ([`plan_vram_reclaim`]) and
/// by the planner's view of room ([`ModelProcessPool::max_local_hostable_layers`])
/// — a planner that credited memory admission would then refuse to reclaim
/// would plan a segment the loader turns down.
fn vram_reclaim_eligible(c: &VramReclaimCandidate) -> bool {
    !c.busy && c.charge_mb > 0 && c.idle_secs >= vram_make_room_min_idle_secs()
}

/// What a card/processor split is made for: the whole model here, or a part
/// of it. A drafter's memory turns on it ([`split_reclaim_eligible`], #442).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SplitFor {
    /// Every layer of the model, here: a local generation, which no engine
    /// drafter guesses for (`try_dsd_distributed` is a split route's).
    Whole,
    /// A segment of a split route, which a drafter here may guess for.
    Part,
}

/// May a card/processor split take the card back from this model? As
/// [`vram_reclaim_eligible`], and never from a worker that guesses for another
/// model (`WorkerHandle::drafts_for_another_model`, #355): a split gains a few
/// layers where the model the drafter serves loses its speed-up — EXCEPT where
/// the split places the whole model it guesses for, and nothing else (#442):
/// a whole model here is a local generation, which reads no drafter, so the
/// drafter protects nothing while it keeps that model's layers off the card
/// (field report v0.3.280's run on v0.3.278: a 3B drafter left by a split
/// route held a 12 GB card, and the same 14B then loaded with 10 of 48 layers
/// there at 5.5 tok/s). Prior art: llama.cpp's server and vLLM load a drafter
/// with its target and free it with it — a drafter outliving its use holds
/// memory nothing reads. The single answer, read by the split's reclaim
/// ([`plan_vram_reclaim_for_split`]) and by the planner's count of it
/// (`ModelProcessPool::idle_vram_reclaimable_for_split_mb`).
fn split_reclaim_eligible(c: &VramReclaimCandidate, placing: SplitFor) -> bool {
    vram_reclaim_eligible(c)
        && (!c.drafts || (placing == SplitFor::Whole && c.guesses_only_for_the_placed))
}

/// Rounds [`ModelProcessPool::get_or_spawn`] may take before giving up: each
/// one that ends empty means another task replaced the worker in between, so
/// more than a couple is contention, not progress.
const GET_OR_SPAWN_ROUNDS: usize = 3;

/// A live worker's budget would not take a range it was asked to add
/// (`ModelProcessPool::charge_additional_segment`), with what reclaiming room
/// for it — or replacing the worker — needs to know.
#[derive(Debug)]
struct GrowthRefused {
    /// What the range would ADD, net of the ranges it subsumes.
    needed_mb: u64,
    /// Which budget refused: the card, or system memory.
    on_gpu: bool,
    /// What the worker had been charged when it refused, read under
    /// `spawn_lock`. A later figure that differs means another request grew
    /// the same worker in between — it is that request's now.
    worker_charged_mb: u64,
    /// The refusal as the caller reports it.
    error: SwarmError,
}

/// [`ModelProcessPool::retirement_decision`]'s answer.
#[derive(Debug, PartialEq, Eq)]
enum Retirement {
    /// Nothing is using it and nobody grew it since it refused: replace it.
    Retire,
    /// In use, or grown by another request since: keep it, refuse ours.
    Keep,
    /// The map holds a different worker now; the spawn path will find it.
    AlreadyReplaced,
}

/// What [`ModelProcessPool::grow_worker`] did about a range a live worker had
/// not held before.
enum Growth {
    /// The worker now holds it — use this handle.
    Grown(Arc<WorkerHandle>),
    /// The worker was idle and no part of the range fit its card, so it was
    /// retired: spawn afresh for the range, where admission weighs it with the
    /// worker's card memory given back — and can put it on the processor.
    Respawn,
}

/// What `ModelProcessPool::charge_segment_as_split`, growth's split rung, did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SplitRung {
    /// The worker now holds the range across the card and the processor.
    Took,
    /// No part of the range fits the card, or the split cannot be priced.
    Declined,
    /// It stood aside so an idle worker is retired and the range placed afresh
    /// (#461): the range takes in, or partly overlaps, one the worker holds.
    SteppedAside,
}

/// How long a GPU-resident model must have gone unused before another model
/// may take the card from it.
///
/// **Protects a model under active use from being displaced. It is not thrash
/// prevention, and it was measured that thrash prevention is not worth buying.**
///
/// It was 60 s, invented on the reasoning that two models alternating faster
/// than they load would evict each other on every request. Measured on
/// 2026-08-28 — two models alternating in multi-turn conversation on one card,
/// same binary, floor 60 s against floor 0 s: **299 s against 82 s, a 3.65x
/// loss.** An external tester's one-shot measurement on different hardware had
/// already found the same direction (8.1 s on the processor against 2.5 s to
/// swap and run). Both arms are in `docs/FUTURE_WORK.md`.
///
/// Two things that measurement showed, both against my own prior reasoning:
///
/// - **The swap is the cheap side.** A reload plus re-prefill on the card cost
///   7-14 s per turn; the same model on the processor cost 15-20 s per turn
///   *with* a warm prefix cache, and 230 s for its first. I had argued the
///   opposite — that discarding the prefix cache on eviction would eat the gain
///   — and the multi-turn case I said would show it is the case that refutes it.
/// - **Idle time cannot express "is swapping worth it".** Under alternation the
///   incumbent has always just been used, so an idle-time floor is inert or
///   total and never in between: at 60 s no swap ever happened and one model
///   held the card indefinitely while the other ran on the processor for the
///   whole conversation.
///
/// So this is now only what an idle-time predicate *can* honestly do: refuse to
/// take the card from a model still in active use, on top of the in-flight
/// check that `plan_vram_reclaim` already applies. Sized to a few seconds of
/// continuing traffic rather than to the cost of a load — a model being asked
/// something every few seconds keeps the card; one that has gone quiet for the
/// length of a turn gives it up.
///
/// Costing the swap properly — load time against what the processor would cost
/// for this model — is the real answer and needs per-model figures for both;
/// `docs/FUTURE_WORK.md` carries it with the measurements that justify it.
const VRAM_MAKE_ROOM_MIN_IDLE_SECS_DEFAULT: u64 = 5;

/// [`WorkerHandle::owner_last_used`] before the owner's first request, and
/// [`WorkerHandle::promotion_refused_ms`] before the card first refused it.
const NEVER_USED: u64 = u64::MAX;

/// How long a retirement waits after the last hand-out of the worker it
/// retires ([`WorkerHandle::handed_out_ms`]) before it judges whether a
/// request is still in flight. A request holding the handle registers its
/// reply without an await in between (`forward_direct`, `generate_attempt`,
/// `draft`, `forward_batch`), so this is microseconds of work given a quarter
/// of a second for a thread the scheduler set aside (#483 (a) F2).
const HAND_OUT_GRACE: std::time::Duration = std::time::Duration::from_millis(250);

/// How long a worker is idle before peers are told it would give way to
/// another model's work (`ModelProcessPool::gives_way`, #447). One capability
/// round (the health monitor broadcasts every 30 s): a worker used between two
/// rounds is not offered in the next, so a model in steady use never flaps in
/// and out of the advertisement — and by the time a peer acts on the figure the
/// worker has been idle well past the reclaim's own floor
/// ([`VRAM_MAKE_ROOM_MIN_IDLE_SECS_DEFAULT`]), so admission takes the room.
const GIVES_WAY_AFTER_IDLE_SECS: u64 = 30;

/// `SWARMLLM_GIVES_WAY=0` tells peers no idle worker's room — the
/// advertisement before #447, for A/B inside one binary.
fn gives_way_advertised() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        !matches!(
            std::env::var("SWARMLLM_GIVES_WAY").ok().as_deref(),
            Some("0")
        )
    })
}

/// `SWARMLLM_VRAM_SWAP_MIN_IDLE_SECS` — pin the floor, for A/B measurement.
///
/// Same discipline as `SWARMLLM_DECODE_THREADS` and `SWARMLLM_DECODE_ATTN`:
/// both arms must be the same binary or the comparison measures the build.
/// `=0` makes every swap eligible, `=60` restores the old constant. Kept out of
/// `config/default.toml` deliberately — it exists to measure the policy, not to
/// hand users a dial in place of one.
fn vram_make_room_min_idle_secs() -> u64 {
    static CACHED: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
    *CACHED.get_or_init(|| {
        match std::env::var("SWARMLLM_VRAM_SWAP_MIN_IDLE_SECS")
            .ok()
            .and_then(|v| v.parse::<u64>().ok())
        {
            Some(secs) => {
                tracing::info!(
                    secs,
                    default = VRAM_MAKE_ROOM_MIN_IDLE_SECS_DEFAULT,
                    "SWARMLLM_VRAM_SWAP_MIN_IDLE_SECS override in force"
                );
                secs
            }
            None => VRAM_MAKE_ROOM_MIN_IDLE_SECS_DEFAULT,
        }
    })
}

/// A whole placement its load's reading split (#322): the free graphics memory
/// the load would have had to read more for the whole model to keep the
/// spawn's cache inside the loader's line, and the card budget when it split.
/// The budget is the card less what OTHER programs hold
/// (`vram::compute_vram_budget`), so a rise in it is room another program
/// gave back — the one thing that can make the same load read enough.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SplitByTheLoad {
    short_by_mb: u64,
    budget_at_split_mb: u64,
}

/// Everything the "should this worker go back to the card?" decision looks at.
///
/// Pure, for the same reason [`plan_vram_reclaim`] is: the policy can then be
/// tested without spawning a worker or owning a GPU, and the method that
/// gathers these values does nothing but gather them.
#[derive(Debug, Clone, Copy)]
struct PromotionInputs {
    /// This node put the running worker on the processor (`--gpu-layers 0`),
    /// or split it between the card and the processor, for want of card
    /// memory — the two placements a card with more room would not have made.
    short_of_the_card: bool,
    /// A reason this model would go to the processor again whatever the memory
    /// situation: the user's own `gpu_layers = 0`, or a card below this build's
    /// kernel floor. **A VRAM pin is deliberately NOT one of them** — that is
    /// the condition this whole decision exists to reconsider.
    permanently_cpu_bound: bool,
    /// [`ModelProcessPool::cpu_reason`] still has an answer — most often a VRAM
    /// pin nothing has lifted yet. It is the predicate the respawn reads FIRST,
    /// so while it holds, a retired worker comes straight back on the
    /// processor: the pin is reconsidered once it is LIFTED, never while it
    /// stands. Leaving this out retired a pinned model's worker on every
    /// forward of a split reply (`docs/FUTURE_WORK.md` #93).
    reason_still_holds: bool,
    /// The worker is in use: a response in flight, or a request's cache held
    /// between two forwards ([`WorkerHandle::in_use`]).
    busy: bool,
    idle_secs: u64,
    /// The idle time the asker waits for before the worker is weighed: the
    /// swarm's request waits [`vram_make_room_min_idle_secs`] — a gap in the
    /// traffic, as before — and the owner's none (#483 (a) F2): the owner's
    /// back-to-back asks (an agent's loop, a nightly's four) never left one,
    /// so a model placed short of the card once stayed there for all of
    /// them. A retirement waits for the request it was last handed to
    /// ([`HAND_OUT_GRACE`]), which is what the floor stood in for.
    idle_floor_secs: u64,
    /// A card reading refused it within the last
    /// [`vram_make_room_min_idle_secs`] — set only where there is no floor,
    /// so the card is read at most that often for one worker.
    refused_lately: bool,
    /// What the card would have to give it, as admission priced it.
    gpu_estimate_mb: u64,
    /// The most this node's card budget could ever be — no other program
    /// holding any of it (`inference_vram_budget_mb` with nothing else on the
    /// card); 0 when unknown. A model above it can never move whole, so the
    /// card is not read for that: a 14B split on an 8 GB card asks on every
    /// request. Only a worker wholly on the processor is read for past it, and
    /// only while the ceiling could hold half of it — a split may still move
    /// it ([`may_move_as_a_split`], #498).
    ceiling_mb: u64,
    /// Card memory the worker already holds and gives back when it is
    /// retired — a split's share of the card (`card_share_of_split_mb`); 0 for
    /// a worker on the processor.
    own_card_mb: u64,
    budget_mb: u64,
    committed_mb: u64,
    /// Megabytes the pool would be willing to reclaim from OTHER models right
    /// now, from a dry run of `plan_vram_reclaim` — so this asks whether the
    /// model fits in the room that can be made, not only in the room lying
    /// about. The plan carries its own guards (idle floor, in-flight, and
    /// all-or-nothing), so a non-zero figure is memory the pool has already
    /// agreed it may take.
    reclaimable_mb: u64,
    /// The worker's [`SplitByTheLoad`], when its load's reading split a
    /// placement admission made whole.
    split_by_the_load: Option<SplitByTheLoad>,
    /// The worker runs every layer on the processor
    /// ([`WorkerHandle::placed_on_cpu_because`]) — not a split. Only such a
    /// worker is moved for a card SPLIT (#498): one already split moves only
    /// whole, so a promotion never trades one split for another.
    wholly_on_the_processor: bool,
    /// For a worker wholly on the processor: the spawn's own split of the
    /// asked range in the room as it stands ([`ModelProcessPool::partial_gpu_layers`],
    /// less the plan's other ranges here, as the spawn leaves them) —
    /// [`CardSplit::card_share`]'s `(on the card, of)`. `None` where it was not
    /// weighed, or where the card takes none of it.
    split_would_place: Option<(usize, usize)>,
    /// This worker was spawned by a promotion that retired the one before it,
    /// and landed wholly on the processor all the same
    /// ([`WorkerHandle::promotion_missed`]): the promotion's arithmetic and the
    /// spawn's disagreed, so this worker is not moved for a split again — a
    /// cold reload a request, for nothing, is the loop #93 was.
    promotion_missed: bool,
    /// A card/processor split is offered at all ([`hybrid_offload_on`]).
    splits_offered: bool,
}

/// Should this processor-resident worker be retired so the model reloads onto
/// the graphics card?
///
/// **The alternative to acting is a model stuck on the processor for as long as
/// it stays resident.** A GPU OOM (or a momentarily full card) pins a model to
/// the CPU; freeing memory lifts the pin; and nothing then re-examined the
/// worker that pin had produced. `get_or_spawn`'s fast path returns any
/// resident worker regardless of device, and the CPU worker survives until
/// `idle_unload_secs` (15 minutes) of *no requests at all* — which a user
/// actively working with the model never reaches. So lifting the pin bought
/// nothing for the model it was lifted for. Reported by an external tester
/// 2026-08-27: llama-3.2-3b took the card, gemma-2-2b-it spawned on the
/// processor 35 s later, the idle-unload then freed llama and logged `GPU
/// memory freed — clearing CPU pins`, and re-requesting gemma against an idle
/// card (653 of 6141 MB in use) reused the processor worker.
///
/// Four guards, three of them carried over from [`plan_vram_reclaim`] because
/// this destroys something that is working and they are what makes that safe:
///
/// - **Only a worker this node demoted** — to the processor, or to a
///   card/processor split (`short_of_the_card`). On a machine with no card it
///   is false and there is nowhere to promote to. The split was left out until
///   2026-10-13 (#260): admission splits a model before it gives up the card,
///   so a model squeezed by another program was far more often split than sent
///   to the processor — the report's Mistral 7B ran 1.4 GB of itself on the
///   card at 12.7 tok/s, 55 once unloaded and reloaded whole. A split's own
///   share of the card (`own_card_mb`) is given back by retiring it, and a
///   model larger than the card could ever give (`ceiling_mb`) is never
///   weighed for a WHOLE move — only one wholly on the processor, for a split,
///   while that ceiling could hold half of it ([`may_move_as_a_split`], #498).
/// - **The reason must actually be gone** (`reason_still_holds`). Of the three
///   causes in [`ModelProcessPool::cpu_reason`], only the OOM pin ever clears —
///   when another model's worker frees the card, or when its hold runs out
///   (`CpuPins`, field report 2026-10-31) — and this is asked at the next
///   request rather than polled for.
///   This bullet was written long before it was checked: the function used to
///   ask only whether the estimate fit, so a model still pinned was retired,
///   respawned on the processor by that same pin, and retired again.
/// - **Never a worker in use, and for the swarm's request not one used inside
///   [`vram_make_room_min_idle_secs`].** Unloading kills the subprocess, and a
///   request that arrives between the check and the kill would die with it.
///   The retirement itself closes that window: it waits [`HAND_OUT_GRACE`] past
///   the worker's last hand-out and then for every reply in flight
///   ([`ModelProcessPool::unload_model`]). The idle floor stays for the swarm's
///   request — a model under a peer's continuous load waits for a gap in the
///   traffic rather than charge a peer's request a cold load — and is waived
///   for the owner's (#483 (a) F2): back-to-back asks never leave a gap, so a
///   model placed short of the card once stayed there for all of them. "In
///   use" includes a reply holding its cache between two forwards
///   ([`WorkerHandle::in_use`]): the gap between tokens is not a gap in the
///   traffic.
/// - **Cost the move before making it.** Retiring a worker and then failing
///   admission costs a cold start and buys nothing, so the model must fit the
///   budget as it stands *now*. An unreadable estimate (0) or an unset budget
///   is not evidence, and leaves the model where it is.
/// - **A split its load's reading made waits for the card to gain what the
///   load lacked** ([`SplitByTheLoad`], #322). The room admitted that model
///   whole, so on the room alone it would be retired at its first idle
///   request, spawned whole, and split again by the same reading — a cold
///   load paid by that request for nothing. The budget now must exceed the
///   budget it was split at by the shortfall; the worker's own share is not
///   added back — the budget never counted it (it is the card less OTHER
///   programs' memory), so adding it would promote every such split at once.
fn should_return_to_gpu(i: &PromotionInputs) -> bool {
    if !promotion_is_worth_weighing(i) || i.budget_mb == 0 {
        return false;
    }
    if let Some(split) = i.split_by_the_load {
        let gained = i.budget_mb.saturating_sub(split.budget_at_split_mb);
        if gained < split.short_by_mb {
            return false;
        }
    }
    let held_by_others = i
        .committed_mb
        .saturating_sub(i.own_card_mb)
        .saturating_sub(i.reclaimable_mb);
    i.gpu_estimate_mb <= i.budget_mb.saturating_sub(held_by_others) || moves_for_a_card_split(i)
}

/// **A worker wholly on the processor moves for a card SPLIT too** (#498):
/// where the spawn would now put at least half its layers on the card
/// ([`PromotionInputs::split_would_place`] — the spawn's own arithmetic, so
/// the respawn does what was weighed). Only whole moves were weighed, so a
/// slice placed on the processor while the card was busy, and too big for the
/// card whole, stayed there for the worker's life: Qwen3.8-27B's 47 layers on
/// the Australian computer at ~6.6 ms a layer beside 10 GB of its card free,
/// the user's 27B route at 2.3-3.7 tokens a second (2026-11-23). Half, so the
/// cold reload a promotion costs buys at least a halving of that hop's step.
///
/// Prior art: llama.cpp fixes `--n-gpu-layers` at load, and Ollama places a
/// model's layers when it loads and moves none later — the room a card frees
/// is used only once the model is loaded again. Our worker can be replaced
/// between replies, so it is: the same moment the whole move already uses.
fn moves_for_a_card_split(i: &PromotionInputs) -> bool {
    may_move_as_a_split(i)
        && i.split_would_place
            .is_some_and(|(on_card, of)| of > 0 && on_card.saturating_mul(2) >= of)
}

/// Could a worker move to the card as a split at all, before the card is read
/// for it: wholly on the processor, not already missed once, splits offered
/// (`SWARMLLM_HYBRID_OFFLOAD`, [`hybrid_offload_on`]), and a ceiling that could
/// hold at least half its estimate — past that no room the card ever has puts
/// half its layers there, and reading the card for it on every request is what
/// the ceiling guard exists to stop (review of #498 (b), 2026-11-23).
fn may_move_as_a_split(i: &PromotionInputs) -> bool {
    i.wholly_on_the_processor
        && !i.promotion_missed
        && i.splits_offered
        && (i.ceiling_mb == 0 || i.ceiling_mb.saturating_mul(2) >= i.gpu_estimate_mb)
}

/// Is a model offered a card/processor split at all? `SWARMLLM_HYBRID_OFFLOAD=0`
/// turns it off ([`crate::model::auto_manage::vram::hybrid_offload_off`], the
/// one reading of that switch).
fn hybrid_offload_on() -> bool {
    !crate::model::auto_manage::vram::hybrid_offload_off()
}

/// Does a promotion's replacement, spawned for `asked`, hold at least what the
/// worker it retires holds (`held`)? The promotion is weighed on the WORKER's
/// estimate — the card has room for everything it holds — but the slow path
/// spawns the range the request asked for. Asked for a slice of a whole copy
/// short of the card, it threw the rest away: the far computer of a 14B split
/// held `[0..48)` with 45 layers on its card, the split's first forward asked
/// `[23..48)` seconds after its last whole reply (past the promotion's 5 s idle
/// floor), the copy was replaced by `[23..48)` alone, all on its card, and the
/// next whole reply reloaded the model with 17 of its layers on the card:
/// hand-offs fell from 24 to 9-10 tokens a second for the rest of the session
/// (real link `TAG=j11`, its peer snapshots, 2026-11-13; the same shape on
/// `TAG=j5`, `j7`, `j9`, `j10` — inferred from the far side's broadcasts, its
/// own log unseen). A worker serves a slice of what it holds (#449), so it
/// serves it as it stands, and is promoted by a request for everything it
/// holds. Ollama never re-places a loaded runner while it can serve the
/// request (`server/sched.go` `needsReload`). An empty `held` keeps nothing.
fn promotion_keeps_what_it_holds(held: &[(u32, u32)], asked: (u32, u32)) -> bool {
    held.iter()
        .all(|&(start, end)| start >= end || (asked.0 <= start && end <= asked.1))
}

/// The guards of [`should_return_to_gpu`] that need no reading of the card —
/// so the card is read only for a worker that could actually move
/// ([`ModelProcessPool::promotion_weighed`]).
fn promotion_is_worth_weighing(i: &PromotionInputs) -> bool {
    i.short_of_the_card
        && !i.permanently_cpu_bound
        && !i.reason_still_holds
        && !i.busy
        && i.idle_secs >= i.idle_floor_secs
        && !i.refused_lately
        && i.gpu_estimate_mb != 0
        // Above the card's ceiling a model never moves WHOLE; one wholly on
        // the processor may still move as a split (#498), so it is weighed.
        && (i.ceiling_mb == 0 || i.gpu_estimate_mb <= i.ceiling_mb || may_move_as_a_split(i))
}

/// How long a model whose card ran out of memory stays on the processor before
/// the card is weighed for it again, the first time.
const PIN_HOLD_FIRST: std::time::Duration = std::time::Duration::from_secs(120);

/// The longest that hold grows to.
const PIN_HOLD_MOST: std::time::Duration = std::time::Duration::from_secs(30 * 60);

/// A card that fails the same model again within this long of the last pin
/// ending doubles the next hold.
const PIN_REPEAT_WITHIN: std::time::Duration = std::time::Duration::from_secs(30 * 60);

/// A worker that ran this long before its card failed it failed a long
/// CONVERSATION, not its load: the next pin starts over at `PIN_HOLD_FIRST`
/// instead of doubling (field report 2026-11-04: a 14B that ran 5-12 min on its
/// card before each failure was held 120, 240, 480, then 960 s). Kubernetes
/// resets CrashLoopBackOff the same way once a container has run 10 min without
/// trouble; this is shorter because the failure the doubling guards against is
/// a load that fails within its first requests, and the creep this pin meets
/// most fails after 5-7 min of one chat (#367 (d)) — at 10 min every one of
/// those would double. Measured from the worker's spawn, so a load slower than
/// this costs at most one load per `PIN_HOLD_FIRST`, never one per request.
const PIN_CLEAN_RUN: std::time::Duration = std::time::Duration::from_secs(3 * 60);

/// Models sent to the processor because their card FAILED them
/// (`classify_worker_error`), and for how long.
///
/// **A memory pin ENDS** (field report 2026-10-31): a 14B alone on a 12 GB
/// card ran out of memory after ~5 min of one chat, was pinned, and stayed on
/// the processor at a fifth of its speed until it was unloaded by hand. The pin
/// used to clear only when ANOTHER model's worker gave graphics memory back —
/// and the worker that ran out is evicted before its pin is taken, so on a card
/// it had to itself nothing ever cleared it. llama.cpp, vLLM and SGLang pin
/// nothing: they shed cache and retry. A pin here is held for a while so a
/// model that fails at every load does not burn one load per request —
/// `PIN_HOLD_FIRST`, doubled up to `PIN_HOLD_MOST` while the card keeps failing
/// it within `PIN_REPEAT_WITHIN` of the last pin ending (the shape of
/// `peer_outliers`) and SOON after giving it back — a worker that ran
/// `PIN_CLEAN_RUN` first starts the hold over — and then it simply stops holding: `cpu_reason` no longer
/// reports it, so the promotion and any fresh spawn weigh the card as it stands
/// (admission, which takes no pin). Ending in `cpu_reason`, the one place every
/// placement asks, rather than in whichever path lifts it, is the point. A card
/// too old for this build's kernels never ends its pin.
#[derive(Debug, Default)]
struct CpuPins {
    /// Every model a card has failed, kept after its pin ends: a pin taken soon
    /// after doubles from the last one's hold. One entry per model ever pinned.
    pins: DashMap<ModelId, CpuPin>,
}

#[derive(Debug, Clone, Copy)]
struct CpuPin {
    /// When the pin stops holding; `None` = never (a card too old for this
    /// build's kernels).
    until: Option<std::time::Instant>,
    hold: std::time::Duration,
}

impl CpuPins {
    /// Pin `model_id` to the processor for `kind`; returns the hold (`None`:
    /// for good). `ran_for` is how long the worker the card failed had been
    /// running (`None`: no worker found — judged as one that failed at once).
    fn pin(
        &self,
        model_id: &ModelId,
        kind: crate::inference::worker_ipc::PermanentGpuFailure,
        ran_for: Option<std::time::Duration>,
    ) -> Option<std::time::Duration> {
        self.pin_at(model_id, kind, ran_for, std::time::Instant::now())
    }

    fn pin_at(
        &self,
        model_id: &ModelId,
        kind: crate::inference::worker_ipc::PermanentGpuFailure,
        ran_for: Option<std::time::Duration>,
        now: std::time::Instant,
    ) -> Option<std::time::Duration> {
        use crate::inference::worker_ipc::PermanentGpuFailure;
        let failed_soon_after_its_load = ran_for.is_none_or(|ran| ran < PIN_CLEAN_RUN);
        let hold = match self.pins.get(model_id).map(|p| *p.value()) {
            Some(CpuPin {
                until: Some(until),
                hold,
            }) if failed_soon_after_its_load && now < until + PIN_REPEAT_WITHIN => {
                hold.saturating_mul(2).min(PIN_HOLD_MOST)
            }
            _ => PIN_HOLD_FIRST,
        };
        let until = (kind != PermanentGpuFailure::ArchitectureTooOld).then(|| now + hold);
        self.pins.insert(model_id.clone(), CpuPin { until, hold });
        until.map(|_| hold)
    }

    /// Does a pin hold `model_id` on the processor right now?
    fn holds(&self, model_id: &ModelId) -> bool {
        self.holds_at(model_id, std::time::Instant::now())
    }

    fn holds_at(&self, model_id: &ModelId, now: std::time::Instant) -> bool {
        self.pins
            .get(model_id)
            .is_some_and(|p| p.until.is_none_or(|u| now < u))
    }

    /// End `model_id`'s memory pin now (graphics memory was freed); true if one
    /// held. Its hold is kept, so a failure soon after doubles it.
    fn lift(&self, model_id: &ModelId) -> bool {
        let now = std::time::Instant::now();
        self.pins
            .get_mut(model_id)
            .is_some_and(|mut p| match p.until {
                Some(u) if now < u => {
                    p.until = Some(now);
                    true
                }
                _ => false,
            })
    }

    /// End every memory pin now; the models lifted, sorted.
    fn lift_all(&self) -> Vec<String> {
        let models: Vec<ModelId> = self.pins.iter().map(|e| e.key().clone()).collect();
        let mut lifted: Vec<String> = models
            .into_iter()
            .filter(|m| self.lift(m))
            .map(|m| m.0)
            .collect();
        lifted.sort();
        lifted
    }

    /// The models a pin holds right now, sorted.
    fn ids(&self) -> Vec<String> {
        let models: Vec<ModelId> = self.pins.iter().map(|e| e.key().clone()).collect();
        let mut v: Vec<String> = models
            .into_iter()
            .filter(|m| self.holds(m))
            .map(|m| m.0)
            .collect();
        v.sort();
        v
    }

    /// End `model_id`'s hold as though its time had run out, for a test.
    #[cfg(test)]
    fn run_out(&self, model_id: &ModelId) {
        if let Some(mut p) = self.pins.get_mut(model_id) {
            if p.until.is_some() {
                p.until = Some(std::time::Instant::now());
            }
        }
    }
}

static RESPONSE_ATTEMPT_TOKEN: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

/// How many of a worker's latest decode steps its published speed is the
/// fastest of ([`OwnDecodeSpeed`]).
const OWN_DECODE_STEPS_KEPT: usize = 32;

/// Fewest decode steps a worker publishes a speed from.
const OWN_DECODE_STEPS_TO_PUBLISH: usize = 4;

/// How long after its last decode step a worker still publishes its speed; a
/// step after that starts a new window.
///
/// A figure nobody refreshes describes the worker as it was, and one that
/// prices it slow keeps away the very steps that would correct it — the ratchet
/// `peer_speed::RANKING_STALE_AFTER` exists for. Hardware does not change
/// within the hour; load does, and an hour bounds that.
const OWN_DECODE_PUBLISHED_FOR: std::time::Duration = std::time::Duration::from_secs(3600);

/// This worker's own decode speed on its model, per layer: the FASTEST of its
/// last [`OWN_DECODE_STEPS_KEPT`] single-token steps run for PEERS, each timed
/// by the pool from the forward's send to its result (FUTURE_WORK #3 (f)).
///
/// Published to the swarm as `ResidentModelLayers::decode_us_per_layer`, the
/// way a Petals server publishes the `inference_rps` it timed on the real
/// block (`petals/server/throughput.py`, kept per model, device and dtype —
/// here per worker, which is all three). A coordinator never times a peer
/// inside a chain another peer leads, so without this it priced one from its
/// stated 7B speed alone.
///
/// **The minimum, as a round trip's floor is kept (BBR's windowed min RTT;
/// `LatencyFilter` here).** Waiting only ever ADDS to a step — behind another
/// request's prompt pass, in a batch's collection window — so the fastest step
/// is the one closest to what the worker computes. A median let any peer that
/// sent this node work make it publish a slow figure for an hour, steering
/// coordinators elsewhere, by queueing half its steps behind other forwards
/// (security review, 2026-10-18); against the minimum it must slow EVERY step
/// in the window, which is the node really being that busy. It is also steady:
/// it moves only when a faster step arrives or the fastest ages out, so it
/// rarely crosses the publish deadband (`health::monitor::
/// CAPABILITY_SPEED_DEADBAND`, #91).
///
/// **Peers' work only** ([`Requester::Swarm`]): the owner's own requests are
/// not timed, so the figure says nothing about when the owner last used a
/// model — not to a peer outside a private pool either.
#[derive(Debug, Default)]
struct OwnDecodeSpeed {
    /// Microseconds per layer, oldest first.
    steps: std::collections::VecDeque<u32>,
    last_step_at: Option<std::time::Instant>,
}

impl OwnDecodeSpeed {
    /// Fold in one decode step that ran `layers` layers in `elapsed`.
    fn note(&mut self, layers: u32, elapsed: std::time::Duration, now: std::time::Instant) {
        if layers == 0 {
            return;
        }
        // A window that has stopped publishing is not resumed by one step.
        if self
            .last_step_at
            .is_some_and(|at| now.saturating_duration_since(at) > OWN_DECODE_PUBLISHED_FOR)
        {
            self.steps.clear();
        }
        let us_per_layer = elapsed.as_micros() / u128::from(layers);
        if self.steps.len() == OWN_DECODE_STEPS_KEPT {
            self.steps.pop_front();
        }
        self.steps
            .push_back(u32::try_from(us_per_layer).unwrap_or(u32::MAX).max(1));
        self.last_step_at = Some(now);
    }

    /// What this worker publishes: µs per layer, or `None` before
    /// [`OWN_DECODE_STEPS_TO_PUBLISH`] steps and once
    /// [`OWN_DECODE_PUBLISHED_FOR`] has passed without one.
    fn published(&self, now: std::time::Instant) -> Option<u32> {
        if self.steps.len() < OWN_DECODE_STEPS_TO_PUBLISH {
            return None;
        }
        if now.saturating_duration_since(self.last_step_at?) > OWN_DECODE_PUBLISHED_FOR {
            return None;
        }
        self.steps.iter().copied().min()
    }
}

/// The computers a prompt pass waiting here depends on (#448 (d)): the one that
/// SENT it (the network layer's authenticated peer, `LayerForward::sender_peer_bytes`)
/// and the coordinator it NAMES (`requester_node_id`, the sender's word). Either
/// gone, no first step will come. Naming an absent coordinator can only release
/// the namer's own pass. A pass from this node's own pipeline names this node,
/// or nobody.
#[derive(Clone, Debug, Default, PartialEq)]
pub(crate) struct PassParties {
    pub(crate) sender: Option<crate::types::NodeId>,
    pub(crate) requester: Option<crate::types::NodeId>,
}

impl PassParties {
    fn of(sender_peer_bytes: Option<&[u8]>, requester_node_id: Option<[u8; 32]>) -> Self {
        Self {
            sender: sender_peer_bytes.and_then(crate::network::transport::node_id_of_peer_bytes),
            requester: requester_node_id.map(crate::types::NodeId),
        }
    }
}

/// Whether a pass's parties have LEFT: a party counts as gone only once this
/// node has seen it in the swarm since the pass began (`seen`, one flag per
/// party). A later hop of a chain may never have the coordinator on record (a
/// gossiped capability installs only into an entry that exists —
/// `docs/invariants/network.md` § the swarm-use gate's `NotHeardFrom`), so its
/// absence proves nothing and the pass keeps the hold's own bound (review of
/// #448 (d), 2026-11-12). The SENDER starts seen, and so does a coordinator
/// that is the sender ([`AwaitedPass::seen_at_arrival`]): it has just delivered
/// the pass over a connection the network layer authenticated, as a lease is
/// granted to a live holder. Left to the first idle tick (30 s), a computer that
/// died right after sending was never seen and its pass kept the whole hold —
/// the vanished-coordinator rig killed one 0.2 s after its pass arrived.
fn a_party_left(
    parties: &PassParties,
    seen: &mut [bool; 2],
    still_here: &dyn Fn(&crate::types::NodeId) -> bool,
) -> bool {
    let mut left = false;
    for (party, seen) in [&parties.sender, &parties.requester]
        .into_iter()
        .zip(seen.iter_mut())
    {
        let Some(node) = party else { continue };
        if still_here(node) {
            *seen = true;
        } else if *seen {
            left = true;
        }
    }
    left
}

/// How long a prompt pass's sender or coordinator may be absent from the swarm
/// before the pass is released (#448 (d)) — the default idle unload's five
/// minutes, which is what such a pass was given before its hold, counted from
/// the first idle tick that finds it gone.
pub(crate) const PASS_PARTY_GONE_AFTER: std::time::Duration = std::time::Duration::from_secs(300);

/// A prompt pass sent to a worker that still awaits its first step (#448 (b)).
#[derive(Debug)]
struct AwaitedPass {
    sent: std::time::Instant,
    parties: PassParties,
    /// Whether each party (sender, requester) has been seen in the swarm since
    /// the pass began ([`a_party_left`]).
    seen: [bool; 2],
    /// The first idle tick that found a seen party gone; cleared when it is back.
    missing_since: Option<std::time::Instant>,
}

impl AwaitedPass {
    /// Who is seen the moment the pass arrives: its authenticated sender, and
    /// the coordinator where it IS the sender — never a coordinator only named.
    fn seen_at_arrival(parties: &PassParties) -> [bool; 2] {
        let sender = parties.sender.is_some();
        [sender, sender && parties.requester == parties.sender]
    }
}

/// A handle to a running model worker subprocess.
///
/// The socket is split into a shared writer (one-at-a-time under `Mutex`) and
/// a reader owned by a dedicated actor task. The reader dispatches each
/// incoming `WorkerMsg` to the per-request channel keyed by `request_id`,
/// allowing N concurrent `forward()` / `generate()` callers to interleave
/// their requests through the same worker without serializing on a single
/// full-request mutex.
struct WorkerHandle {
    /// The worker subprocess.
    ///
    /// `Option` so `Drop` can move it into a reaper task. Killing a process and
    /// the OS reclaiming its device memory are separate events, and the budget
    /// must not be handed back between them — see `exited`.
    child: Option<Child>,
    /// Set once the subprocess has actually been reaped, not merely signalled.
    ///
    /// `Child::start_kill` sends the signal and returns; the kernel tears the
    /// process down and frees its CUDA allocations afterwards. Releasing the
    /// VRAM charge on the signal made `vram_committed_mb` report zero while the
    /// card was still full, so an admission landing in that window passed
    /// against memory that did not exist and the new worker died with
    /// `CUDA_ERROR_OUT_OF_MEMORY`. Reported as an out-of-memory crash that
    /// "landed exactly when auto-manage was mid-eviction of a different model".
    exited: Arc<AtomicBool>,
    /// Write half of the IPC socket. Brief lock held only for the duration of
    /// one outbound framed message (header + optional binary payload).
    writer: Mutex<IpcWriter>,
    /// Per-request response channels. The reader actor inserts `(msg, payload)`
    /// tuples keyed by `request_id`; callers register a channel before sending
    /// their request and drain it until they get a terminal message.
    responses: ResponseMap,
    /// Set to true when the reader actor observes a socket error. Subsequent
    /// callers short-circuit with an error + trigger worker eviction.
    dead: Arc<AtomicBool>,
    /// Socket path used to connect, kept for drop-time cleanup.
    ///
    /// Unix only: the filesystem entry has to be unlinked when the worker goes
    /// away, whereas a Windows named pipe is reclaimed by the kernel once every
    /// handle closes. Carrying the field on Windows would be storing a value
    /// nothing reads, which is what the Windows lint build reports.
    #[cfg(unix)]
    socket_name: String,
    /// Handle to the reader actor task. Aborted on drop so the task doesn't
    /// outlive its worker; also unblocks any pending `recv_worker` in tests.
    reader_handle: tokio::task::JoinHandle<()>,
    /// When this worker was spawned.
    ///
    /// Idle-unload needs a floor on how long a model *could* have been idle. A
    /// model with no recorded request history is not "idle forever" — it cannot
    /// have been idle longer than it has existed. Without this, a model loaded
    /// seconds ago was evicted as though it had sat unused for the whole
    /// configured window, killing the request that had just loaded it.
    spawned_at: std::time::Instant,
    /// Seconds since this worker last had a request registered against it.
    ///
    /// `spawned_at` is only an upper bound on idleness — it cannot tell a model
    /// answering steadily for an hour from one loaded an hour ago and never
    /// used since, and those deserve opposite treatment when something has to
    /// give up the card. Stamped in `register_response`, which is the ONE place
    /// every execution path (local, distributed, peer-served) passes through,
    /// so no caller can forget it — and again when that slot closes
    /// (`ResponseGuard::used_until_now`), so a long reply is not idle the
    /// moment it ends.
    ///
    /// Stored as seconds since `spawned_at` rather than a wall-clock stamp, so
    /// a clock step cannot make a busy worker look idle for hours.
    last_used: AtomicU64,
    /// Has a request ever been registered against this worker? `last_used` is
    /// 0 both before the first and for one registered in its first second.
    /// Read by [`ModelProcessPool::model_used_secs_ago`].
    ran_a_request: AtomicBool,
    /// [`Self::last_used`] counting only THIS computer's owner's requests
    /// ([`Requester::Owner`]), stamped at the same two moments; [`NEVER_USED`]
    /// until the owner's first. What an owner's request reads as another
    /// model's idle time ([`Self::idle_secs_for`], #483 (a)).
    owner_last_used: AtomicU64,
    /// When this handle was last taken out of the pool's map — milliseconds
    /// since [`Self::spawned_at`], 0 at the spawn that hands it out first.
    /// Stamped while the map's read guard is held
    /// ([`ModelProcessPool::live_worker`], `get_existing`, `get_or_spawn_once`),
    /// so a retirement, which removes the handle under the write guard, sees
    /// every hand-out that came before it and waits [`HAND_OUT_GRACE`] past
    /// the last for its request to register ([`ModelProcessPool::unload_model`]).
    /// HikariCP's `ConcurrentBag` closes the same race by making a borrow and an
    /// idle eviction contend on one compare-and-set (#483 (a) F2).
    handed_out_ms: AtomicU64,
    /// When a card reading last refused to move this worker to the card
    /// ([`ModelProcessPool::promotion_weighed`]) — milliseconds since
    /// [`Self::spawned_at`]; [`NEVER_USED`] until then. The owner's promotion
    /// has no idle floor, so this keeps its card reading (one `nvidia-smi`,
    /// ~0.1 s) to one per [`vram_make_room_min_idle_secs`].
    promotion_refused_ms: AtomicU64,
    /// Has this worker been given anything that loads weights — a request
    /// ([`Self::register_response`]), a load ahead (`DaemonMsg::LoadRange`) —
    /// or reported a load (`WorkerMsg::ModelLoadTimed`, by the reader)? Until
    /// then it holds only the device context its spawn opened to read the card,
    /// not the share it was charged, so its retirement waits for no card
    /// memory to come back ([`DepartedWorker::card_mb_it_frees`], #3 (j13)).
    /// Set BEFORE the work is sent, so a load under way is always waited for.
    /// An `Arc`: the reader actor writes it too.
    asked_to_load: Arc<AtomicBool>,
    /// Requests whose conversation cache this worker holds BETWEEN forwards,
    /// and when each last sent one.
    ///
    /// **A distributed reply is idle between tokens and is not finished.** It
    /// reaches the worker as one forward per token, so `responses` is empty for
    /// most of its life while the worker holds its cache — and `last_used` is
    /// stamped at the START of a forward, so a slow CPU forward already reads
    /// as idle the moment it returns. Every "is this worker in use?" that read
    /// `responses` alone saw such a worker as free, and retiring it (to promote
    /// it to the card, or to reclaim memory for another model) threw the cache
    /// away mid-reply. The next forward ran on a fresh worker with nothing
    /// behind it and the reply turned to garbage without an error anywhere:
    /// GLM-4-9B, 14 retirements and 28 loads in one 96-token reply
    /// (`docs/FUTURE_WORK.md` #93, gotcha #690).
    ///
    /// Stamped by every forward, removed when the request releases its cache
    /// or is cancelled, and aged out [`CONVERSATION_GAP_SECS`] after its last
    /// forward — the one bound a conversation served for a REMOTE coordinator
    /// has, since nothing tells this node that reply finished. Read only
    /// through [`WorkerHandle::in_use`].
    kv_holders: std::sync::Mutex<std::collections::HashMap<Uuid, std::time::Instant>>,
    /// Requests whose prompt pass was sent to this worker and whose first step
    /// has not come yet, by when the pass was sent (#448 (b)) — the daemon's
    /// half of the worker's own hold (`KvCacheStore::note_forward_ran`). A
    /// split's later machines can read a long prompt for longer than the
    /// conversation gap and the idle unload, so a segment silent past 300 s
    /// was unloaded with the cache its first step needs. Written by
    /// [`WorkerHandle::note_forward_sent`], dropped with the conversation, held
    /// at most `kv_cache::PROMPT_PASS_HOLD`; read only by the idle unload
    /// ([`ModelProcessPool::models_awaiting_a_first_step`]) — never by
    /// [`WorkerHandle::in_use`], whose two minutes keep a peer's silent cache
    /// from refusing the owner's own request for memory. Prior art: Petals'
    /// server keeps a session's attention cache between steps up to a wait per
    /// step and one per session, and reports its free cache so clients route
    /// around full servers; vLLM frees a running request's blocks only when it
    /// finishes, is aborted or is preempted under pressure, never on idle time.
    /// A pass whose sender or coordinator has left the swarm is released
    /// ([`ModelProcessPool::release_abandoned_prompt_passes`], #448 (d)).
    awaiting_first_step: std::sync::Mutex<std::collections::HashMap<Uuid, AwaitedPass>>,
    /// The ranges each request's passes from position 0 were sent for on this
    /// worker since its pass began (#481 (5)). A chain sends each layer to one
    /// machine once, so a pass from 0 OVERLAPPING one of them is a new pass of
    /// the request — a re-plan keeps its id (#448) — while one beside them is
    /// the same pass's other range here (a split that starts and finishes
    /// here), whose hold is use (#93). Written by
    /// [`WorkerHandle::note_pass_range`], read and cleared by
    /// [`WorkerHandle::release_an_earlier_pass`], dropped with the
    /// conversation; an entry whose request holds nothing here goes when a
    /// range is noted. Lock order: `kv_holders` first.
    pass_ranges: std::sync::Mutex<std::collections::HashMap<Uuid, Vec<(u32, u32)>>>,
    /// Why this node put this worker on the processor — `None` means it was
    /// spawned for the graphics card.
    ///
    /// A property of the WORKER, not of the model: it records where the process
    /// actually went and why, which is the only thing still true minutes later.
    /// [`ModelProcessPool::cpu_reason`] answers for a spawn happening *now*, and
    /// the pin it consults is deliberately cleared while the worker it produced
    /// is still running — so asking it about a resident worker gives the wrong
    /// answer precisely when the answer matters, both for the promotion decision
    /// and for the dashboard's "why is this not on my GPU?".
    ///
    /// Note it is `None` on a node with no graphics card at all: nothing was
    /// demoted, there is simply nowhere else to run.
    placed_on_cpu_because: Option<CpuReason>,
    /// A promotion retired the worker before this one so the model could move
    /// to the card, and this one was placed wholly on the processor all the
    /// same — set by the spawn ([`ModelProcessPool::get_or_spawn_once`]). It is
    /// then never moved for a card split ([`PromotionInputs::promotion_missed`],
    /// #498); a whole move is weighed as before.
    promotion_missed: bool,
    /// What the card would have to give this model, as admission priced it at
    /// spawn — 0 when the geometry could not be read.
    ///
    /// Carried here so a later request can ask "would it fit now?" without
    /// going back to disk: `estimate_gpu_footprint_mb` re-reads
    /// `gguf_header.bin` and scans the model directory, which is fine once per
    /// spawn and not fine once per request.
    gpu_estimate_mb: u64,
    /// A card/processor split — whole layers, or experts kept in RAM — when
    /// admission chose one; `None` for a worker wholly on either device.
    ///
    /// Recorded because nothing else says it. The split was decided here, sent
    /// to the worker as `--gpu-layers`, logged once at spawn, and then existed
    /// nowhere a person could read: the models page showed `fits_on_gpu:
    /// true` and no placement note for a model running 13 of its 28 layers on
    /// the card, so a user could not tell why it was slower than expected.
    card_split: Option<CardSplit>,
    /// Set when admission placed the model WHOLE on the card and its load's
    /// own reading split it ([`ModelProcessPool::fit_whole_placement_to_the_load`],
    /// #322) — what promotion must see the card gain before it moves the
    /// model whole again ([`should_return_to_gpu`]).
    split_by_the_load: Option<SplitByTheLoad>,
    /// The graphics memory OTHER programs held when this worker was placed
    /// short of the card — a card/processor split, or the processor for want
    /// of graphics memory — in MB: [`ModelProcessPool::other_programs_card_mb`]
    /// of the budget that placement weighed. `None` for a worker wholly on the
    /// card, and where no idle card's budget is known to read it against.
    ///
    /// Shown to the owner beside the placement, because nothing else says
    /// it: a chat program holding 630 MB of a 12 GB card cost a 14B 13 of
    /// its 48 card layers (15.3 tok/s against 26.1), and its owner found the
    /// program by hand (field report 2026-11-19). The figure is the moment
    /// of placement, not now: it says why the model is where it is.
    others_on_card_when_placed_mb: Option<u64>,
    /// The conversation a WHOLE card placement was fitted to keep room for by
    /// its load's own reading ([`ModelProcessPool::fit_whole_placement_to_the_load`]);
    /// `None` for every other placement — a split admitted short of the room
    /// is sized for the model's whole context already, and the processor's
    /// cache has a grant of its own. A prompt this placement refuses for want
    /// of room is worth a reload only where one sized for it keeps more
    /// ([`ModelProcessPool::make_room_for_a_longer_prompt`], #454).
    room_sized_for: Option<KvCharge>,
    /// The card's free memory, in MB, as this worker's load READ it before
    /// placing its layers (`WorkerMsg::CardFree`, #365); `None` where the
    /// spawn did not ask. Diagnostic only: gossiped as
    /// `ResidentModelLayers::card_free_at_load_mb`, so a far computer's
    /// placement can be told from the reading it was sized on (#3 (j13)).
    card_free_at_load_mb: Option<u64>,
    /// What this worker put into the pool's reserved-memory map, in MB — its
    /// spawn's admission charge plus every additional segment charged to it.
    /// `charged_against_ram` says which of the two maps.
    ///
    /// **Released by SUBTRACTING this, never by dropping the model's whole
    /// entry.** The maps are keyed by `ModelId` and `add_reserved`
    /// accumulates, which is right — one worker can hold several segments —
    /// but it means a release that removes the key cannot say "only what THIS
    /// worker was charged". That left a race on every path that evicts a dead
    /// worker: a replacement can have been admitted and charged under the same
    /// key before the eviction runs, and removing the key threw the
    /// replacement's charge away too, leaving it running un-accounted. The
    /// direction is under-charging, so the node believes it has more memory
    /// free than it has — the opposite of gotchas #461/#467 and milder, but
    /// the same class of bookkeeping error.
    ///
    /// Taking `spawn_lock` in the eviction paths would also close it and is
    /// the wrong trade: six of those callers are on the request hot path and
    /// that lock is held for a whole model load, minutes for a large model on
    /// a processor.
    charged_mb: AtomicU64,
    /// Layer ranges this worker has already been charged for.
    ///
    /// On the HANDLE rather than in a map keyed by model, for the same reason
    /// as `charged_mb`: the ranges belong to the process that loaded them, so
    /// they must die with it. Keyed by model they outlived their worker, and a
    /// replacement asked for a range its predecessor had paid for would be
    /// waved through without being weighed.
    /// Ranges this worker has been charged for, and what each one cost.
    ///
    /// The cost is recorded per range so a range that is later SUBSUMED can be
    /// released for exactly what it was charged — see
    /// [`WorkerHandle::release_subsumed_segments`].
    charged_segments: std::sync::Mutex<Vec<RangeCharge>>,
    /// Is this worker's memory charged against the system-RAM budget?
    ///
    /// Decided ONCE at spawn by `charges_ram` and recorded, because a later
    /// segment charged to the same worker must go to the same accountant. Its
    /// three inputs — going to the processor, no card detected, a build with no
    /// CUDA — are stable for a running worker, but re-deriving them would be
    /// the same "prediction versus fact" mistake `placed_on_cpu_because` exists
    /// to avoid.
    charged_against_ram: bool,
    /// A card/processor split's processor share, in MB, charged to the RAM
    /// budget beside `charged_mb`'s card share — at spawn (#264), and by every
    /// later range growth placed partly on the processor (#265); 0 for a worker
    /// on one device. Released with the worker.
    host_share_mb: AtomicU64,
    /// The longest conversation the model this worker holds whole admits, as
    /// the worker last reported it (`WorkerMsg::ContextFits`); 0 = no figure.
    /// Written by the reader actor, read by [`ModelProcessPool::context_fits`].
    /// On the handle, so the figure dies with the worker that measured it.
    context_fits: Arc<std::sync::atomic::AtomicU32>,
    /// What this worker's guessers keep on the card and the output head it
    /// would lend, as it last reported them (`WorkerMsg::CardBeside`), and how
    /// much of the first `charged_mb` already counts ([`CardBeside`]). On the
    /// handle, so the figures die with the worker that holds the memory.
    card_beside: Arc<CardBeside>,
    /// A growth's question about this worker's pool, awaiting its answer
    /// ([`CardFreeAsked`]). On the handle, shared with the reader actor.
    card_free_asked: CardFreeAsked,
    /// This worker's own decode speed ([`OwnDecodeSpeed`]), written by
    /// [`ModelProcessPool::note_decode_step`] and published by
    /// [`ModelProcessPool::resident_model_layers`]. On the handle for the
    /// reason `context_fits` is: a worker respawned on the other device starts
    /// with no figure rather than the old device's.
    own_decode: std::sync::Mutex<OwnDecodeSpeed>,
    /// This worker has guessed for another model's request
    /// ([`ModelProcessPool::draft`]). A split's reclaim never takes it (#355):
    /// the model it guesses for would trade its drafter — three times the
    /// 70B's speed (#351) — for a few layers on the card, and the drafter,
    /// reloaded as a guest, gets only the memory that stands free (gotcha
    /// #747's shape, the other way round).
    drafts_for_another_model: AtomicBool,
    /// The models it has guessed for ([`ModelProcessPool::draft`]'s
    /// `beside`), each once — what lets a WHOLE placement of the one model it
    /// guesses for take its card memory (`split_reclaim_eligible`, #442).
    guesses_for: std::sync::Mutex<Vec<ModelId>>,
    /// The pace this worker was last told (`inference::pace`): at spawn, the
    /// pool's then; after, each `DaemonMsg::Pace` it received. The fan-out
    /// tells only the workers it differs for ([`ModelProcessPool::pace_steps`]).
    told_pace: std::sync::atomic::AtomicU32,
    /// Whether this worker was last told another of our workers is busy on
    /// the card (`DaemonMsg::CardBusyBeside`; `false` at spawn, as the worker
    /// starts). The fan-out tells only the workers it differs for
    /// ([`ModelProcessPool::tell_cards_who_is_busy`]).
    told_busy_beside: AtomicBool,
    /// The pool's wake for that fan-out
    /// ([`ModelProcessPool::card_work_changed`]): rung where a reply's slot
    /// opens and closes on this worker ([`card_work_changed`]).
    card_work_changed: Arc<tokio::sync::Notify>,
    /// What that fan-out last saw of this worker's work on the card — kept
    /// only by [`ModelProcessPool::tell_cards_who_is_busy`].
    card_work_seen: std::sync::Mutex<CardWorkSeen>,
}

/// A worker's work on the card as the card fan-out last saw it (#489).
#[derive(Debug, Default, Clone, Copy)]
struct CardWorkSeen {
    /// A reply's step was running at the last look.
    working: bool,
    /// When it was last seen running, or seen to have just ended.
    at: Option<std::time::Instant>,
}

/// How long a card worker's work counts as going on after its last step ends
/// (#489): a drafter model guesses for its target every round, well inside a
/// second, so its target's hold stays paused for the whole reply instead of
/// starting pieces between two guesses that the next guess then waits behind
/// (12 arms of the 14B split, 2026-11-21: with the pause at the step alone,
/// drafting ran 0.6-1.1 ms a forward slower held, code 42.6 vs 43.8 tok/s,
/// while this side's forwards read the same ~25.6 ms — the drafter keeps that
/// card's clocks up by itself). The hold's own span: a reply is over after
/// it ([`crate::inference::clock_hold::HOLD_FOR`]). Prior art: a frequency
/// governor's down-switch hysteresis (cpufreq ondemand's
/// `sampling_down_factor`, devfreq's `downdifferential`).
const CARD_WORK_LINGERS_FOR: std::time::Duration = crate::inference::clock_hold::HOLD_FOR;

/// A reply's slot opened or closed on a worker: wake the fan-out that tells
/// each card worker whether another is busy beside it (#489) — only while the
/// clock hold is on, the one thing that reads it. `notify_one` keeps one
/// wake for a fan-out still running, so a change during one is never lost.
fn card_work_changed(wake: &tokio::sync::Notify) {
    if crate::inference::clock_hold::enabled() {
        wake.notify_one();
    }
}

/// Longest path a Unix domain socket may have, INCLUDING its NUL terminator.
///
/// `sun_path` in `sockaddr_un` is a fixed-size array, not a pointer: 104 bytes
/// on macOS and the BSDs, 108 on Linux. A path one byte over does not truncate
/// — `bind` refuses outright, and the failure surfaces from `interprocess` as
/// "local socket name length exceeds capacity of sun_path of sockaddr_un".
///
/// **This is not a theoretical limit.** macOS gives every user a private
/// per-boot temporary directory (`/var/folders/xx/…/T/`, measured at 49
/// characters on a Mac mini M4), and the old name — `swarmllm-worker-` plus a
/// 36-character UUID plus `.sock`, 57 characters — took that to 106. So EVERY
/// worker spawn failed on macOS, which means every request failed: with prompt
/// privacy on, the first and last layers are always local, so a node that
/// cannot start a worker cannot answer at all, whatever the swarm holds
/// (reported 2026-09-03, two models, first attempt each time). `TMPDIR=/tmp`
/// was the tester's workaround. Linux never saw it: `/tmp` is 4 characters.
#[cfg(unix)]
const SUN_PATH_MAX: usize = if cfg!(any(
    target_vendor = "apple",
    target_os = "freebsd",
    target_os = "openbsd",
    target_os = "netbsd",
    target_os = "dragonfly"
)) {
    104
} else {
    108
};

/// The socket filename, kept SHORT on purpose.
///
/// 12 hex characters of randomness rather than a 36-character UUID: the name
/// only has to be unique among this machine's live workers, and every
/// character spent here is a character the containing directory cannot use.
/// 48 bits collides with probability ~1e-10 at a thousand concurrent workers,
/// and a collision is a clean bind failure and a retry, not corruption.
#[cfg(unix)]
fn worker_socket_filename() -> String {
    let u = Uuid::new_v4();
    format!("swarmllm-{}.sock", &u.simple().to_string()[..12])
}

/// The first candidate directory in which `filename` fits inside `limit`.
///
/// Pure so the arithmetic can be tested without a filesystem, on any platform:
/// the macOS failure was a length calculation, and length calculations are
/// exactly what a Linux-only test suite cannot see.
///
/// `limit` counts the NUL terminator, so the path itself must be strictly
/// shorter than it.
#[cfg(unix)]
fn first_dir_that_fits(
    candidates: &[std::path::PathBuf],
    filename: &str,
    limit: usize,
) -> Option<std::path::PathBuf> {
    candidates
        .iter()
        .map(|d| d.join(filename))
        .find(|p| p.as_os_str().len() < limit)
}

/// A short, private per-user directory to fall back to when `$TMPDIR` is too
/// long for a socket path.
///
/// **Only consulted when `$TMPDIR` does not fit**, which on Linux is never —
/// so an ordinary node neither creates this nor touches `/tmp` at all.
///
/// `/tmp` is world-writable, so another local user can pre-create
/// `/tmp/swarmllm-<uid>` and would otherwise own the place our sockets live.
/// Two rules follow, and both matter:
///
/// - **Create it with its mode, never chmod it afterwards.** `mkdir(2)` with
///   0700 is atomic and fails outright if the name is taken, so there is no
///   moment when the directory exists more permissively than intended — and,
///   more to the point, we never change the permissions of something we did
///   not just create. `create_dir_all` + `set_permissions` would have
///   followed a planted symlink and chmod'd its target.
/// - **An existing directory is VERIFIED, not repaired.** `symlink_metadata`,
///   not `metadata`, because a symlink pointing elsewhere is precisely the
///   attack and following it is how you fail to notice. Anything that is not
///   a real directory, not ours, or group/world accessible is refused; the
///   caller still has `$TMPDIR` and the error names both.
#[cfg(unix)]
fn short_private_socket_dir() -> Option<std::path::PathBuf> {
    use std::os::unix::fs::{DirBuilderExt, MetadataExt, PermissionsExt};
    let uid = unsafe { libc::getuid() };
    let dir = std::path::PathBuf::from(format!("/tmp/swarmllm-{uid}"));
    match std::fs::DirBuilder::new().mode(0o700).create(&dir) {
        // Ours, made just now, with the mode already applied.
        Ok(()) => return Some(dir),
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {}
        Err(_) => return None,
    }
    let md = std::fs::symlink_metadata(&dir).ok()?;
    (md.is_dir() && md.uid() == uid && md.permissions().mode() & 0o077 == 0).then_some(dir)
}

/// Where this worker's IPC socket goes: the first directory whose resulting
/// path fits [`SUN_PATH_MAX`].
///
/// `$TMPDIR` first, because on macOS it is per-user and private and on Linux it
/// is short; the `/tmp/swarmllm-<uid>` fallback exists only for the case that
/// made this function necessary. Returns the path AND the directories that
/// were tried, so a failure can name them — the reported error said only that
/// the limit was exceeded, and the tester could not get the offending path out
/// of the logs even at debug level.
#[cfg(unix)]
fn worker_socket_path() -> Result<String, SwarmError> {
    let filename = worker_socket_filename();
    let mut candidates = vec![std::env::temp_dir()];
    // The fallback is built ONLY if the temp directory does not fit. On Linux
    // it never does not, so an ordinary node never creates it — a directory
    // nobody needs is still a directory somebody has to explain.
    if first_dir_that_fits(&candidates, &filename, SUN_PATH_MAX).is_none() {
        if let Some(short) = short_private_socket_dir() {
            candidates.push(short);
        }
    }
    match first_dir_that_fits(&candidates, &filename, SUN_PATH_MAX) {
        Some(p) => p
            .to_str()
            .map(str::to_string)
            .ok_or_else(|| SwarmError::Internal("socket path not UTF-8".into())),
        None => Err(SwarmError::ServiceUnavailable(format!(
            "no directory short enough for a worker socket (the limit is {SUN_PATH_MAX} \
             characters on this platform, including the file name): tried {}. Set TMPDIR to \
             a shorter path, for example TMPDIR=/tmp.",
            candidates
                .iter()
                .map(|d| format!("{} ({} chars)", d.display(), d.as_os_str().len()))
                .collect::<Vec<_>>()
                .join(", ")
        ))),
    }
}

/// Pull the `request_id` field out of any `WorkerMsg` variant that carries one.
/// `Ready` / `Bye` have no request_id and are dropped by the reader actor
/// (they're only relevant during spawn, which handshakes synchronously).
/// `BatchResult` carries N request_ids and is handled specially by the reader
/// actor — this helper returns `None` for it. `PrefixManifestUpdate` also
/// carries no request_id; the reader actor routes it through the dedicated
/// `prefix_manifest_tx` channel instead.
fn worker_msg_request_id(msg: &WorkerMsg) -> Option<Uuid> {
    match msg {
        WorkerMsg::LayerResult(r) => Some(r.request_id),
        WorkerMsg::Token { request_id, .. }
        | WorkerMsg::GenerateDone { request_id, .. }
        | WorkerMsg::Drafted { request_id, .. }
        | WorkerMsg::PromptAdmitted { request_id }
        | WorkerMsg::PromptRefused { request_id, .. }
        // Sent just before that request's `Error`, which its reader (the
        // generate) needs it beside (#454).
        | WorkerMsg::PromptRoomWanted { request_id, .. }
        | WorkerMsg::Error { request_id, .. } => Some(*request_id),
        // `PrefixSnapshotResponse` is correlated by `request_id` via the
        // normal response-routing channel — `fetch_local_snapshot`
        // registers a receiver up-front and waits for the reply.
        WorkerMsg::PrefixSnapshotResponse { request_id, .. } => Some(*request_id),
        // `Progress` carries a request_id but is explicitly NOT a response:
        // routing it to the per-request channel would hand the waiting caller a
        // progress note where it expects a result. Side-band, like the prefix
        // messages above.
        WorkerMsg::BatchResult { .. }
        | WorkerMsg::PrefixManifestUpdate { .. }
        | WorkerMsg::PrefixFetchProbe { .. }
        | WorkerMsg::Progress { .. }
        | WorkerMsg::CardAllocationProbe { .. }
        | WorkerMsg::CardStepStalled { .. }
        | WorkerMsg::ModelLoadTimed { .. }
        | WorkerMsg::ContextFits { .. }
        | WorkerMsg::CardBeside { .. }
        // Read by the spawn before the reader starts, or answered to a
        // growth's question by the reader (`card_free_asked`).
        | WorkerMsg::CardFree { .. }
        | WorkerMsg::Ready
        | WorkerMsg::Bye => None,
    }
}

/// How fast this node reads a model into memory: an average of milliseconds
/// per GiB over its workers' own load timings (`WorkerMsg::ModelLoadTimed`).
///
/// The one figure behind both halves of FUTURE_WORK #129's pricing: this node
/// advertises it (`NodeCapability::model_load_ms_per_gib`) and the planner
/// charges a cold candidate with it (`NodeCandidate::cold_load_ms_per_layer`).
/// It varies twentyfold across the fleet — measured from this node's own log
/// 2026-10-07, 335 loads: ~1.3 s/GiB onto the card and ~4 s/GiB onto the
/// processor, against ~26 s/GiB for an 8B on a processor peer (2026-08-01) and
/// over 25 s/GiB on a busy Mac that had just restarted (2026-10-07) — which is
/// why it is measured per node rather than assumed.
///
/// An AVERAGE, because a load time is a latency (`AckRttEstimator` vs
/// `GoodputEstimator`): a page-cache-warm reload is a real, fast load, and a
/// cold one a real, slow one. Loads under [`Self::MIN_BYTES`] are skipped —
/// their fixed costs (opening the header, laying out the tensors) would read
/// as a slow disk.
///
/// **Kept across restarts** (`daemon::state::load_rate`): in memory only, every
/// restart — every node at every release's auto-update — priced its first cold
/// load at `UNMEASURED_LOAD_MS_PER_GIB` (10 s/GiB) and advertised none, so a
/// split's first request after one was charged a cold load 3-6× its real cost
/// (this node's log, 2026-10-14: ~58 s priced for a load that took ~9-20 s). The
/// stored figure SEEDS the average and the next timed load moves it.
#[derive(Default)]
pub(crate) struct LoadRate {
    ms_per_gib: std::sync::Mutex<Option<f64>>,
    /// The figure storage holds, so an unchanged rate is never written again.
    written: std::sync::Mutex<Option<u32>>,
}

impl LoadRate {
    /// The smallest load that says anything about per-byte speed.
    const MIN_BYTES: u64 = 256 << 20;
    /// Weight of the newest sample — `peer_speed`'s EMA weight.
    const ALPHA: f64 = 0.3;
    /// The slowest figure the average takes in: over twice the slowest load
    /// the fleet has measured (~26 s/GiB, above). Past it is a load the
    /// machine was suspended through or a disk that stalled, not a speed —
    /// taken in, it priced this node's cold loads, and was advertised, for
    /// many loads after, and across restarts once the rate was kept (the
    /// pre-release review of v0.3.239).
    const MAX_MS_PER_GIB: u32 = 60_000;

    pub(crate) fn observe(&self, bytes: u64, ms: u32) {
        if bytes < Self::MIN_BYTES {
            return;
        }
        let sample = f64::from(ms) / (bytes as f64 / (1u64 << 30) as f64);
        if !sample.is_finite() {
            return;
        }
        let sample = sample.min(f64::from(Self::MAX_MS_PER_GIB));
        if let Ok(mut slot) = self.ms_per_gib.lock() {
            *slot = Some(match *slot {
                Some(prev) => Self::ALPHA * sample + (1.0 - Self::ALPHA) * prev,
                None => sample,
            });
        }
    }

    pub(crate) fn ms_per_gib(&self) -> Option<u32> {
        let v = (*self.ms_per_gib.lock().ok()?)?;
        Some(v.round().clamp(1.0, f64::from(u32::MAX)) as u32)
    }

    /// Start from what an earlier run measured (and storage holds) — unless a
    /// load has already been timed in this one, which is newer. A stored
    /// figure past [`Self::MAX_MS_PER_GIB`] is taken in at it, and storage is
    /// left holding the old one so the bounded figure is written back.
    pub(crate) fn seed(&self, ms_per_gib: u32) {
        if ms_per_gib == 0 {
            return;
        }
        if let Ok(mut slot) = self.ms_per_gib.lock() {
            if slot.is_none() {
                *slot = Some(f64::from(ms_per_gib.min(Self::MAX_MS_PER_GIB)));
            }
        }
        if let Ok(mut written) = self.written.lock() {
            *written = Some(ms_per_gib);
        }
    }

    /// The rate, if storage does not hold it yet.
    pub(crate) fn unwritten(&self) -> Option<u32> {
        let now = self.ms_per_gib()?;
        let written = *self.written.lock().ok()?;
        (written != Some(now)).then_some(now)
    }

    /// Storage now holds `ms_per_gib`.
    pub(crate) fn note_written(&self, ms_per_gib: u32) {
        if let Ok(mut written) = self.written.lock() {
            *written = Some(ms_per_gib);
        }
    }
}

/// Where a worker's side-band messages go — the ones that answer no request.
/// Each channel is unset in a bare pool (unit tests, before startup), and the
/// message is then dropped.
struct SideBand {
    prefix_manifest_tx: Option<mpsc::Sender<PrefixManifestEvent>>,
    prefix_probe_tx: Option<mpsc::Sender<PrefixProbeEvent>>,
    progress_tx: Option<mpsc::Sender<ProgressEvent>>,
    slow_card: Arc<crate::inference::cuda_pool::SlowCardNotice>,
    load_rate: Arc<LoadRate>,
    /// This worker's `WorkerHandle::context_fits`.
    context_fits: Arc<std::sync::atomic::AtomicU32>,
    /// This worker's `WorkerHandle::card_beside`, its reported half.
    card_beside: Arc<CardBeside>,
    /// This worker's `WorkerHandle::card_free_asked`.
    card_free_asked: CardFreeAsked,
    /// This worker's `WorkerHandle::asked_to_load`, set on a reported load.
    asked_to_load: Arc<AtomicBool>,
    /// The daemon's stop signal ([`ModelProcessPool::watch_daemon_stop`]):
    /// whether a worker's death is news or the node stopping.
    daemon_stopping: Option<tokio::sync::watch::Receiver<bool>>,
}

/// How long after a worker's connection ends the daemon may still begin
/// stopping for the two to be one event. A Ctrl-C in a terminal, systemd's
/// `KillMode=control-group` and a `kill` of every `swarmllm` process signal
/// the worker and the daemon at the same instant; the live node's log had
/// the worker's end FIRST in 4 of 65 stops, by under 0.2 ms (#269).
const WORKER_ENDED_WITH_THE_NODE_WITHIN: std::time::Duration = std::time::Duration::from_secs(2);

/// Whether a worker whose connection just ended went because the node is
/// stopping: the daemon's stop was asked already, or is within
/// [`WORKER_ENDED_WITH_THE_NODE_WITHIN`]. A daemon gone entirely (the watch
/// closed) is stopping too. No watch — a pool built without a daemon —
/// is never stopping.
async fn worker_ended_with_the_node(stopping: Option<tokio::sync::watch::Receiver<bool>>) -> bool {
    let Some(mut stopping) = stopping else {
        return false;
    };
    // Finished in time either way: the stop was asked, or the watch closed.
    let finished_in_time = tokio::time::timeout(
        WORKER_ENDED_WITH_THE_NODE_WITHIN,
        stopping.wait_for(|asked| *asked),
    )
    .await
    .is_ok();
    finished_in_time
}

/// Reader actor: owns the read half of the worker socket, dispatches each
/// inbound message to the right per-request channel. Exits when the socket
/// errors out (worker died, IPC corrupted); sets `dead` and drops all
/// in-flight response senders to wake waiting callers with `None`.
async fn reader_actor(
    mut reader: IpcReader,
    responses: ResponseMap,
    dead: Arc<AtomicBool>,
    model_id: ModelId,
    side: SideBand,
) {
    let SideBand {
        prefix_manifest_tx,
        prefix_probe_tx,
        progress_tx,
        slow_card,
        load_rate,
        context_fits,
        card_beside,
        card_free_asked,
        asked_to_load,
        daemon_stopping,
    } = side;
    let mut skipped: std::collections::HashSet<String> = std::collections::HashSet::new();
    loop {
        match recv_worker(&mut reader).await {
            Ok((msg, payload)) => {
                // BatchResult carries N inner results + a concatenated payload.
                // Split it so each caller sees a synthesized LayerResult on
                // their individual response channel — callers using the batch
                // API register one channel per request_id up front.
                if let WorkerMsg::BatchResult {
                    results,
                    activation_lens,
                } = msg
                {
                    dispatch_batch_result(&responses, results, activation_lens, payload).await;
                    continue;
                }
                // Cross-node prefix-cache announcement (Item 8 Phase 1).
                // No request_id; route through the daemon-installed
                // forwarder channel. Drop silently when no forwarder is
                // installed (unit tests / pre-startup).
                if let WorkerMsg::PrefixManifestUpdate {
                    model_id: announce_model,
                    blocks,
                } = msg
                {
                    if let Some(tx) = prefix_manifest_tx.as_ref() {
                        // try_send: never block the IPC reader. Daemon being
                        // slow or absent must not stall worker responses.
                        if let Err(tokio::sync::mpsc::error::TrySendError::Full(_)) =
                            tx.try_send(PrefixManifestEvent {
                                model_id: announce_model,
                                blocks,
                            })
                        {
                            tracing::debug!("prefix manifest channel full — dropping announce");
                        }
                    }
                    continue;
                }
                // Prefill/load progress. Best-effort by construction: a full
                // channel means the display lags, which is strictly better than
                // stalling the worker's result path to deliver a status note.
                if let WorkerMsg::Progress {
                    request_id,
                    phase,
                    done,
                    total,
                    from,
                } = msg
                {
                    if let Some(tx) = progress_tx.as_ref() {
                        let _ = tx.try_send(ProgressEvent {
                            request_id,
                            phase,
                            done,
                            total,
                            from,
                        });
                    }
                    continue;
                }
                // The worker's one card allocation probe (#762). Its own log
                // line carries the figure; the daemon keeps only a slow one,
                // for the health monitor to tell the owner.
                if let WorkerMsg::CardAllocationProbe { took_ms } = msg {
                    slow_card.record(std::time::Duration::from_millis(u64::from(took_ms)));
                    continue;
                }
                // A short card step of this worker stayed blocked (#146 (4)):
                // its log line carries it; the daemon counts the processes.
                if let WorkerMsg::CardStepStalled { blocked_ms, pid } = msg {
                    slow_card.record_stall(
                        pid,
                        std::time::Duration::from_millis(u64::from(blocked_ms)),
                        std::time::Instant::now(),
                    );
                    continue;
                }
                // One model load, timed inside the worker (#129) — and the
                // fact that it holds weights, whatever path asked for them.
                if let WorkerMsg::ModelLoadTimed { bytes, ms } = msg {
                    asked_to_load.store(true, Ordering::Release);
                    load_rate.observe(bytes, ms);
                    tracing::debug!(
                        model = %model_id,
                        bytes,
                        ms,
                        ms_per_gib = ?load_rate.ms_per_gib(),
                        "DIAG: model load timed"
                    );
                    continue;
                }
                // The context the whole model in this worker holds (#252 (1)).
                if let WorkerMsg::ContextFits { tokens } = msg {
                    context_fits.store(tokens.unwrap_or(0), Ordering::Relaxed);
                    tracing::debug!(
                        model = %model_id,
                        tokens = ?tokens,
                        "DIAG: the context the loaded model holds here"
                    );
                    continue;
                }
                // A growth's question about this worker's pool (#481 (5)).
                // One arriving with nobody asking (the spawn's own reading is
                // read before this actor starts) is dropped.
                if let WorkerMsg::CardFree { reusable_bytes, .. } = msg {
                    let asked = card_free_asked.lock().ok().and_then(|mut w| w.take());
                    if let Some(answer) = asked {
                        let _ = answer.send(reusable_bytes);
                    }
                    continue;
                }
                // What its guessers keep on the card, and the head it would
                // lend (#481 (5)); the pool folds the first into the charge.
                if let WorkerMsg::CardBeside {
                    guessers_bytes,
                    lends_head_bytes,
                } = msg
                {
                    card_beside.note_report(guessers_bytes, lends_head_bytes);
                    tracing::debug!(
                        model = %model_id,
                        guessers_mb = guessers_bytes >> 20,
                        lends_head_mb = lends_head_bytes >> 20,
                        "DIAG: what the worker's guessers keep on the card"
                    );
                    continue;
                }
                // Worker-initiated cross-node probe (Item 8 Phase 2b).
                if let WorkerMsg::PrefixFetchProbe {
                    request_id,
                    model_id: probe_model,
                    blocks,
                    keep_here,
                } = msg
                {
                    if let Some(tx) = prefix_probe_tx.as_ref() {
                        let probe_model_for_log = probe_model.clone();
                        if let Err(tokio::sync::mpsc::error::TrySendError::Full(_)) =
                            tx.try_send(PrefixProbeEvent {
                                model_id: probe_model,
                                request_id,
                                blocks,
                                keep: crate::types::KeepAsked::kept_if(keep_here),
                            })
                        {
                            // Dropped probes look indistinguishable from cross-node
                            // misses on the worker side — log so operators can
                            // distinguish channel-saturation from actual misses
                            // when chasing prefix-cache hit-rate regressions.
                            tracing::debug!(
                                model = %probe_model_for_log,
                                %request_id,
                                "prefix probe channel full — dropping probe"
                            );
                        }
                    }
                    continue;
                }
                if let Some(rid) = worker_msg_request_id(&msg) {
                    // `get` returns a Ref, which holds a shard lock. Clone the
                    // Sender and drop the Ref *before* awaiting `send` so we
                    // don't hold a DashMap shard across an await point (that
                    // would risk deadlock on a concurrent insert/remove).
                    if let Some(tx) = responses.get(&rid).map(|r| r.value().1.clone()) {
                        // Send best-effort; if the caller has already hung up
                        // we just drop the message.
                        let _ = tx.send((msg, payload)).await;
                    } else {
                        tracing::debug!(
                            request_id = %rid,
                            "Worker response for unknown request_id (caller dropped?)"
                        );
                    }
                }
            }
            Err(e) if crate::inference::worker_ipc::unknown_worker_msg(&e).is_some() => {
                // A newer worker's message (an update this daemon has not
                // restarted into). Its frame was read whole, so the stream is
                // still aligned: skip it, say so once per kind (#150).
                let tag = crate::inference::worker_ipc::unknown_worker_msg(&e)
                    .unwrap_or_default()
                    .to_string();
                if skipped.insert(tag.clone()) {
                    tracing::warn!(
                        model = %model_id,
                        message = %tag,
                        "A model worker sent a message this version does not know — ignoring it \
                         (the worker is newer; restarting the node finishes the update)"
                    );
                }
            }
            Err(e) => {
                // R107: Release ordering pairs with Acquire loads at every
                // dead-check call site. On weakly-ordered CPUs (ARM), a
                // Relaxed load could legally observe `dead == false` after
                // this store and the subsequent `responses.clear()`,
                // letting a concurrent caller insert into `responses` after
                // the clear — that channel would never receive anything,
                // and the caller's `recv()` loop has no timeout, so it
                // would hang forever. Release/Acquire prevents this race.
                dead.store(true, Ordering::Release);
                // Clear all pending response channels; dropping the Senders
                // makes each caller's `recv()` return `None`, which we map
                // to a "worker died" error.
                responses.clear();
                // Evicted first, judged after: the judgement may wait for the
                // daemon's stop, and it runs on its own task because dropping
                // this worker's handle aborts this one (#269).
                let error = e.to_string();
                tokio::spawn(async move {
                    if worker_ended_with_the_node(daemon_stopping).await {
                        tracing::debug!(
                            model = %model_id,
                            %error,
                            "Model worker stopped with the node"
                        );
                    } else {
                        tracing::warn!(model = %model_id, %error, "Worker reader exiting — evicting");
                    }
                });
                return;
            }
        }
    }
}

/// Split an incoming IpcLayerResult's binary payload back into the two
/// mutually exclusive fields it can carry (activations XOR spec_logits).
/// The worker guarantees only one of `has_activations` / `has_spec_logits`
/// is true; if the invariant is violated we preserve activations and drop
/// spec_logits with a warning (safer than panicking on the hot path).
fn reconstruct_layer_payload(
    has_activations: bool,
    has_spec_logits: bool,
    spec_logits_dims: Option<(u32, u32)>,
    payload: Vec<u8>,
) -> Result<(Vec<u8>, Vec<Vec<f32>>), SwarmError> {
    if has_activations && has_spec_logits {
        tracing::warn!(
            "IpcLayerResult has both has_activations and has_spec_logits — treating as activations"
        );
        return Ok((payload, Vec::new()));
    }
    if has_spec_logits {
        let dims = spec_logits_dims
            .ok_or_else(|| SwarmError::Internal("spec_logits flagged but dims missing".into()))?;
        let logits = crate::inference::worker_ipc::decode_spec_logits(&payload, dims)
            .map_err(SwarmError::Internal)?;
        Ok((Vec::new(), logits))
    } else if has_activations {
        Ok((payload, Vec::new()))
    } else {
        Ok((Vec::new(), Vec::new()))
    }
}

/// Fan out a BatchResult to N per-request channels. Splits the concatenated
/// payload into per-slot byte slices by `activation_lens`, wraps each inner
/// `IpcLayerResult` in a `WorkerMsg::LayerResult`, and delivers to the caller
/// registered under each `request_id`.
async fn dispatch_batch_result(
    responses: &ResponseMap,
    results: Vec<IpcLayerResult>,
    activation_lens: Vec<u32>,
    payload: Vec<u8>,
) {
    if results.len() != activation_lens.len() {
        tracing::warn!(
            results = results.len(),
            lens = activation_lens.len(),
            "BatchResult len mismatch — dropping batch"
        );
        return;
    }
    let mut cursor = 0usize;
    for (r, len) in results.into_iter().zip(activation_lens) {
        let len = len as usize;
        // SEC: only consume payload bytes for slots that actually carry an
        // activation tensor. A malformed worker response with len > 0 on a
        // has_activations=false slot would otherwise silently shift the
        // cursor past valid bytes, corrupting EVERY subsequent slot's
        // payload without any error returned.
        let (slot_payload, advance) = if r.has_activations {
            let end = cursor.saturating_add(len);
            if end <= payload.len() {
                (payload[cursor..end].to_vec(), len)
            } else {
                tracing::warn!(
                    request_id = %r.request_id,
                    cursor, len, payload_len = payload.len(),
                    "BatchResult activation length exceeds payload"
                );
                (Vec::new(), 0)
            }
        } else {
            if len != 0 {
                tracing::warn!(
                    request_id = %r.request_id,
                    len,
                    "BatchResult non-activation slot has len > 0 — ignoring (potential malformed worker response)"
                );
            }
            (Vec::new(), 0)
        };
        cursor = cursor.saturating_add(advance);
        let rid = r.request_id;
        let tx_opt = responses.get(&rid).map(|e| e.value().1.clone());
        if let Some(tx) = tx_opt {
            let _ = tx.send((WorkerMsg::LayerResult(r), slot_payload)).await;
        } else {
            tracing::debug!(
                request_id = %rid,
                "Batch slot reply for unknown request_id (caller dropped?)"
            );
        }
    }
}

/// How long an eviction waits for the subprocess to actually be reaped before
/// handing its memory budget back.
///
/// Bounds the wait on what varies — process teardown, which is fast (the
/// kernel is freeing already-allocated pages, not doing work proportional to
/// the model) but not instant. Long enough that the normal case always
/// completes inside it; short enough that a wedged process cannot stall an
/// eviction triggered from the request path.
const WORKER_EXIT_WAIT: std::time::Duration = std::time::Duration::from_secs(5);

/// How long a retiring worker is given to finish the requests already in flight
/// before it is told to shut down.
///
/// Retirement is triggered by models that are *idle* (both displacement paths
/// impose an idle floor), so in practice there is nothing to wait for and the
/// drain returns immediately. This bounds the exception, not the rule.
///
/// **Finite deliberately.** A request that never completes must not hold a
/// model's memory for the life of the daemon — that would refuse every later
/// load on the device, which is a worse failure than the one being closed here.
/// Same trade, and same reasoning, as `WORKER_EXIT_WAIT` below it.
const WORKER_DRAIN_WAIT: std::time::Duration = std::time::Duration::from_secs(10);

/// Poll interval while waiting for a worker to be reaped.
const WORKER_EXIT_POLL: std::time::Duration = std::time::Duration::from_millis(20);

/// How long a stopped card worker's memory is waited for after its process
/// is gone ([`ModelProcessPool::await_card_memory_back`], #3 (j13)). Ollama's
/// `waitForRecovery`, 5 s ("typical convergence is 0.5-1.5s").
const CARD_MEMORY_BACK_WITHIN: std::time::Duration = std::time::Duration::from_secs(5);

/// How often the card is read while that memory is waited for — Ollama's
/// 250 ms. One `nvidia-smi` reading took 56 ms on the WSL2 laptop.
const CARD_MEMORY_POLL: std::time::Duration = std::time::Duration::from_millis(250);

/// Two readings this close are the same reading: the card's free memory
/// moves by a few MB with other programs (the desktop, a browser).
const CARD_MEMORY_STEADY_MB: u64 = 32;

/// What became of the card memory a stopped worker held
/// ([`ModelProcessPool::await_card_memory_back`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CardMemoryBack {
    /// The card's free memory rose by three quarters of what the worker was
    /// charged, `waited_ms` after its process was gone.
    Back { waited_ms: u64 },
    /// Risen by less than three quarters, then steady: the release is over,
    /// smaller than the worker's charge (an idle worker's cache is not all
    /// filled), `waited_ms` after its process was gone.
    Settled { waited_ms: u64, risen_mb: u64 },
    /// It had not by [`CARD_MEMORY_BACK_WITHIN`]; `free_mb` was the last reading.
    NotBack { free_mb: u64 },
    /// The card could not be read (no `nvidia-smi`, or one stuck).
    Unread,
}

/// Put a model worker in the one Windows job this daemon keeps, which ends
/// every member when its last handle closes — when this daemon exits, however
/// it exits (FUTURE_WORK #153).
///
/// `Command` hands a Windows child every inheritable handle, and the node's
/// sockets turned out to be among them: a worker still busy when its daemon
/// died — loading a model, writing a long reply — kept the node's port, and the
/// next start failed on "already in use" until that work ended. A worker with
/// no daemon has nobody to answer, so it ends with its daemon, by Windows' own
/// mechanism for a process that must not outlive its owner
/// (`JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE`, the documented way a parent takes its
/// children with it). The job handle is created NOT inheritable: a worker
/// holding it open would keep the job alive and itself with it.
///
/// Best effort: if the job cannot be made or joined (a host job that forbids
/// it), the worker runs as before and the failure is logged once per worker.
#[cfg(windows)]
fn end_with_this_daemon(child: &tokio::process::Child) {
    use std::sync::OnceLock;
    use windows_sys::Win32::Foundation::{CloseHandle, HANDLE};
    use windows_sys::Win32::System::JobObjects::{
        AssignProcessToJobObject, CreateJobObjectW, JobObjectExtendedLimitInformation,
        SetInformationJobObject, JOBOBJECT_EXTENDED_LIMIT_INFORMATION,
        JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
    };

    struct Job(HANDLE);
    // SAFETY: a job handle is a kernel object handle, usable from any thread;
    // this one is created once and never closed while the process runs.
    unsafe impl Send for Job {}
    unsafe impl Sync for Job {}
    static JOB: OnceLock<Option<Job>> = OnceLock::new();

    let job = JOB.get_or_init(|| {
        // SAFETY: no security attributes (so the handle is NOT inheritable) and
        // no name; both pointers may be null.
        let handle = unsafe { CreateJobObjectW(std::ptr::null(), std::ptr::null()) };
        if handle.is_null() {
            tracing::warn!(
                error = %std::io::Error::last_os_error(),
                "Could not create the job that ends model workers with this node"
            );
            return None;
        }
        let mut limits = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
        limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
        // SAFETY: `limits` is the struct this information class names, passed
        // with its own size; `handle` was just created.
        let set = unsafe {
            SetInformationJobObject(
                handle,
                JobObjectExtendedLimitInformation,
                &limits as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION as *const core::ffi::c_void,
                std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
            )
        };
        if set == 0 {
            tracing::warn!(
                error = %std::io::Error::last_os_error(),
                "Could not make model workers end with this node"
            );
            // SAFETY: created above and owned by nothing else.
            unsafe { CloseHandle(handle) };
            return None;
        }
        Some(Job(handle))
    });
    let (Some(job), Some(process)) = (job, child.raw_handle()) else {
        return;
    };
    // SAFETY: the job handle lives for the whole process, and `child` owns the
    // process handle for the duration of this call.
    if unsafe { AssignProcessToJobObject(job.0, process as HANDLE) } == 0 {
        tracing::warn!(
            error = %std::io::Error::last_os_error(),
            pid = child.id(),
            "A model worker could not be tied to this node — if the node stops abruptly, \
             it may hold the node's port until it finishes its work"
        );
    }
}

impl Drop for WorkerHandle {
    fn drop(&mut self) {
        // Stop the reader actor so it doesn't outlive the socket.
        self.reader_handle.abort();
        // Kill the child process if still running, then reap it in the
        // background and publish the fact. `start_kill` only signals; whoever
        // is waiting to reuse this worker's memory needs to know when the
        // process is actually gone, which is when the OS has taken its device
        // allocations back.
        if let Some(mut child) = self.child.take() {
            let _ = child.start_kill();
            let exited = self.exited.clone();
            // No runtime in some unit tests; there the flag simply stays false
            // and the waiter falls through on its timeout, which is the same
            // conservative outcome as before this existed.
            if let Ok(rt) = tokio::runtime::Handle::try_current() {
                rt.spawn(async move {
                    let _ = child.wait().await;
                    exited.store(true, Ordering::Release);
                });
            } else {
                self.exited.store(true, Ordering::Release);
            }
        }
        // Clean up the socket file (Unix only — Windows named pipes are
        // reclaimed by the kernel when all handles close).
        #[cfg(unix)]
        let _ = std::fs::remove_file(&self.socket_name);
    }
}

/// RAII guard: unregister a request's response channel when the caller drops
/// it (whether the request finished, errored, or the caller was cancelled).
/// Without this, a cancelled request leaks its entry in `responses` forever.
struct ResponseGuard {
    responses: ResponseMap,
    request_id: Uuid,
    /// Identifies THIS attempt's entry. `Drop` removes the map entry only when
    /// it still carries this token, so a superseded attempt's cleanup cannot
    /// tear down the attempt that displaced it.
    token: u64,
    /// Worker to notify if this guard drops without being disarmed. `None`
    /// suppresses the cancel entirely (used where the request is known to have
    /// already reached the worker's terminal state).
    worker: Option<Arc<WorkerHandle>>,
    /// Worker to mark USED when the slot closes — its reply's end, as its
    /// start was ([`WorkerHandle::register_response`]); `None` for a peer's
    /// question, which marks nothing ([`WorkerHandle::register_question`]).
    ///
    /// Stamped at the start alone, a reply that ran longer than a window read
    /// idle the moment it ended: two minutes into a long reply here, prune's
    /// narrowing (`NARROW_ONLY_AFTER_IDLE_SECS`, #3 (j8)) and the idle unload
    /// could take the model its user had just used (pre-release review,
    /// 2026-11-13). Ollama resets a runner's keep-alive when a request
    /// FINISHES (`server/sched.go`, `finishedReqCh` → `expireTimer`).
    ///
    /// WEAK: the stamp must not keep the worker alive. Its last owner's drop
    /// kills the process and frees its memory (`impl Drop for WorkerHandle`),
    /// and a reply's slot can outlive an evicted worker.
    used_until_now: Option<(std::sync::Weak<WorkerHandle>, Requester)>,
    /// Rung when the slot closes, as at its opening ([`card_work_changed`]):
    /// the worker's work on the card may have ended (#489).
    card_work_changed: Option<Arc<tokio::sync::Notify>>,
}

/// Claim `request_id` in `map` for a fresh attempt. Returns the new attempt's
/// token plus the token it displaced, if another attempt was already
/// registered under the same id.
fn claim_response_slot(map: &ResponseMap, request_id: Uuid, tx: ResponseTx) -> (u64, Option<u64>) {
    let token = RESPONSE_ATTEMPT_TOKEN.fetch_add(1, Ordering::Relaxed);
    let displaced = map.insert(request_id, (token, tx)).map(|(prev, _)| prev);
    (token, displaced)
}

/// True when `request_id` is registered to an attempt other than `token` —
/// i.e. a later attempt has taken the slot over.
fn response_slot_superseded(map: &ResponseMap, request_id: Uuid, token: u64) -> bool {
    map.get(&request_id).is_some_and(|e| e.value().0 != token)
}

impl WorkerHandle {
    /// Is this worker's memory held on a graphics card — i.e. does what it
    /// takes come out of the VRAM budget rather than the system-RAM one?
    ///
    /// **The single answer, and deliberately NOT
    /// `placed_on_cpu_because.is_none()`.** That field records why a model was
    /// DEMOTED, and on a machine with no graphics card at all nothing was
    /// demoted — so it reads `None` there exactly as it does for a worker
    /// genuinely holding a card. `charged_against_ram` is the fact instead: it
    /// is what [`charges_ram`] decided at spawn, and `charges_ram` knows the
    /// two cases `cpu_reason` cannot see, "no card detected" and "this build
    /// has no CUDA".
    ///
    /// Re-deriving it from placement is what made this node's anti-swap
    /// admission control inert. `charge_additional_segment` asked
    /// `placed_on_cpu_because`, so every growth of a live worker on a
    /// GPU-less node was weighed by `admit_to_gpu` — which returns `true`
    /// unconditionally when `vram_budget_mb` is 0, as it is on a machine with
    /// no card. Reported live 2026-09-13 (report #030) from a 16 GB Mac mini:
    /// the 14B's spawn was correctly weighed against RAM (470 MB, headroom
    /// 8400 MB) and its next four layer-range growths — 6090 + 2730 + 2520 +
    /// 210 ≈ 11.5 GB — were each waved through by the graphics gate, all
    /// logged `on_gpu=true` on a machine with no GPU. The node went into swap
    /// with the RAM gate working perfectly and simply never asked again.
    ///
    /// A swarm node's coverage is reassigned by scheduling, failover and
    /// re-plans, so growth is the common case, not the rare one — the gate
    /// opened once per model and then stopped checking. See gotcha #586.
    fn holds_gpu_memory(&self) -> bool {
        !self.charged_against_ram
    }

    /// What this worker's own memory pool holds freed for its next allocation,
    /// in MB, read from the worker NOW (`DaemonMsg::ReadCardFree` →
    /// `WorkerMsg::CardFree::reusable_bytes`). A range this worker grows by
    /// loads into it before the driver hands it anything, and the driver's
    /// free figure the card budget reads counts it as taken: "the driver lends
    /// a pool's spare memory only within its own process" (`cuda_pool`,
    /// `docs/invariants/memory.md`). 0 without an answer within
    /// [`GROWTH_CARD_READ_TIMEOUT`], from a worker older than the field, or
    /// with `SWARMLLM_GROWTH_REUSES_POOL=0` (the A/B).
    ///
    /// Qwen3.8-27B's `[63,64)` growth was refused 4 of 4 with the card at
    /// 1,080-1,130 MB free against the 1,231 its 411 MB needed above the
    /// reserve, while the first range's worker held ~215-320 MB of the prompt
    /// pass's freed buffers in its pool (`~/swarmllm-gate/split27_1120a`,
    /// 2026-11-20; between requests the card read 1,399 free).
    ///
    /// Prior art: vLLM's `determine_available_memory` counts the memory its own
    /// PyTorch caching allocator reserved as its own, never as another
    /// process's; PyTorch's allocator serves an allocation from a reserved
    /// free block before asking the driver.
    async fn pool_reusable_mb(&self, model_id: &ModelId) -> u64 {
        const MIB: u64 = 1024 * 1024;
        if std::env::var("SWARMLLM_GROWTH_REUSES_POOL").as_deref() == Ok("0") {
            return 0;
        }
        let (tx, rx) = tokio::sync::oneshot::channel();
        match self.card_free_asked.lock() {
            Ok(mut asked) => *asked = Some(tx),
            Err(_) => return 0,
        }
        {
            let mut writer = self.writer.lock().await;
            if let Err(e) = send_daemon(&mut *writer, &DaemonMsg::ReadCardFree, &[]).await {
                tracing::debug!(
                    model = %model_id,
                    error = %e,
                    "Could not ask a live worker what its card pool holds freed"
                );
                return 0;
            }
        }
        match tokio::time::timeout(GROWTH_CARD_READ_TIMEOUT, rx).await {
            Ok(Ok(Some(bytes))) => bytes / MIB,
            _ => 0,
        }
    }

    /// How many of the layers this worker holds run on its graphics card —
    /// **the ONE answer**, for this node's planner
    /// ([`ModelProcessPool::card_share_for_planning`]) and for what it tells
    /// peers (`ResidentModelLayers::card_layers`, FUTURE_WORK #361). Range by
    /// range, as each was placed ([`RangeCharge::split`]): a split's card share,
    /// else the whole range on a worker charged to the card and none on one in
    /// system memory. Summed as `resident_model_layers` sums widths, so a
    /// layer held in two ranges counts twice in both.
    ///
    /// Read off the spawn's split alone, a range grown later never counted; and
    /// a peer that said nothing had every layer it held priced as the card's:
    /// a 12 GB card holding 57 of a 70B's layers, about 20 of them on the
    /// card, read as 59 card layers (2026-10-27).
    fn layers_on_card(&self) -> u32 {
        if !self.holds_gpu_memory() {
            return 0;
        }
        self.charged_segments
            .lock()
            .map(|v| v.iter().map(RangeCharge::layers_on_card).sum())
            .unwrap_or(0)
    }

    /// **The single answer to "is this worker in use?"** — a response in flight,
    /// OR a request's conversation cache it holds between two forwards.
    ///
    /// Every decision that can take a worker away asks this, never `responses`
    /// alone: promotion to the card, both memory reclaims, and the in-use set
    /// auto-manage reads. `tests/repo_consistency.rs` fails the build on a bare
    /// read elsewhere, because each of the five sites that used to decide it
    /// had the same blind spot (`kv_holders`).
    fn in_use(&self, window: std::time::Duration) -> bool {
        !self.responses.is_empty() || self.holds_live_conversation(window)
    }

    /// This worker guessed for `target`'s request (`ModelProcessPool::draft`).
    fn note_guessing_for(&self, target: &ModelId) {
        self.drafts_for_another_model.store(true, Ordering::Release);
        let mut targets = self
            .guesses_for
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !targets.contains(target) {
            targets.push(target.clone());
        }
    }

    /// Has this worker guessed for `model` and for no other model? False for
    /// one that never guessed.
    fn guesses_only_for(&self, model: &ModelId) -> bool {
        let targets = self
            .guesses_for
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        !targets.is_empty() && targets.iter().all(|t| t == model)
    }

    /// Does this worker hold the cache of a request that may still send it a
    /// forward? Entries quiet for longer than `window`
    /// ([`ModelProcessPool::conversation_window`]) are dropped as they are
    /// found.
    fn holds_live_conversation(&self, window: std::time::Duration) -> bool {
        let mut holders = self
            .kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        holders.retain(|_, last| last.elapsed() <= window);
        !holders.is_empty()
    }

    /// `request_id` has — or is about to have — a conversation cache on this
    /// worker. Called by every forward, so the stamp is its last activity here.
    fn note_conversation(&self, request_id: Uuid) {
        self.kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(request_id, std::time::Instant::now());
    }

    /// A new pass of `request_id` from its first position over `range`
    /// replaces the earlier attempt's conversation here (a re-plan keeps its
    /// id, #448), so that attempt's hold is no use by anyone else (#481 (5)) —
    /// but only where `range` overlaps a range a pass of the request was sent
    /// for here ([`Self::pass_ranges`]): one beside them is the SAME pass's
    /// other range, and its hold stands, or the worker serving the pass's first
    /// range is retired mid-request for its last (2026-11-19, the 27B's
    /// [0,21) + [63,64)). Only the hold: a reply of it still in flight is still
    /// use. `true` where it released one.
    fn release_an_earlier_pass(&self, request_id: Uuid, range: (u32, u32)) -> bool {
        let mut holders = self
            .kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut passes = self
            .pass_ranges
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let earlier = passes
            .get(&request_id)
            .is_some_and(|sent| sent.iter().any(|r| r.0 < range.1 && range.0 < r.1));
        if earlier {
            passes.remove(&request_id);
            holders.remove(&request_id);
        }
        earlier
    }

    /// A pass of `request_id` from its first position was sent for `range` on
    /// this worker ([`Self::pass_ranges`]).
    fn note_pass_range(&self, request_id: Uuid, range: (u32, u32)) {
        let holders = self
            .kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut passes = self
            .pass_ranges
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        passes.retain(|r, _| *r == request_id || holders.contains_key(r));
        let sent = passes.entry(request_id).or_default();
        if !sent.contains(&range) {
            sent.push(range);
        }
    }

    /// `request_id` released its cache here, or was cancelled.
    fn forget_conversation(&self, request_id: Uuid) {
        self.kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&request_id);
        self.pass_ranges
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&request_id);
        self.awaiting_first_step
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&request_id);
    }

    /// A forward for `request_id` is being sent to this worker: sequence 0 is
    /// a prompt pass, whose first step is now awaited; anything later is a
    /// step, and ends the wait (#448 (b), as the worker's
    /// `KvCacheStore::note_forward_ran` does; off with the same
    /// `SWARMLLM_PROMPT_PASS_HOLD=0`).
    fn note_forward_sent(&self, request_id: Uuid, sequence_num: u32, parties: PassParties) {
        let mut waiting = self
            .awaiting_first_step
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if sequence_num == 0 && crate::inference::split::kv_cache::prompt_pass_hold_enabled() {
            waiting.insert(
                request_id,
                AwaitedPass {
                    sent: std::time::Instant::now(),
                    seen: AwaitedPass::seen_at_arrival(&parties),
                    parties,
                    missing_since: None,
                },
            );
        } else {
            waiting.remove(&request_id);
        }
    }

    /// The passes waiting here whose sender or coordinator has been out of the
    /// swarm (`still_here` false) for `gone_after` as of `now`, taken out of the
    /// wait (#448 (d)). A party seen again clears the count, so a reconnect or
    /// a late registry entry keeps the pass.
    fn take_abandoned_passes(
        &self,
        still_here: &dyn Fn(&crate::types::NodeId) -> bool,
        now: std::time::Instant,
        gone_after: std::time::Duration,
    ) -> Vec<Uuid> {
        let mut waiting = self
            .awaiting_first_step
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut abandoned = Vec::new();
        for (request_id, pass) in waiting.iter_mut() {
            if !a_party_left(&pass.parties, &mut pass.seen, still_here) {
                pass.missing_since = None;
                continue;
            }
            let since = *pass.missing_since.get_or_insert(now);
            if now.saturating_duration_since(since) >= gone_after {
                abandoned.push(*request_id);
            }
        }
        for request_id in &abandoned {
            waiting.remove(request_id);
        }
        abandoned
    }

    /// Does a prompt pass sent here still await its first step? Entries older
    /// than `kv_cache::PROMPT_PASS_HOLD` — the coordinator's own longest wait —
    /// are dropped as they are found.
    fn awaits_a_first_step(&self) -> bool {
        let hold = crate::inference::split::kv_cache::PROMPT_PASS_HOLD;
        let mut waiting = self
            .awaiting_first_step
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        waiting.retain(|_, pass| pass.sent.elapsed() <= hold);
        !waiting.is_empty()
    }

    /// What this worker is charged now, as (graphics card, the machine's
    /// memory) in MB: `charged_mb` goes to whichever device the spawn charged
    /// (`charged_against_ram`), a card/processor split's processor share
    /// (`host_share_mb`) to the machine.
    fn card_and_machine_mb(&self) -> (u64, u64) {
        let charged = self.charged_mb.load(Ordering::Acquire);
        let host = self.host_share_mb.load(Ordering::Acquire);
        if self.charged_against_ram {
            (0, charged.saturating_add(host))
        } else {
            (charged, host)
        }
    }

    /// Has this worker already been charged for exactly `segment`? The charge
    /// RECORD; whether a forward for it would load anything is
    /// [`Self::serves_segment`].
    #[cfg(test)]
    fn segment_is_charged(&self, segment: (u32, u32)) -> bool {
        self.charged_segments
            .lock()
            .map(|v| v.iter().any(|c| c.range == segment))
            .unwrap_or(false)
    }

    /// Does this worker run `segment` with nothing more loaded — a range it
    /// was charged for, or a run inside one, which its worker serves from that
    /// range's weights (#449, `split::view`; `SWARMLLM_ELASTIC_SPANS=0` asks
    /// for the exact range only)? **The one answer to "would a forward for
    /// this load anything here"**: growth, the guest's fit, a peer's question
    /// and the load ahead all ask it, so none of them charges or loads a run
    /// the worker already serves — read as "charged" only when equal, a 14B
    /// held whole was charged and grown for the 25 layers a split gave it
    /// (2026-11-13), and the worker read them from disk again.
    fn serves_segment(&self, segment: (u32, u32), shape: RunShape) -> bool {
        self.serving_range(segment, shape).is_some()
    }

    /// The charged range that serves `segment` — itself where charged as it
    /// is, else (a plain run) the narrowest charged range holding it (#449). A
    /// forward for a run inside a charged range carries that range to the
    /// worker (`IpcForward::served_from`), so the worker loads THAT range —
    /// what the daemon charged — and serves the run from it, never the run on
    /// its own.
    fn serving_range(&self, segment: (u32, u32), shape: RunShape) -> Option<(u32, u32)> {
        let charged = self.charged_segments.lock().ok()?;
        if charged.iter().any(|c| c.range == segment) {
            return Some(segment);
        }
        if shape == RunShape::TensorParallel || !crate::inference::split::view::elastic_spans_on() {
            return None;
        }
        charged
            .iter()
            .map(|c| c.range)
            .filter(|r| {
                crate::inference::split::view::serves_inside(
                    (r.0 as usize, r.1 as usize),
                    (segment.0 as usize, segment.1 as usize),
                )
            })
            .min_by_key(|r| r.1 - r.0)
    }

    /// What a forward for `segment` tells the worker it is served from
    /// (`IpcForward::served_from`): a charged range holding it, where that is
    /// not `segment` itself — never for a tensor-parallel share.
    fn served_from_for(&self, segment: (u32, u32), shape: RunShape) -> Option<(u32, u32)> {
        self.serving_range(segment, shape).filter(|r| *r != segment)
    }

    /// Drop the charges for every range this one strictly contains, returning
    /// what they were charged.
    ///
    /// **Mirrors what the worker is about to do to its own map.**
    /// `model_worker::subsumed_segment_keys` removes a loaded range the
    /// incoming one already covers — [16..48) plus [0..16) becoming [0..48) is
    /// a miss on its exact key, so without that the whole model is read from
    /// disk again beside the copy already resident. The worker frees the
    /// memory; the daemon went on charging for it, so a worker that had
    /// consolidated its ranges kept paying for the ones it had dropped and
    /// refused later models that would have fitted.
    ///
    /// **Strict containment only**, the same rule the worker applies: a partial
    /// overlap is two ranges that each still need their own layers.
    ///
    /// **Known gap, and it is pre-existing rather than introduced here.** The
    /// worker keys its map by `(start, end, tp_rank, tp_size)` and drops only
    /// within one tensor-parallel shape, while the daemon's charges carry no
    /// rank at all — `record_charged_segment` is idempotent on the range, so a
    /// range serving several ranks is charged once for all of them. Under
    /// tensor parallelism this therefore releases a charge the worker may only
    /// partly have dropped. That is a smaller error than the one being fixed
    /// and in the same direction as the daemon's existing single-charge
    /// simplification; giving the daemon a rank-aware model is the real fix and
    /// is recorded in `docs/FUTURE_WORK.md`.
    ///
    /// Returns what the dropped ranges held of `charged_mb` and, separately, of
    /// `host_share_mb` — a range grown partly onto the processor holds both
    /// (#265).
    fn release_subsumed_segments(&self, incoming: (u32, u32)) -> RangeCost {
        let Ok(mut v) = self.charged_segments.lock() else {
            return RangeCost::default();
        };
        let mut freed = RangeCost::default();
        v.retain(|c| {
            let subsumed = strictly_subsumes(incoming, c.range);
            if subsumed {
                freed = freed.plus(c.cost);
            }
            !subsumed
        });
        // Saturating, always: an under-run wraps the budget to 18 exabytes and
        // admits everything for ever (the rule `release_reserved` already
        // follows).
        for (held, mb) in [
            (&self.charged_mb, freed.mb),
            (&self.host_share_mb, freed.host_mb),
        ] {
            held.fetch_sub(mb.min(held.load(Ordering::Acquire)), Ordering::AcqRel);
        }
        freed
    }

    /// What [`Self::release_subsumed_segments`] WOULD free for `incoming`,
    /// without freeing it.
    ///
    /// Admission needs the figure before the charge exists: the worker drops
    /// the ranges `incoming` strictly contains BEFORE it loads it
    /// (`model_worker::ensure_model_loaded`), so the peak it reaches is the new
    /// range less what those held, and that peak is what admission must weigh.
    /// One predicate for both, so the admitted discount and the later release
    /// cannot disagree about which ranges it covers.
    fn subsumed_charge(&self, incoming: (u32, u32)) -> RangeCost {
        self.charged_segments
            .lock()
            .map(|v| {
                v.iter()
                    .filter(|c| strictly_subsumes(incoming, c.range))
                    .fold(RangeCost::default(), |acc, c| acc.plus(c.cost))
            })
            .unwrap_or_default()
    }

    /// Does `incoming` take in a range whose memory is charged in the worker's
    /// BASE — its spawn's own range, or one grown with nothing judged, both
    /// recorded at no cost of their own? [`Self::subsumed_charge`] then counts
    /// nothing for the memory that range gives back when the worker drops it
    /// for `incoming` (#461).
    fn takes_in_a_range_charged_in_its_base(&self, incoming: (u32, u32)) -> bool {
        self.charged_segments
            .lock()
            .map(|v| {
                v.iter()
                    .any(|c| strictly_subsumes(incoming, c.range) && c.cost == RangeCost::default())
            })
            .unwrap_or(false)
    }

    /// Does `incoming` share layers with a charged range while neither holds
    /// the other? The worker drops only ranges a load strictly contains
    /// (`model_worker::subsumed_segment_keys`), so it keeps both, and a split
    /// of `incoming` is sized on the room beside a copy of the very layers they
    /// share (#461, 2026-11-25).
    fn partly_overlaps_a_charged_range(&self, incoming: (u32, u32)) -> bool {
        self.charged_segments
            .lock()
            .map(|v| {
                v.iter().any(|c| {
                    layers_shared(incoming, c.range) > 0
                        && !strictly_subsumes(incoming, c.range)
                        && !(c.range.0 <= incoming.0 && incoming.1 <= c.range.1)
                })
            })
            .unwrap_or(false)
    }

    /// Record that this worker has been charged for `segment`, wholly on the
    /// device it is charged to, and add `mb` to what it owes. Idempotent on the
    /// range.
    fn record_charged_segment(&self, segment: (u32, u32), mb: u64) {
        self.record_charged_range(segment, RangeCost { mb, host_mb: 0 }, None);
    }

    /// Record `segment` at no extra cost, placed as the spawn placed its own —
    /// the spawn's own range, and one grown with nothing judged, which the
    /// worker loads under the spawn's `--gpu-layers` (`split::placement_of`).
    fn record_segment_placed_as_spawned(&self, segment: (u32, u32)) {
        self.record_charged_range(segment, RangeCost::default(), self.card_split);
    }

    /// [`Self::record_charged_segment`] for a range placed on both devices:
    /// `cost.mb` joins `charged_mb` (the card's), `cost.host_mb` joins
    /// `host_share_mb` (the machine's), so a departure releases both (#265);
    /// `split` says how many of its layers the card runs ([`Self::layers_on_card`]).
    fn record_charged_range(&self, segment: (u32, u32), cost: RangeCost, split: Option<CardSplit>) {
        if let Ok(mut v) = self.charged_segments.lock() {
            if v.iter().any(|c| c.range == segment) {
                return;
            }
            v.push(RangeCharge {
                range: segment,
                cost,
                split,
            });
        }
        self.charged_mb.fetch_add(cost.mb, Ordering::AcqRel);
        self.host_share_mb.fetch_add(cost.host_mb, Ordering::AcqRel);
    }

    /// Register `tx` as the response channel for `request_id` and return the
    /// guard that owns the entry. This is the ONLY supported way to populate
    /// `responses`: inserting directly cannot produce a correctly-tokened
    /// guard, so a superseded attempt would tear down its successor.
    ///
    /// `cancel_on_drop` sends the worker a cancel if the guard drops while
    /// still armed; pass `false` where there is no compute worth abandoning.
    ///
    /// Returns the guard plus the token displaced from the map, if any. A
    /// `Some` displaced token means another attempt is in flight under the
    /// same `request_id` — the caller has superseded it.
    ///
    /// `user` is whose request the slot serves, REQUIRED: an owner's use is
    /// stamped apart ([`Self::idle_secs_for`], #483 (a)).
    fn register_response(
        self: &Arc<Self>,
        request_id: Uuid,
        tx: ResponseTx,
        cancel_on_drop: bool,
        user: Requester,
    ) -> (ResponseGuard, Option<u64>) {
        self.mark_used_now(user);
        self.ran_a_request.store(true, Ordering::Relaxed);
        // Before the request is sent: its first message may load weights.
        self.asked_to_load.store(true, Ordering::Release);
        let (mut guard, displaced) = self.register_unseen(request_id, tx, cancel_on_drop);
        guard.used_until_now = Some((Arc::downgrade(self), user));
        (guard, displaced)
    }

    /// Requests other than `request_id` with a reply registered on this
    /// worker now — generates, forwards and peers' questions alike: what a
    /// request diverted out of the batch would keep waiting
    /// (`IpcGenerate::others_in_flight`).
    fn others_in_flight(&self, request_id: Uuid) -> u32 {
        self.responses
            .iter()
            .filter(|entry| *entry.key() != request_id)
            .count()
            .try_into()
            .unwrap_or(u32::MAX)
    }

    /// Is a reply's step running on this worker NOW — a slot open from just
    /// before its request is sent to its end? Deliberately NOT
    /// [`Self::in_use`], which also counts a conversation held between two
    /// forwards: then the card stands idle, the very gap the clock hold fills
    /// (#489). Asked ONLY by [`ModelProcessPool::tell_cards_who_is_busy`] —
    /// never for whether a worker may be retired, reclaimed or promoted, where
    /// the gap between forwards is still a reply (#93; guard
    /// `whether_a_worker_is_in_use_is_decided_in_one_place`).
    fn working_now(&self) -> bool {
        !self.responses.is_empty()
    }

    /// [`Self::in_use`] asked by one request about every OTHER: a reply of
    /// another in flight, or another's conversation held between forwards.
    /// What a request that would retire this worker for itself asks
    /// ([`ModelProcessPool::make_room_for_a_longer_prompt`]) — its own
    /// registration is not use by anyone else.
    fn in_use_beside(&self, request_id: Uuid, window: std::time::Duration) -> bool {
        if self.others_in_flight(request_id) > 0 {
            return true;
        }
        let mut holders = self
            .kv_holders
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        holders.retain(|_, last| last.elapsed() <= window);
        holders.keys().any(|holder| *holder != request_id)
    }

    /// This worker did work for a request just now: its idle time starts
    /// over ([`Self::idle_secs`]). A plain store, as the stamp always was: the
    /// clock only moves forward, and two stamps racing differ by a second.
    fn mark_used_now(&self, user: Requester) {
        let now = self.spawned_at.elapsed().as_secs();
        self.last_used.store(now, Ordering::Relaxed);
        if user == Requester::Owner {
            self.owner_last_used.store(now, Ordering::Relaxed);
        }
    }

    fn millis_since_spawn(&self) -> u64 {
        u64::try_from(self.spawned_at.elapsed().as_millis()).unwrap_or(u64::MAX)
    }

    /// The pool handed this worker to a caller just now. Called ONLY under the
    /// map's read guard ([`Self::handed_out_ms`]).
    fn note_handed_out(&self) {
        self.handed_out_ms
            .store(self.millis_since_spawn(), Ordering::Relaxed);
    }

    /// How long since the pool last handed this worker out.
    fn since_handed_out(&self) -> std::time::Duration {
        std::time::Duration::from_millis(
            self.millis_since_spawn()
                .saturating_sub(self.handed_out_ms.load(Ordering::Relaxed)),
        )
    }

    /// A card reading just refused to move this worker to the card.
    fn note_promotion_refused(&self) {
        self.promotion_refused_ms
            .store(self.millis_since_spawn(), Ordering::Relaxed);
    }

    /// Did a card reading refuse to move it within the last `secs`?
    fn promotion_refused_within(&self, secs: u64) -> bool {
        match self.promotion_refused_ms.load(Ordering::Relaxed) {
            NEVER_USED => false,
            at => self.millis_since_spawn().saturating_sub(at) < secs.saturating_mul(1000),
        }
    }

    /// [`Self::register_response`] for a PEER's question
    /// ([`ModelProcessPool::weigh_peer_prompt`]): the slot, without marking the
    /// worker used. A question is no work for this node's own users, so it
    /// must not keep a model looking busy — one every few seconds would hold
    /// off the idle unload and the card reclaim forever (security review,
    /// 2026-10-18). The slot itself lives the milliseconds of the answer.
    fn register_question(
        self: &Arc<Self>,
        request_id: Uuid,
        tx: ResponseTx,
    ) -> (ResponseGuard, Option<u64>) {
        self.register_unseen(request_id, tx, true)
    }

    fn register_unseen(
        self: &Arc<Self>,
        request_id: Uuid,
        tx: ResponseTx,
        cancel_on_drop: bool,
    ) -> (ResponseGuard, Option<u64>) {
        let (token, displaced) = claim_response_slot(&self.responses, request_id, tx);
        // Before the request is sent, as the load flag is: the card worker
        // beside this one pauses its hold as this work starts (#489).
        card_work_changed(&self.card_work_changed);
        if displaced.is_some() {
            tracing::warn!(
                %request_id,
                "Second in-flight generate for this request_id — superseding \
                 the earlier attempt (router retry)"
            );
        }
        (
            ResponseGuard {
                responses: self.responses.clone(),
                request_id,
                token,
                worker: cancel_on_drop.then(|| self.clone()),
                used_until_now: None,
                card_work_changed: Some(self.card_work_changed.clone()),
            },
            displaced,
        )
    }

    /// Seconds since this worker last had a request registered against it.
    ///
    /// A worker that has never been used reports its full residency, which is
    /// the honest answer: it has been idle for as long as it has existed.
    fn idle_secs(&self) -> u64 {
        self.spawned_at
            .elapsed()
            .as_secs()
            .saturating_sub(self.last_used.load(Ordering::Relaxed))
    }

    /// How long this worker has gone unused as `asking`'s request sees it —
    /// the idle time another model's request weighs before it may take the
    /// card from this one ([`vram_reclaim_eligible`]).
    ///
    /// **The swarm sees every use; the owner sees only their own** (#483 (a)):
    /// the contribution level caps what the SWARM may use of this computer,
    /// never the owner (#266), so a model answering peers keeps the card from
    /// another peer's model while it is in steady use, but not from the
    /// owner's. Field report on 0.3.300 (2026-11-20): Gemma 4 12B on the
    /// card, the owner's own 14B beside it partly on the processor at 5.1
    /// tok/s against ~20 — a peer's use was inferred, never read in the log.
    /// Never mid-reply: [`Self::in_use`] guards both readings (#93). A worker
    /// the owner never used has been idle, to them, as long as it has existed,
    /// as [`Self::idle_secs`] reads one nobody used.
    fn idle_secs_for(&self, asking: Requester) -> u64 {
        match asking {
            Requester::Swarm => self.idle_secs(),
            Requester::Owner => {
                let residency = self.spawned_at.elapsed().as_secs();
                match self.owner_last_used.load(Ordering::Relaxed) {
                    NEVER_USED => residency,
                    stamp => residency.saturating_sub(stamp),
                }
            }
        }
    }

    /// Did this node place the worker short of the card for want of its
    /// memory — on the processor, or split between the two? A split is only
    /// ever admission's answer to a card without room for the whole model
    /// (`get_or_spawn`'s `card_split`); the user's own `gpu_layers` never
    /// makes one.
    fn short_of_the_card(&self) -> bool {
        self.placed_on_cpu_because.is_some()
            || self.card_split.is_some_and(CardSplit::is_short_of_the_card)
    }

    /// Card memory this worker holds and gives back when it is retired: a
    /// split's charge, which is against the card. 0 for a worker charged
    /// against RAM (the processor) or wholly on the card (never promoted).
    fn card_mb_held(&self) -> u64 {
        if self.charged_against_ram || self.card_split.is_none() {
            return 0;
        }
        self.charged_mb.load(Ordering::Acquire)
    }

    /// True when `request_id`'s entry has been taken over by a later attempt.
    /// Distinguishes "a retry displaced me" from "the worker really died",
    /// which present identically as a closed response channel.
    fn response_superseded(&self, request_id: Uuid, token: u64) -> bool {
        response_slot_superseded(&self.responses, request_id, token)
    }
}

impl ResponseGuard {
    /// Mark the request as completed so dropping this guard does NOT cancel it.
    /// Every path that returns a terminal result must call this — otherwise a
    /// normal completion sends a spurious cancel for a request the worker has
    /// already finished. (Harmless, since the worker treats unmatched cancels
    /// as no-ops and sweeps them, but it's pure noise on the IPC socket.)
    fn disarm(&mut self) {
        self.worker = None;
    }
}

impl Drop for ResponseGuard {
    fn drop(&mut self) {
        // Identity-checked: if a retry with the same request_id has already
        // replaced our entry, that entry belongs to the retry and removing it
        // would fail a request that is still perfectly healthy.
        self.responses
            .remove_if(&self.request_id, |_, (tok, _)| *tok == self.token);
        if let Some(wake) = &self.card_work_changed {
            card_work_changed(wake);
        }
        if let Some((worker, user)) = self
            .used_until_now
            .take()
            .and_then(|(w, user)| w.upgrade().map(|w| (w, user)))
        {
            worker.mark_used_now(user);
        }

        // Still armed → the caller went away before a terminal reply arrived:
        // client disconnected, or a `tokio::select!` timeout fired. Tell the
        // worker to stop; otherwise
        // it computes to completion and the reader actor silently discards the
        // result. For a `Generate` that is the whole remaining token budget of
        // GPU time spent on output nobody will read.
        let Some(worker) = self.worker.take() else {
            return;
        };
        // Drop is sync, so the IPC write is handed to a task. `try_current`
        // rather than `Handle::current` because a guard can be dropped outside
        // a runtime in tests, where losing a best-effort cancel is fine.
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return;
        };
        let request_id = self.request_id;
        handle.spawn(async move {
            if worker.dead.load(Ordering::Acquire) {
                return;
            }
            let mut writer = worker.writer.lock().await;
            let _ = send_daemon(&mut *writer, &DaemonMsg::CancelRequest { request_id }, &[]).await;
        });
    }
}

/// How long a request seen only once still counts as decoding here, before
/// its own pace is known.
const FIRST_FORWARD_ACTIVE: std::time::Duration = std::time::Duration::from_millis(250);
/// The longest a request counts as decoding after its last forward, however
/// slow its pace — a processor or a far WAN ring.
const MAX_STREAM_GAP: std::time::Duration = std::time::Duration::from_secs(3);

/// The requests whose decode forwards reached the batch scheduler recently,
/// by model, with each one's own pace — the only forwards a wait could batch
/// with.
///
/// **A stream counts while its NEXT forward is due** — within twice the gap
/// between its last two — not for a fixed window. A fixed 2 s window was
/// measured holding every request back for the first 2 s after the previous
/// one FINISHED (2026-09-29: half of 390 tokens of back-to-back requests paid
/// the full wait; an agent's next call is exactly that shape). A card stream
/// forwarding every ~30 ms stops counting ~60 ms after it ends; a WAN stream
/// forwarding every 500 ms, ~1 s after.
#[derive(Default)]
struct ActiveStreams {
    /// request → (model, last forward, gap before it)
    last_seen: std::collections::HashMap<
        uuid::Uuid,
        (ModelId, std::time::Instant, Option<std::time::Duration>),
    >,
}

impl ActiveStreams {
    fn note(&mut self, request_id: uuid::Uuid, model_id: &ModelId, now: std::time::Instant) {
        self.last_seen
            .retain(|_, (_, at, _)| now.duration_since(*at) < MAX_STREAM_GAP);
        let gap = self
            .last_seen
            .get(&request_id)
            .map(|(_, at, _)| now.duration_since(*at));
        self.last_seen
            .insert(request_id, (model_id.clone(), now, gap));
    }

    /// Other requests decoding on `model_id` — the forwards worth waiting for.
    fn others_on(&self, model_id: &ModelId, except: uuid::Uuid, now: std::time::Instant) -> usize {
        self.last_seen
            .iter()
            .filter(|(id, (m, at, gap))| {
                let due_within = gap.map_or(FIRST_FORWARD_ACTIVE, |g| (g * 2).min(MAX_STREAM_GAP));
                **id != except && m == model_id && now.duration_since(*at) < due_within
            })
            .count()
    }
}

/// How many distinct requests' forwards to collect before dispatching, or
/// `None` to dispatch at once.
///
/// **A lone stream does not wait.** The window used to run after EVERY first
/// forward, so a request with nothing to batch with paid it on every token, on
/// every node of a split: measured 2026-09-29 on a two-node split of
/// qwen2.5-coder-7b on one card at ~0 ms of network, 6.6 ms from the daemon's
/// send to the worker's receipt, per node per token — 13 of a 36 ms token,
/// the split at 54% of the same model run locally. The config's own note said
/// "single-request workloads are unaffected" and that WSL2's timer resolution
/// made the window moot; neither held. Iteration-level schedulers (Orca,
/// OSDI '22; vLLM) never delay one request for a batch that is not there, and
/// Triton's dynamic batcher waits only up to a queue delay it is configured to
/// accept.
///
/// With others decoding on the same model the wait is for THEM — it ends the
/// moment each has arrived, not at the deadline, which still caps it.
fn collection_target(
    others_decoding: usize,
    collection_ms: u64,
    max_batch: usize,
) -> Option<usize> {
    if collection_ms == 0 || others_decoding == 0 || max_batch <= 1 {
        return None;
    }
    Some((others_decoding + 1).min(max_batch))
}

/// Auto-coalescing batch scheduler loop. One per `ModelProcessPool`. Collects
/// `Forward` requests into time-windowed batches grouped by `model_id`, then
/// dispatches each group via `pool.forward_batch(...)`. Responses are fanned
/// out to the per-request `oneshot::Sender`s.
///
/// Worker-side CPU fallback (`run_fused_batch_forward` errors out on CPU, which
/// `handle_batch_forward` catches and runs sequentially) means this is safe on
/// every device — GPU workers run the fused `SplitModel::forward_batch` path,
/// CPU workers run the sequential path with zero regression.
async fn batch_scheduler_loop(
    pool: Arc<ModelProcessPool>,
    mut rx: mpsc::Receiver<BatchSchedulerMsg>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
) {
    use std::collections::HashMap;
    use std::time::{Duration, Instant};
    let mut active = ActiveStreams::default();
    loop {
        let first = tokio::select! {
            biased;
            _ = shutdown_rx.changed() => {
                tracing::debug!("batch_scheduler_loop: shutdown observed");
                return;
            }
            msg = rx.recv() => match msg {
                Some(m) => m,
                None => return, // sender side dropped
            },
        };
        let collection_ms = pool
            .batch_collection_ms
            .load(std::sync::atomic::Ordering::Relaxed);
        let max_batch = pool
            .max_concurrent_decode_batch
            .load(std::sync::atomic::Ordering::Relaxed) as usize;
        let max_batch = max_batch.max(1);

        let (first_request, first_model) = {
            let BatchSchedulerMsg::Forward { ref fwd, .. } = first;
            (fwd.request_id, fwd.model_id.clone())
        };
        let now = Instant::now();
        active.note(first_request, &first_model, now);
        let target = collection_target(
            active.others_on(&first_model, first_request, now),
            collection_ms,
            max_batch,
        );

        let mut pending: Vec<BatchSchedulerMsg> = vec![first];
        if let Some(target) = target {
            let deadline = now + Duration::from_millis(collection_ms);
            let arrived_on_model = |pending: &[BatchSchedulerMsg]| {
                pending
                    .iter()
                    .filter(|BatchSchedulerMsg::Forward { fwd, .. }| fwd.model_id == first_model)
                    .map(|BatchSchedulerMsg::Forward { fwd, .. }| fwd.request_id)
                    .collect::<std::collections::HashSet<_>>()
                    .len()
            };
            while pending.len() < max_batch && arrived_on_model(&pending) < target {
                let now = Instant::now();
                if now >= deadline {
                    break;
                }
                match tokio::time::timeout(deadline - now, rx.recv()).await {
                    Ok(Some(msg)) => {
                        let BatchSchedulerMsg::Forward { ref fwd, .. } = msg;
                        active.note(fwd.request_id, &fwd.model_id, Instant::now());
                        pending.push(msg);
                    }
                    Ok(None) => {
                        // Sender dropped — process what we have and exit.
                        dispatch_scheduler_pending(&pool, pending).await;
                        return;
                    }
                    Err(_) => break, // deadline elapsed
                }
            }
        }

        // Group by model_id — forward_batch requires a single model.
        let mut by_model: HashMap<ModelId, Vec<BatchSchedulerMsg>> = HashMap::new();
        for msg in pending {
            let BatchSchedulerMsg::Forward { ref fwd, .. } = msg;
            by_model.entry(fwd.model_id.clone()).or_default().push(msg);
        }
        for (_, msgs) in by_model {
            dispatch_scheduler_group(&pool, msgs).await;
        }
    }
}

async fn dispatch_scheduler_pending(pool: &Arc<ModelProcessPool>, pending: Vec<BatchSchedulerMsg>) {
    use std::collections::HashMap;
    let mut by_model: HashMap<ModelId, Vec<BatchSchedulerMsg>> = HashMap::new();
    for msg in pending {
        let BatchSchedulerMsg::Forward { ref fwd, .. } = msg;
        by_model.entry(fwd.model_id.clone()).or_default().push(msg);
    }
    for (_, msgs) in by_model {
        dispatch_scheduler_group(pool, msgs).await;
    }
}

/// Dispatch a same-model group: 1 request → `pool.forward_direct`, ≥2 →
/// `pool.forward_batch`. Fan out to each `resp_tx`.
async fn dispatch_scheduler_group(pool: &Arc<ModelProcessPool>, msgs: Vec<BatchSchedulerMsg>) {
    if msgs.is_empty() {
        return;
    }
    if msgs.len() == 1 {
        let BatchSchedulerMsg::Forward {
            fwd,
            requester,
            resp_tx,
        } = msgs.into_iter().next().expect("len == 1 checked above");
        // Only decode steps are batch-scheduled; an owner's mark made at its
        // prompt pass stays on the request, so naming the requester changes
        // no width — it stamps whose use the step was (#483 (a)).
        let result = pool.forward_direct(fwd, None, requester).await;
        let _ = resp_tx.send(result);
        return;
    }
    let mut forwards = Vec::with_capacity(msgs.len());
    let mut users = Vec::with_capacity(msgs.len());
    let mut resp_txs = Vec::with_capacity(msgs.len());
    for BatchSchedulerMsg::Forward {
        fwd,
        requester,
        resp_tx,
    } in msgs
    {
        forwards.push(fwd);
        users.push(requester);
        resp_txs.push(resp_tx);
    }
    let n = forwards.len();
    match pool.forward_batch(forwards, &users).await {
        Ok(results) => {
            if results.len() != n {
                for tx in resp_txs {
                    let _ = tx.send(Err(SwarmError::Internal(format!(
                        "batch result count mismatch: expected {n}, got {}",
                        results.len()
                    ))));
                }
                return;
            }
            // Fan out in sender order (forward_batch preserves input order).
            for (tx, result) in resp_txs.into_iter().zip(results) {
                let _ = tx.send(Ok(result));
            }
        }
        Err(e) => {
            // SwarmError isn't Clone, so we can't propagate `e` to each
            // tx. The vast-majority batch failure cause is worker death
            // (subprocess closed IPC) — ServiceUnavailable is correct
            // for that. Was previously Internal which mapped to 500 and
            // misled operators about the failure class.
            let err_str = e.to_string();
            for tx in resp_txs {
                let _ = tx.send(Err(SwarmError::ServiceUnavailable(format!(
                    "batch failed: {err_str}"
                ))));
            }
        }
    }
}

/// Manages one worker subprocess per loaded ModelId.
///
/// When a model is unloaded, its worker process is killed and the OS/CUDA
/// driver reclaims all GPU memory immediately — no restart required.
///
/// ## Concurrency model
///
/// Each WorkerHandle has a `Mutex<write_half>` and a reader-actor task that
/// multiplexes inbound `WorkerMsg`s by `request_id` to per-request channels.
/// `forward()` and `generate()` only hold the write mutex long enough to send
/// one framed IPC message; waiting for the response happens off-lock on the
/// per-request channel. **Multiple concurrent `forward()` / `generate()` calls
/// against the same model no longer block each other**, as long as the worker
/// itself can make progress on them.
///
/// Compute-side serialization still applies: the worker subprocess handles one
/// forward call at a time internally (until Item 7 BatchGenerate lands proper
/// slot batching). So two concurrent requests share the worker in a "fair"
/// interleaved fashion — each request's message arrives at the worker in the
/// order it was sent, and responses flow back in whatever order the worker
/// emits them.
/// Why a model is running on the CPU.
///
/// Kept as three distinct values rather than a bool because they call for three
/// different actions from the user: change a setting, free some memory, or
/// accept that this machine's GPU is too old. Downstream they were all just
/// `--gpu-layers 0`, which is how a correct setting and an override came to look
/// identical — see [`ModelProcessPool::cpu_reason`].
/// Does a model being spawned count against the system-RAM budget (and get a
/// KV budget handed to its worker)? Yes when it is being sent to the CPU, when
/// no GPU was detected on this node, or when this build cannot drive one.
/// Pure, so the truth table is pinned by `ram_is_charged_wherever_the_model_
/// can_only_land_in_ram`.
pub(crate) fn charges_ram(going_to_cpu: bool, gpu_detected: bool, build_has_cuda: bool) -> bool {
    going_to_cpu || !gpu_detected || !build_has_cuda
}

/// What one range a worker holds was charged: `mb` to the worker's own
/// accountant (`WorkerHandle::charged_mb` — the card, or RAM for a processor
/// worker) and `host_mb` to the machine beside a card (`host_share_mb`), for
/// a range grown partly onto the processor (#265).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct RangeCost {
    mb: u64,
    host_mb: u64,
}

impl RangeCost {
    fn plus(self, other: Self) -> Self {
        Self {
            mb: self.mb.saturating_add(other.mb),
            host_mb: self.host_mb.saturating_add(other.host_mb),
        }
    }
}

/// Whether a forward's run is one rank's share of a tensor-parallel group.
/// A worker serves a PLAIN run inside a range it loaded from that copy's
/// weights (#449, `split::view`), so the daemon charges nothing for it; a
/// rank's share holds different weights — a slice of every matrix — so it is
/// charged and loaded as itself, as every run was before (review 2026-11-13:
/// charged nothing, the worker read it from disk all the same). REQUIRED of
/// every "would this load" question that a tensor-parallel forward reaches.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum RunShape {
    Plain,
    TensorParallel,
}

impl RunShape {
    pub(crate) fn of(tensor_parallel: bool) -> Self {
        if tensor_parallel {
            Self::TensorParallel
        } else {
            Self::Plain
        }
    }
}

/// A range a worker has been charged for, what it cost, and where it went.
#[derive(Debug, Clone, Copy)]
struct RangeCharge {
    range: (u32, u32),
    cost: RangeCost,
    /// Its card/processor split, where it has one: the spawn's
    /// (`WorkerHandle::card_split`) for a range placed as the spawn placed its
    /// own, the growth's for a range grown across both devices (#265). `None`:
    /// wholly on the device the worker is charged to.
    split: Option<CardSplit>,
}

impl RangeCharge {
    /// Layers of this range on the card, for a worker charged to the card:
    /// a split's `on_card` (`--gpu-layers` counted within the range; which
    /// ones, `hybrid::processor_run`), else all of them.
    fn layers_on_card(&self) -> u32 {
        let width = self.range.1.saturating_sub(self.range.0);
        self.split.map_or(width, |split| {
            u32::try_from(split.card_share().0)
                .unwrap_or(u32::MAX)
                .min(width)
        })
    }
}

/// What a spawn's admission charged, carried onto its worker so the release
/// subtracts exactly this worker's share (`WorkerHandle::charged_mb`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SpawnCharge {
    /// `mb` is against the RAM budget (`charges_ram`), else the card's.
    against_ram: bool,
    mb: u64,
    /// A card/processor split's processor share, against RAM (#264).
    host_share_mb: u64,
}

impl SpawnCharge {
    /// Whichever budget the worker is charged against is the one its release
    /// subtracts from; a split's RAM charge is its processor share.
    fn decided(charge_ram: bool, vram_mb: u64, ram_mb: u64) -> Self {
        if charge_ram {
            Self {
                against_ram: true,
                mb: ram_mb,
                host_share_mb: 0,
            }
        } else {
            Self {
                against_ram: false,
                mb: vram_mb,
                host_share_mb: ram_mb,
            }
        }
    }
}

/// The worker arguments that say where its layers go — the placement the
/// spawn decided, the ONE statement of where the worker is going, used for
/// both the spawn argument and the handle.
fn worker_placement_args(
    placed_on_cpu_because: Option<CpuReason>,
    card_split: Option<CardSplit>,
    configured_gpu_layers: i32,
) -> Vec<String> {
    let gpu_layers = match (placed_on_cpu_because, card_split) {
        (Some(_), _) => 0,
        // A partial split: the worker places this many of its layers on the
        // card and the rest on the processor. Reaches the loader through
        // `GPU_LAYER_LIMIT`, the same route `--kv-budget-bytes` takes — the
        // daemon decides, the worker obeys.
        (None, Some(CardSplit::Layers { on_card, .. })) => on_card as i32,
        // Every layer on the card, whatever count the user set: the experts
        // below are what this placement keeps off it.
        (None, Some(CardSplit::ExpertsInRam { .. })) => -1,
        (None, None) => configured_gpu_layers,
    };
    let mut args = vec!["--gpu-layers".to_string(), gpu_layers.to_string()];
    // ...and the layers whose routed experts stay in RAM, which reach the
    // loader through `split::CPU_EXPERT_LAYERS` (#138 (3)).
    if let (None, Some(CardSplit::ExpertsInRam { in_ram, .. })) =
        (placed_on_cpu_because, card_split)
    {
        args.push("--cpu-moe-layers".to_string());
        args.push(in_ram.to_string());
    }
    args
}

/// What a spawn keeps in the machine's memory, and so charges to it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RamShare {
    /// Layers `[start, end)` — weights, conversation cache and the process —
    /// the whole segment of a processor placement, or a whole-layer split's
    /// processor run.
    Layers((u32, u32)),
    /// The routed experts of the segment's first `layers`, beside a card that
    /// holds everything else of them, their caches included
    /// ([`CardSplit::ExpertsInRam`]).
    Experts { layers: usize },
}

/// What a spawn charges to the machine's memory: the whole `segment` when it
/// lands there (`charges_ram`), a whole-layer split's processor-held run
/// ([`CardSplit::processor_run`]: where `place` puts it — a far segment's
/// first layers, a first segment's tail, a whole model's run early in the
/// middle), the experts a split keeps in RAM, and nothing for a model wholly
/// on the card.
///
/// **A split's processor share was charged to nothing** (#264): its weights,
/// their conversation cache and the worker process sat outside
/// `resources.max_ram_mb`, a processor worker started beside it was admitted
/// into memory the split already held, and its processor-side cache had no
/// budget from the daemon (#262). Charged here, it goes through the same RAM
/// admission and refusal as a processor placement — and a run of layers, the
/// same `--kv-budget-bytes` grant.
fn ram_charged_share(
    charge_ram: bool,
    segment: (u32, u32),
    split: Option<CardSplit>,
    place: crate::inference::split::hybrid::RunPlace,
) -> Option<RamShare> {
    if charge_ram {
        return Some(RamShare::Layers(segment));
    }
    match split? {
        split @ CardSplit::Layers { .. } => {
            split.processor_run(segment, place).map(RamShare::Layers)
        }
        CardSplit::ExpertsInRam { in_ram, .. } => {
            (in_ram > 0).then_some(RamShare::Experts { layers: in_ram })
        }
    }
}

/// What a spawn charges the machine's memory
/// (`ModelProcessPool::machine_charge`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MachineCharge {
    /// The layers or experts the placement keeps there ([`ram_charged_share`]).
    share: Option<RamShare>,
    /// What that share costs, in MB.
    share_mb: u64,
    /// The host-resident tensors a placement reaching the card keeps there
    /// (`VramFootprintInputs::host_resident_bytes`), in MB.
    beside_card_mb: u64,
}

impl MachineCharge {
    /// The whole charge, in MB.
    fn mb(self) -> u64 {
        self.share_mb.saturating_add(self.beside_card_mb)
    }
}

/// What a fresh load would take on another computer
/// ([`ModelProcessPool::fresh_load_room`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct FreshLoadRoom {
    /// The widest run of the model's layers that would load.
    pub(crate) layers: u32,
    /// Of them, the ones its card would hold — 0 on a computer whose models
    /// run on its processor.
    pub(crate) on_card: u32,
}

/// Add `mb` to a model's recorded charge.
///
/// Segments of one model share a worker, so a second segment ADDS to what the
/// first reserved rather than replacing it. Replacing was correct only while a
/// spawn charged the WHOLE model whatever it was about to load; now that it
/// prices the segment, an overwrite would silently forget the first one.
fn add_reserved(map: &dashmap::DashMap<ModelId, u64>, model_id: &ModelId, mb: u64) {
    *map.entry(model_id.clone()).or_insert(0) += mb;
}

/// What a worker's guessers keep on the card beyond the ranges it was charged
/// for, and the card-held output head it would lend a later range ending the
/// model (`WorkerMsg::CardBeside`, #481 (5)), in MB.
///
/// The reported half is written by the reader actor as reports arrive; the
/// charged half only by [`ModelProcessPool::charge_what_its_guessers_hold`],
/// under `spawn_lock`, which moves the worker's charge (`charged_mb` and the
/// model's `vram_reserved_mb`) by the difference. A departure releases
/// `charged_mb` whole, so what was folded in goes with it.
#[derive(Debug, Default)]
pub(crate) struct CardBeside {
    reported_mb: AtomicU64,
    lends_head_mb: AtomicU64,
    charged_mb: AtomicU64,
}

impl CardBeside {
    fn note_report(&self, guessers_bytes: u64, lends_head_bytes: u64) {
        const MIB: u64 = 1024 * 1024;
        self.reported_mb
            .store(guessers_bytes.div_ceil(MIB), Ordering::Release);
        // Rounded down: a growth is never priced below what it loads.
        self.lends_head_mb
            .store(lends_head_bytes / MIB, Ordering::Release);
    }

    /// The card-held output head the worker lends, MB.
    fn lends_head_mb(&self) -> u64 {
        self.lends_head_mb.load(Ordering::Acquire)
    }
}

/// What a departing worker owed, read off its handle before it is dropped.
///
/// Exists because `unload_model` waits for the subprocess to exit — which
/// outlives the handle — and the release still needs that worker's own figures
/// rather than whatever the model's entry holds by then.
struct DepartedWorker {
    freed_gpu_memory: bool,
    charged_mb: u64,
    charged_against_ram: bool,
    host_share_mb: u64,
    /// `WorkerHandle::asked_to_load`: whether it may hold the share it was charged.
    asked_to_load: bool,
}

impl From<&WorkerHandle> for DepartedWorker {
    fn from(h: &WorkerHandle) -> Self {
        Self {
            // Read from the WORKER, not from `effective_gpu_layers`. That asks
            // where a spawn happening *now* would go, and its pin is cleared
            // while the processor worker it produced is still running — so a
            // model on its way back to the card answered "GPU" and lifted every
            // other model's pin on the strength of memory it never held.
            //
            // Through `holds_gpu_memory`, so the `device` this line reports and
            // the budget the release below subtracts from cannot disagree:
            // reading `placed_on_cpu_because` directly logged `device="gpu"`
            // for every worker on a machine with no graphics card.
            freed_gpu_memory: h.holds_gpu_memory(),
            charged_mb: h.charged_mb.load(Ordering::Acquire),
            charged_against_ram: h.charged_against_ram,
            host_share_mb: h.host_share_mb.load(Ordering::Acquire),
            asked_to_load: h.asked_to_load.load(Ordering::Acquire),
        }
    }
}

impl DepartedWorker {
    /// The card memory this worker was charged and gives back on exit — what
    /// its retirement waits to read free again (`unload_model`, #3 (j13)). 0
    /// for a worker in system memory (its processor share is `host_share_mb`),
    /// and for one never asked to load anything: charged at its spawn, it
    /// loads on its first message, so until then it holds its device context
    /// alone. Waited for at its charge, its release never rose a quarter, never
    /// settled, and held the spawn lock the whole 5 s (pre-release review
    /// 2026-11-14). The charge itself is released either way
    /// (`after_worker_gone_charge`).
    ///
    /// Prior art: Ollama's `waitForVRAMRecovery` (`server/sched.go`) waits for
    /// every runner on a discrete card — but a runner enters its scheduler's
    /// loaded set only once its load has finished, so it never waits on one
    /// that allocated nothing. Ours is charged before it loads.
    fn card_mb_it_frees(&self) -> u64 {
        if self.freed_gpu_memory && !self.charged_against_ram && self.asked_to_load {
            self.charged_mb
        } else {
            0
        }
    }
}

/// Is a retired card worker's memory waited for before the next load reads
/// the card (#3 (j13))? A/B `SWARMLLM_CARD_MEMORY_BACK=0` turns the wait off.
fn card_memory_back_on() -> bool {
    std::env::var("SWARMLLM_CARD_MEMORY_BACK").as_deref() != Ok("0")
}

/// Take `mb` back off a model's recorded charge. Returns whether the model is
/// now charged nothing at all.
///
/// The inverse of `add_reserved`, and it must be a subtraction rather than a
/// removal: several workers' lifetimes can overlap under one model id — a
/// replacement is admitted and charged before the dead one is evicted — so
/// dropping the key would discard a charge that is still live. Saturating,
/// because an under-run would otherwise wrap to a budget of 18 exabytes and
/// admit everything for ever.
fn release_reserved(map: &dashmap::DashMap<ModelId, u64>, model_id: &ModelId, mb: u64) -> bool {
    let mut emptied = false;
    if let Some(mut e) = map.get_mut(model_id) {
        *e = e.saturating_sub(mb);
        emptied = *e == 0;
    }
    if emptied {
        map.remove_if(model_id, |_, v| *v == 0);
    }
    emptied
}

/// The layer count, first-segment flag and weight bytes a footprint estimate
/// should describe for `segment` of a `block_count`-layer model whose shards
/// total `shard_bytes`.
///
/// `None` asks about the whole model. Weights are charged in proportion to the
/// layers mapped — the same approximation `auto_manage::estimate_segment_mb`
/// and the scheduler's `bytes_per_layer` make, so the planner and the loader
/// price a segment identically.
pub(crate) fn segment_shape(
    block_count: u64,
    shard_bytes: u64,
    segment: Option<(u32, u32)>,
) -> (u64, bool, u64) {
    let Some((start, end)) = segment else {
        return (block_count, true, shard_bytes);
    };
    let layers = u64::from(end.saturating_sub(start)).clamp(1, block_count.max(1));
    let weights = if block_count == 0 || layers >= block_count {
        shard_bytes
    } else {
        shard_bytes / block_count * layers
    };
    (layers, start == 0, weights)
}

/// A segment's weights where the loader puts them ([`segment_weights`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SegmentWeights {
    /// Every tensor the segment loads, at its quantized size.
    pub total: u64,
    /// Of which kept in the machine's memory whatever the device
    /// (`VramFootprintInputs::host_resident_bytes`).
    pub host_resident: u64,
    /// Of which the ends' tables, on the segment's main device
    /// (`VramFootprintInputs::head_bytes`).
    pub head: u64,
}

/// What layers `[start, end)` load of a model whose tensor table is `tensors`
/// (`(name, bytes)`), by the loader's own classification
/// (`split::segment_tensor`): their own layers' tensors, the token table on
/// the first, the output head on the last — weight-tied, the token table
/// again, once where one segment is both — and the small shared ones on
/// every segment. `None` when no tensor names a layer, so nothing here can
/// say which are whose.
///
/// The token table is counted at its QUANTIZED size, as a card reading its
/// rows on demand keeps it; where it cannot be gathered the estimator adds
/// the dequantized table on top (`resident_footprint_on`), as before.
///
/// Spread evenly over the layers instead (`segment_shape`), a 70B's first
/// segment was charged ~7 MB of its 564 MB token table and its last ~10 MB of
/// its 822 MB output head, and a card split placed one layer too many: the
/// worker found no room for the conversation (2026-10-25, FUTURE_WORK #342).
pub(crate) fn segment_weights(
    tensors: &[(&str, u64)],
    (start, end): (usize, usize),
    is_first: bool,
    is_last: bool,
) -> Option<SegmentWeights> {
    ModelWeights::of(tensors).map(|weights| weights.segment((start, end), is_first, is_last))
}

/// A model's tensor table sorted once by where the loader loads each tensor
/// (`split::segment_tensor`), so [`Self::segment`] answers
/// [`segment_weights`] for any range without walking the table again — the
/// scheduler weighs hundreds of ranges a plan (field report #039).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub(crate) struct ModelWeights {
    /// `(layer, bytes)` of each layer's own tensors, by layer — sparse, so a
    /// header's layer numbers never size an allocation.
    layers: Vec<(usize, u64)>,
    /// `layer_sums[k]`: the bytes of `layers[..k]`.
    layer_sums: Vec<u64>,
    token_table: u64,
    /// The output head and its norm (`SegmentTensor::OutputHead`).
    output_head: u64,
    host_resident: u64,
    beside_embedding: u64,
    shared: u64,
    /// No `output.weight`: the token table doubles as the output head.
    tied: bool,
}

impl ModelWeights {
    /// `None` when no tensor names a layer, so nothing can say which are whose.
    pub(crate) fn of(tensors: &[(&str, u64)]) -> Option<Self> {
        use crate::inference::split::SegmentTensor;
        let mut weights = Self {
            tied: !tensors.iter().any(|(name, _)| *name == "output.weight"),
            ..Self::default()
        };
        let mut by_layer = std::collections::BTreeMap::<usize, u64>::new();
        for &(name, bytes) in tensors {
            let slot = match crate::inference::split::segment_tensor(name) {
                SegmentTensor::Layer(idx) => by_layer.entry(idx).or_insert(0),
                SegmentTensor::Unplaced => continue,
                SegmentTensor::TokenTable => &mut weights.token_table,
                SegmentTensor::OutputHead => &mut weights.output_head,
                SegmentTensor::HostResident => &mut weights.host_resident,
                SegmentTensor::BesideEmbedding => &mut weights.beside_embedding,
                SegmentTensor::Shared => &mut weights.shared,
            };
            *slot = slot.saturating_add(bytes);
        }
        if by_layer.is_empty() {
            return None;
        }
        weights.layers = by_layer.into_iter().collect();
        weights.layer_sums = std::iter::once(0)
            .chain(weights.layers.iter().scan(0u64, |sum, &(_, bytes)| {
                *sum = sum.saturating_add(bytes);
                Some(*sum)
            }))
            .collect();
        Some(weights)
    }

    /// The table a PLAN weighs a peer's ranges by — the scheduler's bounds,
    /// its booking, auto-manage's chains — read off `meta`'s tensor table.
    /// `None` under the A/B `SWARMLLM_PEER_RANGE_WEIGHTS=average`, which
    /// weighs every range at the file's average layer, as before field report
    /// #039.
    pub(crate) fn for_planning(meta: &crate::inference::split::GgufTensorMeta) -> Option<Self> {
        if std::env::var("SWARMLLM_PEER_RANGE_WEIGHTS").as_deref() == Ok("average") {
            return None;
        }
        let tensors: Vec<(&str, u64)> = meta
            .tensors
            .iter()
            .map(|(name, location)| (name.as_str(), location.size))
            .collect();
        Self::of(&tensors)
    }

    /// Layers `[start, end)`' own tensors.
    fn layer_bytes(&self, start: usize, end: usize) -> u64 {
        let at = |layer: usize| self.layers.partition_point(|&(idx, _)| idx < layer);
        let (from, to) = (at(start), at(end.max(start)));
        self.layer_sums[to].saturating_sub(self.layer_sums[from])
    }

    /// What `[start, end)` loads: its own layers' tensors, the token table on
    /// the first, the output head on the last — weight-tied, the token table
    /// again, once where one segment is both — what the loader keeps in host
    /// memory and beside the embeddings on the first, and the small shared
    /// tensors on every segment.
    pub(crate) fn segment(
        &self,
        (start, end): (usize, usize),
        is_first: bool,
        is_last: bool,
    ) -> SegmentWeights {
        // One tensor: a segment that is first and last shares it.
        let token_table = if is_first || (is_last && self.tied) {
            self.token_table
        } else {
            0
        };
        let output_head = if is_last { self.output_head } else { 0 };
        let (host_resident, beside_embedding) = if is_first {
            (self.host_resident, self.beside_embedding)
        } else {
            (0, 0)
        };
        let head = token_table.saturating_add(output_head);
        SegmentWeights {
            total: self
                .layer_bytes(start, end)
                .saturating_add(self.shared)
                .saturating_add(host_resident)
                .saturating_add(beside_embedding)
                .saturating_add(head),
            host_resident,
            head,
        }
    }
}

/// The weights loading `range` of `weights`' `num_layers`-layer model adds
/// to a worker holding `held`, in bytes — [`layers_added_by`] in bytes, by
/// the same rule: an exact hit adds nothing; anything else loads as a
/// segment of its own, its ends' tables included ([`ModelWeights::segment`]),
/// and gives back the releasable share of each range it strictly contains.
/// `on_card` leaves out what the loader keeps in host memory whatever the
/// device, as a card's bound does (`scheduler::weight_bytes_per_layer`).
pub(crate) fn bytes_added_by(
    range: (u32, u32),
    held: &[HeldRange],
    weights: &ModelWeights,
    num_layers: u32,
    on_card: bool,
) -> u64 {
    if held.iter().any(|h| h.covers_without_a_load(range)) {
        return 0;
    }
    let loads = |(start, end): (u32, u32)| {
        let w = weights.segment(
            (start as usize, end as usize),
            start == 0,
            end >= num_layers,
        );
        if on_card {
            w.total.saturating_sub(w.host_resident)
        } else {
            w.total
        }
    };
    let released = held
        .iter()
        .filter(|h| strictly_subsumes(range, h.range))
        .fold(0u64, |acc, h| {
            let width = h.range.1.saturating_sub(h.range.0).max(1);
            let share = u64::from(h.releasable_layers.min(width));
            acc.saturating_add(loads(h.range).saturating_mul(share) / u64::from(width))
        });
    loads(range).saturating_sub(released)
}

/// `(fixed_mb, per_layer_mb)` that `estimate` charges a MIDDLE segment of the
/// model `base` describes (its whole-model inputs) — weights charged in
/// proportion to the layers, as `segment_shape` charges them at admission. The estimate is affine in the
/// layer count — weights and KV scale with it, the process overhead does not —
/// so two points determine it, and taking them from the estimator itself means
/// nothing here restates its arithmetic.
///
/// **The KV cache scales with the segment too.** The estimator charges the
/// segment's own caches (`VramFootprintInputs::kv`; #228: three in four of
/// Qwen 3.5's layers carry a fixed state instead); left at the whole model's,
/// every point charged the WHOLE cache, so the curve put all of it in the
/// fixed term and a partial segment was charged the model's entire cache. And
/// the two points are the whole model and half of it, not one layer and two:
/// MB rounding bends a slope taken over a single layer.
fn cost_curve_of(
    base: &crate::model::auto_manage::vram::VramFootprintInputs,
    estimate: fn(&crate::model::auto_manage::vram::VramFootprintInputs) -> u64,
) -> Option<(u64, u64)> {
    let total = base.segment_layers;
    if total == 0 {
        return None;
    }
    let at = |layers: u64| {
        let mut i = *base;
        i.segment_layers = layers;
        i.is_first = false;
        i.quantized_weight_bytes = base.quantized_weight_bytes / total * layers;
        // In proportion too, as the weights it is part of: the card's curve
        // then prices the card-held weights, the processor's all of them (#296).
        i.host_resident_bytes = base.host_resident_bytes / total * layers;
        // A middle segment carries neither end's table; the curve keeps them
        // in its weights, spread evenly, as before (#342's residual).
        i.head_bytes = 0;
        i.kv = base.kv.share(layers, total);
        estimate(&i)
    };
    let half = total / 2;
    if half == 0 {
        // A one-layer model: no slope to separate from the fixed terms, so
        // charge all of it as the one layer.
        return Some((0, at(1)));
    }
    let (at_half, at_whole) = (at(half), at(total));
    // Rounded UP to a whole MB, so the line is exact for the whole model and
    // within a MB a layer BELOW the estimator for any shorter segment — never
    // above it: a peer's ceiling must not be weighed more strictly than its own
    // admission weighs it. The cost is on the LOCAL bound
    // (`max_local_hostable_layers`), which may offer a segment up to a MB a
    // layer more than admission then grants — a refusal the router re-plans
    // around (`note_local_memory_refusal`); the one-and-two-layer points this
    // replaced erred by as much in either direction. The proportional cache
    // is a floor too: a recurrent model's real segment can keep one more
    // cache than its share.
    let per_layer = at_whole.saturating_sub(at_half).div_ceil(total - half);
    Some((at_whole.saturating_sub(per_layer * total), per_layer))
}

/// How many layers fit in `free_mb` once the fixed terms are paid.
///
/// `None` when there is no per-layer cost to divide by — unknowable, never
/// "no room" (see `max_hostable_layers` for why that distinction is load
/// bearing).
/// `SWARMLLM_DRAFTER_ROOM_FIRST=average` counts the room beside a guest on the
/// average layer alone, as before #376 — an A/B inside one binary. Read at
/// each plan, so a test run can flip it.
fn first_range_priced_beside_guest() -> bool {
    std::env::var("SWARMLLM_DRAFTER_ROOM_FIRST").map_or(true, |v| v.trim() != "average")
}

pub(crate) fn layers_that_fit(free_mb: u64, fixed_mb: u64, per_layer_mb: u64) -> Option<u32> {
    if per_layer_mb == 0 {
        return None;
    }
    Some((free_mb.saturating_sub(fixed_mb) / per_layer_mb) as u32)
}

/// Does loading `incoming` make the resident range `held` redundant?
///
/// **The worker's own rule, restated once for the daemon** —
/// `model_worker::subsumed_segment_keys`: strict containment only. A range
/// EQUAL to `incoming` is the caller's cache hit, not something to drop, and a
/// partial overlap describes layers each range still needs on its own.
fn strictly_subsumes(incoming: (u32, u32), held: (u32, u32)) -> bool {
    held.0 >= incoming.0 && held.1 <= incoming.1 && held != incoming
}

/// One layer range a live worker already holds, as the planner must see it.
///
/// Read by the scheduler's local capacity bound so that a plan this node makes
/// is a plan its loader will take (FUTURE_WORK #95). `releasable_layers` is
/// NOT always the range's width: it is what `charge_additional_segment` takes
/// off its admission when a new range strictly contains this one, which is the
/// range's recorded CHARGE — and the spawn records its first segment at zero,
/// because the spawn's own admission already paid for it. Pricing that range at
/// its width would plan consolidations the loader then refuses.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HeldRange {
    pub range: (u32, u32),
    pub releasable_layers: u32,
    /// Its holder serves any run inside it from its weights (#449,
    /// `split::view`): such a run adds nothing. This node's own ranges where
    /// `SWARMLLM_ELASTIC_SPANS` is on; a peer's where it advertises
    /// `features::SERVES_SLICES` — an older peer loads the run again.
    pub serves_slices: bool,
}

impl HeldRange {
    /// Is `range` run by this held range with nothing loaded: the range
    /// itself, or a run inside it its holder serves from these weights? The
    /// planner prices such a run on the devices this range was loaded to
    /// (`NodeCandidate::layers_by_device`).
    pub(crate) fn covers_without_a_load(&self, range: (u32, u32)) -> bool {
        self.range == range
            || (self.serves_slices
                && self.range.0 <= range.0
                && range.1 <= self.range.1
                && range.0 < range.1)
    }
}

/// What a spawn refused system memory says when no itemised footprint can be
/// given — the spawn's own words, and a peer's answer when it weighs the same
/// spawn before the prompt pass (`ModelProcessPool::peer_load_refusal`).
fn ram_refusal_words(model: &str, needed_mb: u64, budget_mb: u64, in_use_mb: u64) -> String {
    format!(
        "{model} needs about {needed_mb} MB of memory but this node's budget allows \
         {budget_mb} MB and {in_use_mb} MB is already in use. Raise `resources.max_ram_mb`, \
         or free memory by unloading another model."
    )
}

/// The layers two ranges share — `[a.0..a.1)` ∩ `[b.0..b.1)`, counted.
fn layers_shared(a: (u32, u32), b: (u32, u32)) -> u32 {
    a.1.min(b.1).saturating_sub(a.0.max(b.0))
}

/// The run two ranges share, empty (start = end) where they share none.
fn layers_common(a: (u32, u32), b: (u32, u32)) -> (u32, u32) {
    let start = a.0.max(b.0);
    (start, a.1.min(b.1).max(start))
}

/// How many layers of NEW memory running `range` would take on a worker that
/// already holds `held`.
///
/// Mirrors the worker, case by case (`model_worker::ensure_model_loaded`):
///
/// - a range it already holds EXACTLY is a cache hit — nothing is loaded;
/// - a range CONTAINED in a held one whose holder serves slices
///   ([`HeldRange::serves_slices`], #449) runs on those weights — nothing is
///   loaded either;
/// - a range that strictly contains held ones drops them BEFORE it loads, so
///   it costs its width less what the daemon will release for them;
/// - a range contained in a held superset whose holder does NOT serve slices
///   is read from disk and held a second time (report #021), so it costs its
///   full width, as does a partial overlap.
///
/// With nothing held this is the width, so a node with no live worker — and
/// every peer, which carries no held ranges — is priced exactly as before.
pub(crate) fn layers_added_by(range: (u32, u32), held: &[HeldRange]) -> u32 {
    let width = range.1.saturating_sub(range.0);
    if held.iter().any(|h| h.covers_without_a_load(range)) {
        return 0;
    }
    let released: u32 = held
        .iter()
        .filter(|h| strictly_subsumes(range, h.range))
        .fold(0u32, |acc, h| acc.saturating_add(h.releasable_layers));
    width.saturating_sub(released)
}

/// What a range of a model really weighs on a machine, against the average
/// every one of its bounds counts layers in.
///
/// A peer's bounds — the room it advertises, its published room, its ceiling
/// — are layer counts at the file's AVERAGE layer (`weight_bytes_per_layer`,
/// the ceiling's `segment_cost_curve`), which spreads the token table and the
/// output head over every layer. That is exact for the whole model and wrong
/// for a part of it: a range ending the model loads the whole head, a range
/// starting it the whole token table, and a middle range neither. Llama 3.3
/// 70B: 506.8 MB a layer on average; a 5-layer tail weighs 2,594 MB of layers
/// and the 822 MB head, where 5 average layers are 2,534. A peer whose ceiling
/// held 7 average layers was planned layers 73-80 and refused them up front —
/// "needs about 4387 MB but this node's budget allows 4096 MB" (field report
/// #039). llama.cpp prices its output layer as a unit of its own, kept whole
/// on the last device (`common/fit.cpp`).
///
/// The scheduler keeps one per PEER (`NodeCandidate::range_weights`: none for
/// this node, whose loader prices its own ranges, nor for a peer whose weights
/// count as paid without saying which); auto-manage's chain planner one per
/// model (`coverage::near_chain`). Both build it from the header only.
#[derive(Debug, Clone)]
pub(crate) struct RangeWeights {
    /// The model's tensors by where the loader loads them.
    pub(crate) weights: Arc<ModelWeights>,
    pub(crate) num_layers: u32,
    /// The average layer its bounds count in (`weight_bytes_per_layer`).
    pub(crate) average_bytes: u64,
    /// What one layer costs those bounds: the average plus this prompt's KV.
    pub(crate) layer_price_bytes: u64,
    /// Its layers run on its card, which keeps the host-resident tensors in
    /// the machine's memory — as `average_bytes` leaves them out.
    pub(crate) on_card: bool,
}

impl RangeWeights {
    /// Layers of its bounds that running `range` costs beyond the average
    /// layers it adds: what loading it really adds
    /// ([`bytes_added_by`]) less `layers × average`, over the
    /// price of a layer — about a layer and a half for a 70B's tail, half one
    /// for its first range, a little below zero in its middle, nothing for
    /// the whole model.
    pub(crate) fn excess_layers(&self, range: (u32, u32), held: &[HeldRange]) -> f64 {
        if self.layer_price_bytes == 0 {
            return 0.0;
        }
        let adds = bytes_added_by(range, held, &self.weights, self.num_layers, self.on_card);
        let layers = layers_added_by(range, held);
        let averaged = u64::from(layers).saturating_mul(self.average_bytes);
        (adds as f64 - averaged as f64) / self.layer_price_bytes as f64
    }

    /// `range`'s width in layers of a TOTAL bound — one a count of every layer
    /// a machine is given is held to: the width plus what its weights cost
    /// beyond the average beside `held` ([`Self::excess_layers`]), rounded
    /// up. A warm peer's total counts each layer it has loaded as ONE, its
    /// tables already paid (`scheduler::PeerResidency::Layers`), so a range
    /// it holds costs its width; a ceiling, which is cold, passes `&[]`.
    /// Priced as if it held nothing, a tail a peer had loaded was charged its
    /// output head again: 9 of a total of 7 (pre-release sweep of v0.3.256).
    pub(crate) fn width_in_bound(&self, range: (u32, u32), held: &[HeldRange]) -> u32 {
        let width = range.1.saturating_sub(range.0);
        (f64::from(width) + self.excess_layers(range, held))
            .ceil()
            .max(0.0) as u32
    }

    /// A peer's word that `layers` REAL layers would load from `from`, as a
    /// TOTAL bound: what that run is charged beside `held` — its width and
    /// [`Self::excess_layers`], the charge a candidate refused this prompt
    /// is held to — rounded DOWN, so a range the bound admits weighs no more
    /// than the run that loaded (at the cost of the run's last layer where its
    /// charge is not whole). Read bare, 45 of a 70B's lighter middle layers
    /// admitted 47 heavier ones, 1,155 MB more than had loaded (2026-10-26,
    /// `daemon::state::PeerPromptFit`). None is none; a run past the model's
    /// end is cut at it.
    pub(crate) fn ceiling_of_a_fit(&self, from: u32, layers: u32, held: &[HeldRange]) -> u32 {
        let end = from.saturating_add(layers).min(self.num_layers);
        if end <= from {
            return 0;
        }
        let width = end - from;
        (f64::from(width) + self.excess_layers((from, end), held))
            .floor()
            .max(0.0) as u32
    }
}

/// One resident model-worker subprocess as the status surfaces report it.
///
/// Read through [`ModelProcessPool::worker_summaries`]; every field is a fact
/// the pool already keeps, so the report cannot disagree with the decisions
/// the pool makes from the same numbers.
#[derive(Debug, Clone, serde::Serialize)]
pub struct WorkerSummary {
    pub model: String,
    /// The subprocess id, when the child is still ours to name.
    pub pid: Option<u32>,
    /// `"graphics card"` or `"processor"`.
    pub device: &'static str,
    /// Why it runs on the processor, when it does (`CpuReason::as_str`).
    pub cpu_reason: Option<&'static str>,
    /// Requests this worker is computing right now.
    pub in_flight: usize,
    /// Seconds since a request was last registered against it.
    pub idle_secs: u64,
    /// Seconds since it was spawned.
    pub age_secs: u64,
    /// The reader actor saw its socket close: the process is gone or going.
    pub dead: bool,
    /// What admission priced the model at, in MB; 0 when unpriced.
    pub gpu_estimate_mb: u64,
    /// For a card/processor split, how many of `layers_total` are on the
    /// card — all of them when some keep their experts in RAM; `None` for a
    /// worker wholly on either device.
    pub gpu_layers_on_card: Option<u32>,
    /// Layers in the model this worker runs, known only for a split.
    pub layers_total: Option<u32>,
    /// Of those, how many keep their routed experts in the machine's memory
    /// (`CardSplit::ExpertsInRam`); `None` otherwise.
    pub expert_layers_in_ram: Option<u32>,
}

/// How many of a segment's layers go on the card when the whole segment does
/// not fit in `card` (the pool's room, and the load's reading where a worker
/// was asked — `hybrid::SplitCard`): `(on the card, in total)`, or `None` to
/// leave the model to the processor.
///
/// **Only for an architecture the loader will split.** It loads any other one
/// WHOLE on the card (`hybrid::arch_supports_hybrid`, with a warning), so a
/// split offered here put a model that does not fit onto the card anyway — a
/// failed load and a respawn on the processor at best. DeepSeek-2 and Qwen 3.5's
/// MoE variant are the ones today (review of #104, 2026-09-25; dense Qwen 3.5
/// joined the allowlist 2026-10-07, #228).
///
/// `layer_weights[i]` is layer `i` of the segment's own tensors
/// ([`LayerBytes::weights`]); the card holds every layer outside the
/// processor's run (`hybrid::processor_run`, `place` deciding where that run
/// sits), so each is charged what it weighs, never the segment's average
/// (#343).
fn split_for_card(
    inputs: &crate::model::auto_manage::vram::VramFootprintInputs,
    layer_weights: &[u64],
    card: crate::inference::split::hybrid::SplitCard,
    place: crate::inference::split::hybrid::RunPlace,
) -> Option<(usize, usize)> {
    let layers = inputs.segment_layers as usize;
    if !inputs.splits_across_devices || layers == 0 || layer_weights.len() != layers {
        return None;
    }
    // The ends' tables go to the card whichever layers do (#342), and so do
    // the small tensors no layer names (the output norm, `rope_freqs`): paid
    // first, and the layers placed in what is left, each by its own weights.
    let laid = layer_weights
        .iter()
        .fold(0u64, |sum, &bytes| sum.saturating_add(bytes));
    let up_front = inputs
        .card_weight_bytes()
        .saturating_sub(laid)
        .max(inputs.head_bytes);
    // The room is the loader's share of the card, never the budget less a
    // reserve alone — past its share the load refuses the card outright
    // (`hybrid::split_room_bytes`, field report v0.3.258).
    let n = crate::inference::split::hybrid::plan_gpu_layers(
        crate::inference::split::hybrid::split_room_bytes(card).saturating_sub(up_front),
        layer_weights,
        card_kv_bytes_of_split(inputs),
        place,
    );
    (n > 0).then_some((n, layers))
}

/// Each of a segment's layers' bytes, from the same read of the header as its
/// footprint ([`ModelProcessPool::segment_geometry`]).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub(crate) struct LayerBytes {
    /// Layer `i`'s own tensors (`split::segment_tensor` → `Layer`) — what
    /// placing it on the card costs in weights ([`split_for_card`]). Spread
    /// evenly where no tensor names a layer.
    pub weights: Vec<u64>,
    /// Of which its routed experts (`split::routed_expert_bytes`), all 0 for
    /// a dense model — what keeping experts in RAM is weighed by
    /// ([`experts_in_ram_for_card`]).
    pub experts: Vec<u64>,
    /// Where a split puts its processor run (`hybrid::run_place`, the
    /// loader's own reading of the header): a far segment's first layers
    /// (#461 (4)), a first segment's tail, or — the whole model, every layer
    /// keeping its own cache, so its card could guess without the run —
    /// early in the middle (`hybrid::processor_run`).
    pub run_place: crate::inference::split::hybrid::RunPlace,
}

/// `bytes` spread evenly over `layers` layers — a segment's weights where no
/// tensor says which layer it belongs to.
fn spread_over_layers(bytes: u64, layers: usize) -> Vec<u64> {
    if layers == 0 {
        return Vec::new();
    }
    vec![bytes / layers as u64; layers]
}

/// What a segment's caches take on the card at its full context, as a
/// card/processor split keeps them — the KV term both placements below charge,
/// so they promise a conversation the same room.
///
/// Priced as the loader prices its own budget (`kv_budget::KvPrice`, from the
/// same layout): only the layers that keep a cache (a recurrent layer holds a
/// fixed state; Qwen 3.5, #228), each by its own shape, kept the way the card
/// will keep it — the half cache, or f32 plus the flash mirror for a
/// grouped-query model where that does not apply — and a sliding-window layer
/// charged its window (#281), handed forwards as wide as such a split reads a
/// prompt (`PromptReader::CardCopyingWeights` at its widest). A split must
/// charge what the loader charges, or it leaves the card less room for a
/// conversation than the model serves: GLM-4-9B split 36/40 on an 8 GB card
/// covered ~5,300 of its 8,192 tokens (#104's follow-up).
fn card_kv_bytes_of_split(inputs: &crate::model::auto_manage::vram::VramFootprintInputs) -> u64 {
    use crate::inference::prefill_pacer::{PromptReader, COPIED_CHUNK_MAX_TOKENS};
    let context = inputs.effective_context as usize;
    inputs
        .kv
        .reading(
            PromptReader::CardCopyingWeights {
                room_tokens: COPIED_CHUNK_MAX_TOKENS,
            },
            context,
        )
        .bytes_for(context)
}

/// How much more free graphics memory a WHOLE card placement's load would
/// have to read for the model's weights to leave a `positions`-token cache
/// inside the loader's line (`kv_budget::weights_and_caches_room`); 0 when it
/// fits (#322). Charged exactly as [`split_for_card`] charges every layer on
/// the card — the ends' tables up front, each layer by its own weights
/// (`layer_weights`), the cache priced as a split's
/// (`card_kv_bytes_of_split`) at that context — so the whole placement and
/// the split placed in its stead are weighed by one arithmetic.
fn whole_placement_short_by_bytes(
    inputs: &crate::model::auto_manage::vram::VramFootprintInputs,
    layer_weights: &[u64],
    positions: u64,
    load_reads_free_bytes: u64,
    one_long_prompt: bool,
) -> u64 {
    use crate::inference::split::kv_budget::{weights_and_caches_room, VRAM_HEADROOM_PCT};
    let at_positions = crate::model::auto_manage::vram::VramFootprintInputs {
        effective_context: inputs.effective_context.min(positions),
        ..*inputs
    };
    let laid = layer_weights
        .iter()
        .fold(0u64, |sum, &bytes| sum.saturating_add(bytes));
    // A load fitted to the one prompt it was refused keeps that prompt's
    // forward buffers too, as its split would (`hybrid::split_room_bytes`).
    let forward = if one_long_prompt {
        crate::inference::split::hybrid::FORWARD_BUFFER_RESERVE_BYTES
    } else {
        0
    };
    let needs = inputs
        .card_weight_bytes()
        .max(laid.saturating_add(inputs.head_bytes))
        .saturating_add(card_kv_bytes_of_split(&at_positions))
        .saturating_add(forward);
    if needs <= weights_and_caches_room(load_reads_free_bytes) {
        return 0;
    }
    // The free memory whose line holds `needs`, less what the load read.
    needs
        .div_ceil(VRAM_HEADROOM_PCT)
        .saturating_mul(100)
        .saturating_sub(load_reads_free_bytes)
}

/// Where a segment that does not fit the card whole goes instead.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CardSplit {
    /// `on_card` of `total` layers on the card, a run of the rest on the
    /// processor (`--gpu-layers`) — which run, [`Self::processor_run`].
    Layers { on_card: usize, total: usize },
    /// Every layer on the card except the routed experts of its first
    /// `in_ram`, which stay in the machine's memory and run on the processor
    /// (`--cpu-moe-layers`, llama.cpp's `--n-cpu-moe`; FUTURE_WORK #138 (3)).
    ExpertsInRam { in_ram: usize, total: usize },
}

impl CardSplit {
    /// `(layers whose feed-forward runs on the card, layers in total)` — what
    /// "placed short of the card" reads and what the planner blends the two
    /// devices' speeds by (`scheduler::split_tokens_per_sec`). For experts in
    /// RAM that counts a layer whose experts stay there as the processor's,
    /// which prices it a little slow: the routed experts are nearly all of
    /// such a layer's reading, and its attention stays on the card (30B-A3B
    /// on an 8 GB card: 40 ms a step with 23 layers' experts in RAM, 49 ms
    /// with 22 whole layers on the processor, 2026-10-13).
    pub fn card_share(self) -> (usize, usize) {
        match self {
            Self::Layers { on_card, total } => (on_card, total),
            Self::ExpertsInRam { in_ram, total } => (total.saturating_sub(in_ram), total),
        }
    }

    /// The layers of `segment` (absolute) a whole-layer split puts on the
    /// processor: `hybrid::processor_run` of its count — the loader's own
    /// answer, given the same facts — or `None` for none / experts in RAM.
    /// `place`: where `segment`'s run sits ([`LayerBytes::run_place`]).
    fn processor_run(
        self,
        segment: (u32, u32),
        place: crate::inference::split::hybrid::RunPlace,
    ) -> Option<(u32, u32)> {
        let Self::Layers { on_card, .. } = self else {
            return None;
        };
        let len = segment.1.saturating_sub(segment.0) as usize;
        let run = crate::inference::split::hybrid::processor_run(len, on_card, place);
        let at = |offset: usize| {
            segment
                .0
                .saturating_add(u32::try_from(offset).unwrap_or(u32::MAX))
        };
        (!run.is_empty()).then(|| (at(run.start), at(run.end)))
    }

    /// Layers wholly or partly on the processor, so ever short of the card.
    fn is_short_of_the_card(self) -> bool {
        let (on_card, total) = self.card_share();
        on_card < total
    }

    /// What a live worker is told for a range split this way
    /// (`DaemonMsg::PlaceRange`, #265) — the per-range form of what
    /// `worker_placement_args` puts on a spawn's command line.
    fn placement(self) -> crate::inference::split::RangePlacement {
        use crate::inference::split::RangePlacement;
        match self {
            Self::Layers { on_card, .. } => RangePlacement {
                gpu_layers: Some(on_card),
                cpu_expert_layers: None,
            },
            Self::ExpertsInRam { in_ram, .. } => RangePlacement {
                gpu_layers: None,
                cpu_expert_layers: Some(in_ram),
            },
        }
    }
}

/// The fewest of a segment's first layers whose routed experts must stay in
/// the machine's memory for everything else of every layer — attention, the
/// router, shared experts, the whole KV cache — to fit `card`; `None` when the segment has no routed experts, or when even all of
/// them in RAM leave the rest too large.
///
/// **What llama.cpp's own fitting does** (`--fit`, `llama_params_fit_impl`):
/// it puts "only dense weights in device memory" first, then lets routed
/// experts overflow to system memory, layer by layer ("48 layers (34
/// overflowing)"). Measured here on Qwen3-30B-A3B Q2_K and an 8 GB card
/// (2026-10-13): 40 ms a decode step with 23 layers' experts in RAM against
/// 49-68 ms for 26 whole layers on the card, prompts alike — a token reads 8
/// of 128 experts, so the processor's share is small, while a whole layer
/// there also runs attention over the conversation.
///
/// Charged by the same terms as [`split_for_card`] — the KV cache at the
/// model's full context, in the card room the load takes
/// (`hybrid::split_room_bytes`: the loader's share, never more than the budget
/// less a forward's transient buffers) — so the two placements promise a
/// conversation the same room.
/// `expert_bytes[i]` is layer `i` of the segment's routed-expert bytes
/// (`split::routed_expert_bytes`), exact per layer: a quantization mix gives
/// some layers' experts more bits than others.
fn experts_in_ram_for_card(
    inputs: &crate::model::auto_manage::vram::VramFootprintInputs,
    expert_bytes: &[u64],
    card: crate::inference::split::hybrid::SplitCard,
) -> Option<usize> {
    if !inputs.splits_across_devices
        || expert_bytes.len() != inputs.segment_layers as usize
        || expert_bytes.iter().all(|&b| b == 0)
    {
        return None;
    }
    let kv = card_kv_bytes_of_split(inputs);
    let usable = crate::inference::split::hybrid::split_room_bytes(card);
    let mut on_card = inputs.card_weight_bytes().saturating_add(kv);
    // At least one: this is asked only of a segment admission found too large
    // for the card whole.
    for (layer, &bytes) in expert_bytes.iter().enumerate() {
        on_card = on_card.saturating_sub(bytes);
        if on_card <= usable {
            return Some(layer + 1);
        }
    }
    None
}

/// How a segment too large for `card` is placed: every layer on the card
/// with the fewest layers' experts in RAM where it has routed experts and the
/// rest fits ([`experts_in_ram_for_card`]), otherwise its first layers on the
/// card and the rest on the processor ([`split_for_card`]); `None` leaves it
/// to the processor.
fn card_split(
    inputs: &crate::model::auto_manage::vram::VramFootprintInputs,
    layers: &LayerBytes,
    card: crate::inference::split::hybrid::SplitCard,
) -> Option<CardSplit> {
    let total = inputs.segment_layers as usize;
    if let Some(in_ram) = experts_in_ram_for_card(inputs, &layers.experts, card) {
        return Some(CardSplit::ExpertsInRam { in_ram, total });
    }
    split_for_card(inputs, &layers.weights, card, layers.run_place)
        .map(|(on_card, total)| CardSplit::Layers { on_card, total })
}

/// Whether a spawn's placement is a WHOLE card placement, to be weighed again
/// by the free memory its load reads (`fit_whole_placement_to_the_load`,
/// #322): admission weighed it against the pool's room, which cannot see the
/// loader's line. Never a guest — it takes only memory that stands free, never
/// a split — nor a placement charged to the machine, which has no card.
/// A/B inside one binary: `SWARMLLM_WHOLE_READS_CARD=0` loads it whole as
/// admitted, as v0.3.270 did.
fn whole_placement_reads_the_card(
    card_split: Option<CardSplit>,
    going_to_cpu: bool,
    charge_ram: bool,
    guest: bool,
) -> bool {
    card_split.is_none()
        && !going_to_cpu
        && !charge_ram
        && !guest
        && std::env::var("SWARMLLM_WHOLE_READS_CARD").as_deref() != Ok("0")
}

/// [`card_split`] in `room_mb` of the card and, for a spawn, the free memory
/// its load reads (`SplitCard::read_by_the_load`; a plan has only the room) —
/// the sizing every split admitted short of the card shares with a whole
/// placement the load would leave too little (#322). `one_long_prompt`: the
/// placement is fitted to one prompt a worker refused, and keeps its forward's
/// buffers off the load's line (`SplitCard::for_one_long_prompt`, #454).
fn split_in_room(
    inputs: &crate::model::auto_manage::vram::VramFootprintInputs,
    mut layers: LayerBytes,
    room_mb: u64,
    load_reads_free_bytes: Option<u64>,
    one_long_prompt: bool,
) -> Option<CardSplit> {
    use crate::inference::split::hybrid::SplitCard;
    // A/B inside one binary: `0` places a mixture-of-experts model by whole
    // layers, as before #138 (3).
    if std::env::var("SWARMLLM_EXPERTS_IN_RAM").as_deref() == Ok("0") {
        layers.experts.clear();
    }
    let room = room_mb.saturating_mul(1024 * 1024);
    let card = match load_reads_free_bytes {
        Some(free) => SplitCard::read_by_the_load(room, free),
        None => SplitCard::room(room),
    };
    let card = if one_long_prompt {
        card.for_one_long_prompt()
    } else {
        card
    };
    card_split(inputs, &layers, card)
}

/// What a range grown onto a live card worker as `split` costs each device
/// (#265), at the per-layer rates growth charges (`segment_cost_curve`, with
/// no fixed term — the worker paid that once): the card its card-held layers,
/// less any experts kept in RAM, never more than `room_mb` (as a spawn's
/// share is capped, `card_share_of_split_mb`); the machine its processor-held
/// layers, or those experts (`experts_in_ram_mb`, the loader's own count).
fn split_growth_cost(
    split: CardSplit,
    segment: (u32, u32),
    card_per_layer_mb: u64,
    host_per_layer_mb: u64,
    experts_in_ram_mb: impl FnOnce(usize) -> u64,
    room_mb: u64,
) -> RangeCost {
    let layers = u64::from(segment.1.saturating_sub(segment.0));
    let (card_mb, host_mb) = match split {
        CardSplit::Layers { on_card, .. } => {
            let on_card = u64::try_from(on_card).unwrap_or(u64::MAX).min(layers);
            (
                card_per_layer_mb.saturating_mul(on_card),
                host_per_layer_mb.saturating_mul(layers - on_card),
            )
        }
        CardSplit::ExpertsInRam { in_ram, .. } => {
            let experts = experts_in_ram_mb(in_ram);
            (
                card_per_layer_mb
                    .saturating_mul(layers)
                    .saturating_sub(experts),
                experts,
            )
        }
    };
    RangeCost {
        mb: card_mb.min(room_mb),
        host_mb,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CpuReason {
    /// `inference.gpu_layers = 0` — the user asked for CPU.
    Configured,
    /// This build's CUDA kernels need a newer card than the one present.
    GpuTooOld,
    /// The graphics stack stopped working while this node was running — almost
    /// always a driver update underneath us. Distinct from [`Self::GpuTooOld`]
    /// because the card is fine and the remedy is a restart, and distinct from
    /// [`Self::NotEnoughVram`] because waiting will never clear it.
    GpuUnavailable,
    /// The model's estimated footprint exceeds the free VRAM budget. Unlike the
    /// others this clears itself once memory frees up.
    NotEnoughVram,
    /// The graphics driver is not answering — an `nvidia-smi` is still blocked
    /// in it past its bound, which is what a card reset (a TDR) looks like from
    /// here (`vram::graphics_driver_not_answering`). A worker started on the
    /// card now would block in its context creation for as long as the reset
    /// takes — 14 minutes once (FUTURE_WORK #220). Clears itself when the
    /// driver answers, and the model then returns to the card through the
    /// ordinary promotion (`reason_still_holds`). Distinct from
    /// [`Self::GpuUnavailable`], whose advice is a restart a reset does not need.
    DriverNotAnswering,
    /// NVIDIA's CUDA libraries that this build opens are not installed
    /// (`gpu_support::missing_cuda_libraries`, #253). Distinct from
    /// [`Self::GpuTooOld`]: the card is fine, and the remedy is an install and
    /// a restart, not a newer card.
    CudaLibrariesMissing,
    /// The model holds weights in a format this build's card kernels cannot
    /// read — IQ4_NL or IQ4_XS (#404), read on the processor only. On a card
    /// each such product would dequantize its weight in host memory and send
    /// it back, every token: seconds a token. Kept off the card until a card
    /// kernel reads it, by [`ModelProcessPool::cpu_reason`], so the planner and
    /// the spawn agree — as MXFP4 was until its card kernels landed (#390 step
    /// 7). Distinct from [`Self::GpuTooOld`]: the card is fine, and other
    /// models still use it.
    WeightFormatNeedsTheProcessor,
}

impl CpuReason {
    /// Every reason, so whatever puts a reason into words can be checked
    /// against all of them.
    pub const ALL: [CpuReason; 7] = [
        CpuReason::Configured,
        CpuReason::GpuTooOld,
        CpuReason::GpuUnavailable,
        CpuReason::NotEnoughVram,
        CpuReason::DriverNotAnswering,
        CpuReason::CudaLibrariesMissing,
        CpuReason::WeightFormatNeedsTheProcessor,
    ];

    /// Stable machine-readable tag. Used in logs and in the admin API, so keep
    /// these values stable — something will grep for them.
    pub fn as_str(self) -> &'static str {
        match self {
            CpuReason::Configured => "configured_cpu_only",
            CpuReason::GpuTooOld => "gpu_too_old_for_this_build",
            CpuReason::GpuUnavailable => "gpu_stopped_responding",
            CpuReason::NotEnoughVram => "not_enough_vram",
            CpuReason::DriverNotAnswering => "driver_not_answering",
            CpuReason::CudaLibrariesMissing => "cuda_libraries_missing",
            CpuReason::WeightFormatNeedsTheProcessor => "weight_format_needs_the_processor",
        }
    }

    /// The same reason as this node states it to its peers
    /// (`ResidentModelLayers::on_processor_because`, #498) — the wire word is
    /// [`Self::as_str`]'s (`every_processor_reason_reaches_peers_in_its_own_words`).
    pub fn for_peers(self) -> swarmllm_types::OnProcessorBecause {
        use swarmllm_types::OnProcessorBecause as Wire;
        match self {
            CpuReason::Configured => Wire::ConfiguredCpuOnly,
            CpuReason::GpuTooOld => Wire::GpuTooOldForThisBuild,
            CpuReason::GpuUnavailable => Wire::GpuStoppedResponding,
            CpuReason::NotEnoughVram => Wire::NotEnoughVram,
            CpuReason::DriverNotAnswering => Wire::DriverNotAnswering,
            CpuReason::CudaLibrariesMissing => Wire::CudaLibrariesMissing,
            CpuReason::WeightFormatNeedsTheProcessor => Wire::WeightFormatNeedsTheProcessor,
        }
    }
}

/// Models whose workers this node keeps on the processor whatever the card has
/// room for: `SWARMLLM_PROCESSOR_MODELS=a,b`, read once. A rig's switch, the
/// shape of llama.cpp's `--gpu-layers-draft 0` — a split's drafter on the
/// processor beside a head on the card, so the card serves ONE process (two
/// sharing it tracked the FECS bursts, gotcha #755). [`ModelProcessPool::cpu_reason`]
/// asks it, so the planner's prediction and the spawn agree.
fn kept_on_the_processor(model_id: &ModelId) -> bool {
    static KEPT: std::sync::OnceLock<std::collections::HashSet<String>> =
        std::sync::OnceLock::new();
    KEPT.get_or_init(|| {
        models_named(&std::env::var("SWARMLLM_PROCESSOR_MODELS").unwrap_or_default())
    })
    .contains(&model_id.0)
}

/// The model ids in a comma-separated list, blanks dropped.
fn models_named(list: &str) -> std::collections::HashSet<String> {
    list.split(',')
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .map(str::to_owned)
        .collect()
}

/// Where a guest's spawn would put it, if anywhere
/// ([`ModelProcessPool::guest_fit`], [`ModelProcessPool::guest_fit_beside`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum GuestFit {
    /// It would not be given a worker.
    Refused,
    /// On the graphics card.
    OnCard,
    /// In system memory: every guess reads its weights through the processor.
    InSystemMemory,
}

impl GuestFit {
    pub(crate) fn admitted(self) -> bool {
        self != Self::Refused
    }
}

/// Whether loading a model may take memory from other models, and how long a
/// conversation its cache is charged for — a REQUIRED argument of
/// `ModelProcessPool::get_or_spawn`, so no load can leave either out.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Tenancy {
    /// Asked for by a request FOR this model: reclaims idle models' memory
    /// rather than run on the processor, may go part card, part processor, and
    /// returns to the card once it fits.
    Tenant,
    /// Serves another model's request — the split drafter
    /// (`ModelProcessPool::draft`). It takes only memory that is free as it
    /// stands: no reclaim, no card/processor split, no promotion, no growth,
    /// and no dashboard notice. Loaded as a tenant it evicted the very model it
    /// was guessing for — idle between turns after `VRAM_MAKE_ROOM_MIN_IDLE_SECS`
    /// — whose next prompt pass then reloaded it beside the drafter, on the
    /// processor if the card was full, and the two could swap on every turn.
    /// vLLM hit the static form of this (the draft model's weights missing from
    /// its memory profiler, vllm-project/vllm#14067) and plans the two
    /// together; a swarm node loads models on demand, so the drafter is made
    /// subordinate instead (2026-09-28).
    ///
    /// `conversation` is the positions of the reply it is loaded to guess for
    /// (`model_worker::drafter_cache_positions`): its load is charged that
    /// cache, not a typical conversation's (#275, `vram::KvCharge`).
    ///
    /// `leaves_mb` is the card memory it must leave standing for the model it
    /// guesses for — that model's conversation room on the card
    /// ([`ModelProcessPool::room_a_guest_leaves_mb`]), weighed beside the
    /// guest's own figure and charged to nobody: the room is the target's.
    Guest { conversation: u64, leaves_mb: u64 },
}

impl Tenancy {
    fn is_guest(self) -> bool {
        matches!(self, Tenancy::Guest { .. })
    }

    /// How long a conversation this load's cache is charged for.
    fn kv_charge(self) -> KvCharge {
        match self {
            Tenancy::Tenant => KvCharge::Typical,
            Tenancy::Guest { conversation, .. } => KvCharge::Conversation(conversation),
        }
    }
}

/// How long a prompt refused for want of room keeps a model's later loads
/// sized for one as long (#454): a conversation that sent one is likely to
/// send the next, longer still — an agent's grows with every tool result.
const LONG_PROMPT_REMEMBERED_FOR: std::time::Duration = std::time::Duration::from_secs(30 * 60);

/// The positions a load keeps room for after a prompt of `positions` was
/// refused: the next multiple of a typical conversation
/// ([`crate::model::auto_manage::vram::ADMISSION_KV_CONTEXT`]), so the turns
/// after it, a little longer each, fit the same placement instead of each
/// asking for a reload.
fn long_prompt_room(positions: u64) -> u64 {
    let step = crate::model::auto_manage::vram::ADMISSION_KV_CONTEXT;
    positions.div_ceil(step).saturating_mul(step)
}

/// `SWARMLLM_LONG_PROMPT_RELOAD=0` keeps every load fitted to a typical
/// conversation and refuses a longer prompt as before #454 — for an A/B inside
/// one binary. Read once.
fn long_prompt_reload_on() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var("SWARMLLM_LONG_PROMPT_RELOAD").as_deref() != Ok("0"))
}

/// The prompts each model was refused lately for want of room on a whole
/// card placement fitted to a shorter conversation (#454), in positions
/// ([`long_prompt_room`]), each kept [`LONG_PROMPT_REMEMBERED_FOR`] from the
/// last. Written ONLY by [`ModelProcessPool::make_room_for_a_longer_prompt`],
/// read ONLY by the spawn's fitting of a whole placement
/// ([`ModelProcessPool::whole_placement_kv`]).
#[derive(Default)]
struct LongPrompts(DashMap<ModelId, (u64, std::time::Instant)>);

impl LongPrompts {
    /// The room `model`'s loads keep now, if a refusal asked for more than a
    /// typical conversation within the window.
    fn room_for(&self, model: &ModelId, now: std::time::Instant) -> Option<u64> {
        let (room, at) = *self.0.get(model)?;
        (now.saturating_duration_since(at) < LONG_PROMPT_REMEMBERED_FOR).then_some(room)
    }

    /// A prompt asked for `room`: the longest asked within the window is kept,
    /// its clock started again.
    fn note(&self, model: &ModelId, room: u64, now: std::time::Instant) {
        let kept = self.room_for(model, now).unwrap_or(0).max(room);
        self.0.insert(model.clone(), (kept, now));
    }
}

/// How long the ranges a plan gives this node are kept for its spawns
/// ([`PlannedHere`]): the up-front admission runs just before the first
/// segment's forward, whose spawn follows within a second; a minute covers a
/// spawn behind a retiring worker's card memory coming back (#3 (j13), 5 s).
const PLANNED_HERE_FOR: std::time::Duration = std::time::Duration::from_secs(60);

/// Every range the latest plan gives this node, per model, while it has two
/// or more (#481 (5)) — so the first range's spawn leaves the card room the
/// others will be grown into. Written ONLY by [`ModelProcessPool::admit_prompt`]
/// (the up-front admission, which every plan with a peer in it asks before its
/// first forward), read ONLY by [`ModelProcessPool::room_for_the_plans_other_ranges`].
///
/// Measured on this node's 8 GB card, 2026-11-19 (`~/swarmllm-gate/split27_1119n`,
/// main at 79d5f182e, Qwen3.8-27B planned `[0..21)` + `[63..64)` here, `[21..63)`
/// in Australia): the first range's spawn split 17 of 21 layers onto the card,
/// its load read more free memory and refitted it to 20 (#365), filling the
/// budget; the last layer's growth then asked for 261 MB the card no longer had,
/// and 5 of 6 requests failed with "1 layers 63..64 … need about 261 MB more" —
/// the plan only ever fitted with the room for that layer left.
#[derive(Default)]
struct PlannedHere(DashMap<ModelId, (Vec<(u32, u32)>, std::time::Instant)>);

impl PlannedHere {
    fn note(&self, model: &ModelId, ranges: &[(u32, u32)], now: std::time::Instant) {
        if ranges.len() < 2 {
            self.0.remove(model);
        } else {
            self.0.insert(model.clone(), (ranges.to_vec(), now));
        }
    }

    /// The plan's ranges here that a spawn of `segment` does not load, if the
    /// plan is recent and `segment` is one of its ranges.
    fn beside(
        &self,
        model: &ModelId,
        segment: (u32, u32),
        now: std::time::Instant,
    ) -> Vec<(u32, u32)> {
        let Some(entry) = self.0.get(model) else {
            return Vec::new();
        };
        let (ranges, at) = &*entry;
        if now.saturating_duration_since(*at) >= PLANNED_HERE_FOR || !ranges.contains(&segment) {
            return Vec::new();
        }
        ranges
            .iter()
            .copied()
            .filter(|&r| !(segment.0 <= r.0 && r.1 <= segment.1))
            .collect()
    }
}

/// Whose memory cap a drafter's load is weighed against
/// ([`ModelProcessPool::draft`], [`ModelProcessPool::guest_fit`],
/// the planner's room beside it): that of the request it guesses for. A
/// drafter guessing for the owner's reply is part of serving the owner's
/// request, and the contribution level caps the swarm's work, not the owner's
/// (#266). It stays a guest either way: it takes only memory that stands free,
/// reclaims nothing, and the machine's live headroom binds it.
///
/// It was the swarm's for every request until 2026-10-26 (#351): on the live
/// node (16 GB, contribution minimal, swarm cap 4997 MB) the owner's
/// Llama-3.3-70B held 9470 MB of system memory, more than the swarm's whole
/// cap, so no drafter could load beside it. Llama-3.2-3B was refused at its
/// spawn, the 1B was never admitted, and every reply ran unguessed (0.56-0.59
/// tok/s), while the owner's 12792 MB cap had room for either.
/// `SWARMLLM_DRAFTER_CAP=swarm` weighs every drafter as the swarm's, the
/// behaviour before, for an A/B inside one binary. Read once.
fn drafter_requester(requester: Requester) -> Requester {
    static SWARM_ALWAYS: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    let swarm_always = *SWARM_ALWAYS
        .get_or_init(|| std::env::var("SWARMLLM_DRAFTER_CAP").is_ok_and(|v| v.trim() == "swarm"));
    if swarm_always {
        Requester::Swarm
    } else {
        requester
    }
}

/// What an admission's arithmetic says of one estimate, before anything is
/// charged ([`ModelProcessPool::card_verdict`], [`ModelProcessPool::ram_verdict`]).
#[derive(Debug, Clone, Copy)]
enum Verdict<B> {
    /// No budget to weigh against, or nothing to weigh: admitted unjudged.
    Unjudged,
    Fits {
        budget: B,
        committed: u64,
    },
    Refused {
        budget: B,
        committed: u64,
    },
}

/// Whose request a [`ModelProcessPool::generate`] — or a forward of a segment
/// of it, [`ModelProcessPool::forward_for_request`] — serves, which decides
/// how many cores may read its prompt (`cpu_pools::in_phase_pool`).
///
/// The contribution level is how much of the computer SwarmLLM may use to
/// answer requests FROM THE SWARM; it had been capping the owner's own
/// prompts to half the cores as well (FUTURE_WORK #119).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Requester {
    /// This machine's owner: a request made to this node's own API, whether it
    /// ran straight to the worker or through the router and came back here.
    Owner,
    /// A peer's request this node serves for the swarm.
    Swarm,
}

/// A request's forwards keep the hidden states at its chain's far run while
/// this lives ([`ModelProcessPool::learn_far_run`]); dropped, they stop.
pub struct FarRunLearning {
    pool: Arc<ModelProcessPool>,
    request_id: Uuid,
}

impl Drop for FarRunLearning {
    fn drop(&mut self) {
        self.pool.far_runs.remove(&self.request_id);
    }
}

pub struct ModelProcessPool {
    workers: DashMap<ModelId, Arc<WorkerHandle>>,
    /// Serializes worker spawning to prevent TOCTOU races where two concurrent
    /// callers both miss the DashMap lookup and each spawn a subprocess.
    spawn_lock: Mutex<()>,
    /// Crash-loop backoff: per-model `(last_failure_at, consecutive_failures)`.
    /// A spawn that fails (or crashes immediately) bumps the counter; further
    /// `get_or_spawn` calls within the cooldown window short-circuit with
    /// `ModelNotAvailable` instead of repeatedly burning the 30 s
    /// `WORKER_CONNECT_TIMEOUT_SECS` on every arriving request. First
    /// successful spawn clears the entry.
    spawn_failures: DashMap<ModelId, (std::time::Instant, u32)>,
    /// Layers this node's loader refused to ADD for a request — the fewest, when
    /// it refused more than once — kept until the router takes them into its
    /// record of the refusal (`take_layers_refused`). See
    /// [`Self::note_load_refusal`].
    layers_refused: DashMap<Uuid, (u32, std::time::Instant)>,
    /// Layers of a request this node's conversation memory held at its
    /// prompt's length, when the up-front admission refused it — kept like
    /// `layers_refused` until the router takes them (`take_layers_fitting`).
    layers_fitting: DashMap<Uuid, (u32, std::time::Instant)>,
    /// Prompts each model was refused lately for want of room on a whole card
    /// placement fitted to a shorter conversation, so its next loads keep room
    /// for one as long (#454).
    long_prompts: LongPrompts,
    /// The ranges the latest plan gives this node (#481 (5), [`PlannedHere`]).
    planned_here: PlannedHere,
    data_dir: PathBuf,
    /// Each model's header, parsed once while its file is unchanged — read
    /// ONLY by `segment_geometry`, which every footprint estimate goes through
    /// (a 70B plan parsed its 7.8 MB header 73 times, #360).
    header_cache: crate::inference::split::HeaderCache,
    /// Active shard windows: which shards each model worker should load.
    /// If absent, the worker loads all on-disk shards (default behavior).
    active_shard_windows: DashMap<ModelId, Vec<u32>>,
    /// Device placement passed to future-spawned workers, mirroring
    /// `InferenceConfig::gpu_layers`: `-1` auto, `0` CPU only, `>0` GPU.
    gpu_layers: std::sync::atomic::AtomicI32,
    // (see `CpuReason` for why the three CPU causes are kept distinct)
    /// Models forced onto the CPU because a worker died of a GPU OOM while
    /// serving them. Without this, the respawned worker makes the identical
    /// allocation and dies the same way, and the user sees an unbroken run of
    /// 500s with no path out.
    ///
    /// **The pin is NOT for the life of the daemon**, and this doc used to say
    /// it was. `unload_model` clears every pin whenever unloading actually
    /// freed graphics memory, because the condition that caused the OOM has
    /// then changed — see the `freed_gpu_memory` branch there, and
    /// `worker_should_return_to_gpu` for the resident-worker half. Reasoning
    /// about this field as permanent is how a model that could move back to
    /// the card gets left on the processor (gotcha #401). Nor does it wait for
    /// another model to unload: a memory pin ENDS after its hold, and the card
    /// is weighed again as it stands ([`CpuPins`], field report 2026-10-31 —
    /// the model that ran out was the card's only tenant).
    cpu_pins: CpuPins,
    /// GPU memory budget in MB, 0 = unset (no admission control).
    ///
    /// The LAST reading of the effective `resources` budget — re-read at every
    /// admission through [`Self::vram_budget_source`] where one is set, so this
    /// is what a failed reading (or a test with no source) falls back to.
    vram_budget_mb: std::sync::atomic::AtomicU64,
    /// Where the card budget comes from NOW: `auto_manage::compute_vram_budget`,
    /// set by `SharedState::new` — `nvidia-smi` minus what this node's own
    /// workers are charged, so another program's use of the card counts at
    /// the moment a model is admitted, not as it stood when the node started.
    /// See [`Self::vram_budget_now`]. Replaceable, so a test that builds a
    /// `SharedState` can name the card it means rather than read the machine's.
    vram_budget_source: std::sync::RwLock<Option<VramBudgetSource>>,
    /// The most that budget could be with no other program on the card —
    /// `auto_manage::vram_budget_ceiling`, read from the live config without
    /// asking the card. Unset (tests, a node with no card) is no ceiling.
    vram_ceiling_source: std::sync::OnceLock<Box<dyn Fn() -> Option<u64> + Send + Sync>>,
    /// When [`Self::vram_budget_now`] last read the card live — so a plan,
    /// which asks a dozen times, pays one `nvidia-smi`
    /// ([`Self::card_budget_for_planning`]).
    card_read_at: std::sync::Mutex<Option<std::time::Instant>>,
    /// CPU threads each worker's rayon pool may use. 0 until set at startup,
    /// which the spawn path reads as "not configured" and leaves alone.
    cpu_threads: std::sync::atomic::AtomicUsize,
    /// See [`Self::set_owner_prefill_threads`]. 0 = no wider owner pool.
    owner_prefill_threads: std::sync::atomic::AtomicUsize,
    /// The pace every worker should run at (`inference::pace`, #440 step 4):
    /// a spawn starts its worker at it, [`Self::pace_steps`] sets it.
    pace_permille: std::sync::atomic::AtomicU32,
    /// Rung where a reply's slot opens or closes on any worker (each worker
    /// holds a clone); awaited ONLY by the daemon's card fan-out
    /// (`daemon::background::spawn_card_busy_fan_out` →
    /// [`Self::tell_cards_who_is_busy`], #489).
    card_work_changed: Arc<tokio::sync::Notify>,
    /// GPU memory charged to each live worker, in MB.
    ///
    /// Admission needs to know what is already committed, and it cannot ask the
    /// device: `nvidia-smi` reports the whole machine (so it counts other
    /// programs, and on WSL per-process figures are unavailable), and a worker
    /// that has been admitted but has not finished loading has allocated
    /// nothing yet while still owing its footprint. Charging at admission and
    /// crediting on unload is the only view that is correct at the moment the
    /// decision is made.
    vram_reserved_mb: dashmap::DashMap<ModelId, u64>,
    /// System RAM budget in MB, 0 = unset (no admission control).
    ///
    /// The CPU-side sibling of `vram_budget_mb`, and it matters most exactly
    /// where that one gives up: refusing a model the GPU cannot hold loads it
    /// on the CPU instead, so the busier the GPU admission control is, the more
    /// weight lands in system RAM. With no ceiling there, the fallback that
    /// keeps a node answering is also what drives a small machine into swap.
    ram_budget_mb: std::sync::atomic::AtomicU64,
    /// How `ram_budget_mb` was arrived at, in one sentence, for the refusal
    /// message — the number alone surprised a user whose `max_ram_mb` was
    /// larger (external report, 2026-08-21).
    ram_budget_note: std::sync::Mutex<String>,
    /// System RAM charged to each live CPU worker, in MB. Same
    /// charge-at-admission / credit-on-unload discipline as
    /// `vram_reserved_mb`, and for the same reason: a worker owes its
    /// footprint from the moment it is admitted, long before it has loaded
    /// anything to measure.
    ram_reserved_mb: dashmap::DashMap<ModelId, u64>,
    /// Live RAM budget source, installed once by the daemon
    /// (`set_ram_budget_provider`): returns the cap from the CURRENT config and
    /// the anti-swap headroom from memory free NOW. Without one (tests), the
    /// stored `ram_budget_mb` cap is used alone.
    #[allow(clippy::type_complexity)]
    ram_budget_provider: std::sync::OnceLock<
        Box<dyn Fn() -> Option<crate::model::auto_manage::vram::RamBudget> + Send + Sync>,
    >,
    /// Whether this node detected a GPU at startup (`SharedState::gpu_info`).
    /// Defaults to `true` so nothing changes for a pool nobody told; the daemon
    /// sets it once. See `charges_ram`. A TEST's pool starts with none: every
    /// reader also asks whether the build drives a card, so the default build's
    /// tests never saw one, and a CUDA build's tests took this machine's real
    /// card instead — nine of them failed there and pass with this ("room is
    /// left", 2026-11-25). A test of a card says so (`test_card_in_play`,
    /// `set_gpu_detected`).
    gpu_detected: std::sync::atomic::AtomicBool,
    /// KV budget handed to each CPU worker at spawn (`--kv-budget-bytes`):
    /// the model's typical-context KV charge plus the RAM budget still
    /// uncommitted at admission. Set by `record_cpu_kv_budget`, cleared with
    /// the reservation.
    cpu_kv_budget_bytes: dashmap::DashMap<ModelId, u64>,
    /// Activity event sender for dashboard notifications.
    activity_tx:
        std::sync::OnceLock<tokio::sync::broadcast::Sender<crate::daemon::state::ActivityEvent>>,
    /// KV-cache session TTL passed to worker subprocesses (from config).
    kv_cache_ttl_secs: std::sync::atomic::AtomicU64,
    /// Prefix-cache config snapshot applied to future-spawned workers.
    /// Reading/writing is Relaxed — workers are spawned rarely enough that
    /// we don't care about cross-thread immediacy.
    prefix_cache_enabled: std::sync::atomic::AtomicBool,
    prefix_cache_max_entries: std::sync::atomic::AtomicU32,
    prefix_cache_max_prompt_tokens: std::sync::atomic::AtomicU32,
    prefix_cache_max_mb: std::sync::atomic::AtomicU32,
    prefix_cache_block_tokens: std::sync::atomic::AtomicU32,
    prefix_cache_min_tokens: std::sync::atomic::AtomicU32,
    /// SWIFT (arxiv 2410.06916) self-speculative decoding settings applied
    /// to future-spawned workers.
    swift_self_speculative: std::sync::atomic::AtomicBool,
    swift_calibration_tokens: std::sync::atomic::AtomicU32,
    swift_gamma: std::sync::atomic::AtomicU32,
    /// Stored as parts-per-thousand to fit into AtomicU32 (e.g. 0.45 → 450).
    swift_skip_ratio_milli: std::sync::atomic::AtomicU32,
    /// Force `standard_attention` everywhere (baseline + speculative paths).
    /// Required for SWIFT correctness; optional for benchmarking baselines.
    force_standard_attn: std::sync::atomic::AtomicBool,
    /// 0 means use the GGUF context_length verbatim. >0 caps it for KV-cache
    /// pre-allocation, so 128K-context models fit on small VRAM.
    max_seq_len_override: std::sync::atomic::AtomicU32,
    /// Quantize intermediate-segment hidden state activations to Q8_0 before
    /// returning them to the daemon (which forwards to the next pipeline peer).
    /// Receivers auto-dispatch on the dtype tag. See Item 13 in
    /// `docs/plans/archive/distributed_inference_speedup.md`.
    activation_compression: std::sync::atomic::AtomicBool,
    /// Continuous batching: when on, `forward()` routes through an
    /// auto-coalescing scheduler that collects concurrent arrivals into a
    /// time-windowed batch and dispatches via `forward_batch` (one
    /// `DaemonMsg::BatchForward` IPC message, one fused `SplitModel::forward_batch`
    /// call on GPU, falls through to sequential on CPU). Off → `forward()`
    /// bypasses the scheduler and sends a single `DaemonMsg::Forward`.
    continuous_batching: std::sync::atomic::AtomicBool,
    /// Time-window in milliseconds for the scheduler to wait for additional
    /// arrivals after the first request lands in an empty batch. Matches
    /// `InferenceConfig::batch_collection_ms`.
    batch_collection_ms: std::sync::atomic::AtomicU64,
    /// Maximum batch size. Matches `InferenceConfig::max_concurrent_decode_batch`.
    max_concurrent_decode_batch: std::sync::atomic::AtomicU32,
    /// Item 7 Phase 2: Sarathi prefill chunk size (in prompt tokens). Passed
    /// into spawned workers as `--prefill-chunk-tokens`. Matches
    /// `InferenceConfig::prefill_chunk_tokens`.
    prefill_chunk_tokens: std::sync::atomic::AtomicU32,
    /// Runtime mirror of `InferenceConfig::prefill_target_ms`.
    prefill_target_ms: std::sync::atomic::AtomicU64,
    /// Longest n-gram the local draft-free speculator will try to match.
    /// Matches `InferenceConfig::ngram_max_size`.
    ngram_max_size: std::sync::atomic::AtomicU32,
    /// How many tokens a local speculative round drafts. **Zero means the
    /// speculator is off**, which is how `InferenceConfig::ngram_lookup_enabled`
    /// reaches the worker — one value carries both the switch and the width, so
    /// a worker cannot be spawned with them disagreeing.
    ngram_pred_tokens: std::sync::atomic::AtomicU32,
    /// Item 7 Phase 4: fuse concurrent same-shape Prefilling slots into one
    /// `forward_batch` call. Passed into spawned workers as
    /// `--batched-prefill-forward`. Matches
    /// `InferenceConfig::batched_prefill_forward`. When false, Phase A always
    /// runs singleton forwards (useful for A/B benchmarks).
    batched_prefill_forward: std::sync::atomic::AtomicBool,
    /// Global batch scheduler. Created once by `start_batch_scheduler` from
    /// daemon setup (where `Arc<Self>` is available). When unset, `forward()`
    /// bypasses batching entirely regardless of the `continuous_batching` flag.
    batch_scheduler: std::sync::OnceLock<mpsc::Sender<BatchSchedulerMsg>>,
    /// Requests this node coordinates whose chain starts and ends here, by
    /// the far run `[a, b)` between their two ends ([`Self::learn_far_run`]):
    /// each forward of theirs carries it to the worker
    /// (`IpcForward::far_run`) and goes direct, never through the batch
    /// scheduler, whose fused forward keeps no hidden state.
    far_runs: DashMap<Uuid, (u32, u32)>,
    /// Item 8 Phase 1: cross-node prefix-cache announcement sink. Set by
    /// `SharedState::new` after the daemon spawns its forwarder task; reader
    /// actors call `try_send` so a slow daemon never backpressures the worker
    /// IPC reader. When unset (e.g. unit tests constructing a bare pool),
    /// inbound `PrefixManifestUpdate` messages are dropped silently.
    prefix_manifest_tx: std::sync::OnceLock<mpsc::Sender<PrefixManifestEvent>>,
    progress_tx: std::sync::OnceLock<mpsc::Sender<ProgressEvent>>,
    /// Item 8 Phase 2b: worker-initiated fetch probes land here. Daemon
    /// drains and responds via `send_prefix_fetch_result`. Unset → drop.
    prefix_probe_tx: std::sync::OnceLock<mpsc::Sender<PrefixProbeEvent>>,
    /// The slowest card allocation probe the workers reported since the owner
    /// was last told (#762) — written by every reader actor, read by the
    /// health monitor through [`Self::slow_card_notice`].
    slow_card: Arc<crate::inference::cuda_pool::SlowCardNotice>,
    /// How fast this node reads a model into memory, from its workers' own
    /// load timings — written by every reader actor, advertised by the health
    /// monitor and priced by the planner through [`Self::load_ms_per_gib`].
    load_rate: Arc<LoadRate>,
    /// The daemon's stop signal, set by `SharedState::new`
    /// ([`Self::watch_daemon_stop`]); unset in a pool built without a daemon.
    daemon_stopping: std::sync::OnceLock<tokio::sync::watch::Receiver<bool>>,
    /// A model's `(fixed_mb, per_layer_mb)` for a test that needs the growth
    /// path to weigh something. The real curve is read off a GGUF header on
    /// disk, which a unit test must not depend on the developer's node for.
    #[cfg(test)]
    pub(crate) test_cost_curve: DashMap<ModelId, (u64, u64)>,
    /// A model's whole-model geometry for a test, in place of its header on
    /// disk — what `footprint_inputs` would read. Same reason as above.
    #[cfg(test)]
    pub(crate) test_footprint_inputs:
        DashMap<ModelId, crate::model::auto_manage::vram::VramFootprintInputs>,
    /// Each layer's routed-expert bytes for a test model, whole model — what
    /// `segment_geometry` would read off the header. Absent = a dense model.
    #[cfg(test)]
    pub(crate) test_expert_bytes: DashMap<ModelId, Vec<u64>>,
    /// Test models whose layers do not all keep a cache of their own (Gemma 4
    /// E2B's shared layers, Qwen 3.5's recurrent ones) — what
    /// `hybrid::run_place` would read off the header.
    #[cfg(test)]
    pub(crate) test_layers_share_caches: dashmap::DashSet<ModelId>,
    /// A test's stand-in for a usable graphics card (`card_in_play`), which a
    /// build without the CUDA feature never has.
    #[cfg(test)]
    pub(crate) test_card_in_play: std::sync::atomic::AtomicBool,
    /// A refusal the next [`Self::generate`] returns without running — a test
    /// of what a caller does with a worker's refusal, with no worker.
    #[cfg(test)]
    pub(crate) test_refuse_next_generate: std::sync::Mutex<Option<SwarmError>>,
}

/// Command into the batch scheduler task.
enum BatchSchedulerMsg {
    Forward {
        fwd: crate::types::LayerForward,
        /// Whose request the step is ([`WorkerHandle::idle_secs_for`]).
        requester: Requester,
        resp_tx: tokio::sync::oneshot::Sender<Result<crate::types::LayerResult, SwarmError>>,
    },
}

/// Is this forward ONE decode step of the base model — what a worker's own
/// published speed is timed on ([`OwnDecodeSpeed`], FUTURE_WORK #3 (f))?
///
/// One position past a prompt pass, counted the way the serve credit counts it
/// ([`crate::inference::tensor_util::positions_carried`]), through the model's
/// own weights: no tensor-parallel share of a layer, no image, no adapter.
/// Whatever ELSE the step asks is the same work for a segment: a check of one
/// position (`spec_logits_requested`, a tail walk) and a rewind before it
/// (`truncate_kv_to`) are how a coordinator speculating with n-grams sends every
/// step that found no guess — the batch path's test ([`forward_is_schedulable`])
/// refuses those, and a chain driven that way was never timed (the
/// `split_rig.sh owntiming` run of 2026-10-18: a peer served 5 such steps and
/// published nothing). A check of several positions is not one step.
pub(crate) fn forward_is_one_decode_step(f: &crate::types::LayerForward) -> bool {
    f.sequence_num != 0
        && f.index_pos != 0
        && f.prompt_cache.is_none()
        && f.prompt_span.is_none()
        && f.image_spans.is_empty()
        && f.draft_parents.is_empty()
        && f.tp_meta.is_none()
        && f.vision_embeddings.is_none()
        && f.adapter_id.is_none()
        && crate::inference::tensor_util::positions_carried(f) == 1
}

/// Can this `LayerForward` share a `BatchForward` message with others? Matches
/// the worker-side `batch_eligible` check: same layer_range + decode-only + no
/// vision/LoRA/spec/TP/pre-embedded/truncate. If any of these trip, we send a
/// single `DaemonMsg::Forward` instead.
fn forward_is_schedulable(f: &crate::types::LayerForward) -> bool {
    if f.sequence_num == 0 || f.index_pos == 0 {
        return false;
    }
    if f.tp_meta.is_some() {
        return false;
    }
    if f.vision_embeddings.is_some() {
        return false;
    }
    if f.adapter_id.is_some() {
        return false;
    }
    if !f.draft_tokens.is_empty() || !f.draft_parents.is_empty() {
        return false;
    }
    if f.spec_logits_requested {
        return false;
    }
    if f.pre_embedded {
        return false;
    }
    if f.truncate_kv_to.is_some() {
        return false;
    }
    // A streamed verify runs in its stream's order, which the batch scheduler
    // does not keep. Every one is a verify too, so this states the reason.
    if f.stream_seq.is_some() {
        return false;
    }
    // A prompt pass that restores a stored prompt (`sequence_num` 0 already
    // excludes it); stated so the batch path's `prompt_cache: _` stays true.
    if f.prompt_cache.is_some() {
        return false;
    }
    // A piece of a prompt pass (also `sequence_num` 0): continues a cache the
    // batch path would not know to keep.
    if f.prompt_span.is_some() {
        return false;
    }
    // A forward reaching into a picture whose rows attend both ways (#115
    // (2b)): its mask is its own, and the batch path builds one causal mask.
    if !f.image_spans.is_empty() {
        return false;
    }
    // A forward asking for a block drafter's rows (#428): the batch path keeps
    // no layer's output.
    if f.block_rows_wanted.is_some() {
        return false;
    }
    true
}

/// Memory a spawn has charged against the shared budget but not yet handed to a
/// worker, released on drop.
///
/// `get_or_spawn` charges `vram_reserved_mb`/`ram_reserved_mb` and only then
/// awaits `spawn_worker`, which starts a subprocess and waits for it to connect
/// (`WORKER_CONNECT_TIMEOUT_SECS` is 30). Release lived in two places, both
/// reached only by the await RETURNING: the `Err` arm gives the charge back,
/// the `Ok` arm hands it to the new `WorkerHandle`. If the enclosing future is
/// dropped or the task aborted while suspended in that await, neither happens —
/// and no `WorkerHandle` was ever inserted, so nothing later reconciles it. The
/// `Err` arm's own comment says what that costs: "Leaving the charge would
/// shrink the budget permanently."
///
/// Two ordinary things drop that future mid-spawn:
///
/// - `pipeline::local_generate::try_local_generate_fastpath` WRAPS
///   `pool.generate(..)` in `cancel::unless_cancelled`, which cancels by
///   dropping. `forward_direct` brackets the same call with
///   `bail_if_cancelled` instead and its comment explains why — "dropping a
///   load half-done abandons a spawning subprocess" — but that rule is a
///   comment, so a file added later did the wrapped version anyway (gotcha
///   #459, reintroduced).
/// - `SwarmMessage::CancelInference` calls `abort_handle().abort()` on the task
///   serving an inbound segment. An external abort drops the future wherever it
///   is suspended, so no in-band checkpoint can defend against it — bracketing
///   cannot help here at all.
///
/// The budget is keyed by model and accumulates, so each leak compounds until
/// the node refuses a model it has room for and only a restart clears it.
struct PendingSpawnCharge<'a> {
    pool: &'a ModelProcessPool,
    model_id: ModelId,
    vram_mb: u64,
    ram_mb: u64,
}

impl PendingSpawnCharge<'_> {
    /// The await returned, so the caller's own `Ok`/`Err` arms own the charge
    /// from here. Only cancellation should reach this guard's `Drop`.
    fn handed_back_to_the_caller(mut self) {
        self.vram_mb = 0;
        self.ram_mb = 0;
    }
}

impl Drop for PendingSpawnCharge<'_> {
    fn drop(&mut self) {
        if self.vram_mb == 0 && self.ram_mb == 0 {
            return;
        }
        tracing::warn!(
            model = %self.model_id,
            vram_mb = self.vram_mb,
            ram_mb = self.ram_mb,
            "A model spawn was abandoned mid-flight — returning the memory it had reserved"
        );
        self.pool.release_vram_charge(&self.model_id, self.vram_mb);
        self.pool.release_ram_charge(&self.model_id, self.ram_mb);
    }
}

